-- ════ BEGIN SECTION S · courses and past exams (sources.md) ════
-- ════════════════════════════════════════════════════════════════════════
--  SECTION S · COURSES AND PAST EXAMS   (docs/study/sources.md, Part B)
--  Part 8 of the SQL Editor's parts. Every change to an object of an
--  earlier section is a create or replace, or an alter … if not exists,
--  made here; nothing above is edited. Re-runnable.
-- ════════════════════════════════════════════════════════════════════════

-- ── S 1 · courses ──
-- A course is the existing course text of lectures and exams, matched by
-- study_private.course_key(course) (below). The row gives it an id (for
-- addresses and settings: the exam date, its length) and nothing moves: no lecture or exam gets a
-- course_id, and the lecture's text stays the truth (courseStyle, s=c.<text>,
-- QuizSetup and study_plans.courses[] keep reading it). Renaming or merging
-- rewrites the text everywhere at once (study_course_rename / _merge).
--
-- The key: study_private.course_key(text), the one normaliser every match
-- of S uses, the same as shared/study/courseKey.ts: direction and
-- zero-width marks pasted from PDFs (U+200B–U+200F, U+202A–U+202E, U+2060,
-- U+2066–U+2069) removed, every run of white space (the characters
-- JavaScript's \s matches: NBSP, tabs, U+2000–U+200A, U+3000…) one space,
-- trimmed, in lower case.
create or replace function study_private.course_key(p_name text)
returns text language sql immutable parallel safe as $$
  select lower(btrim(regexp_replace(
           regexp_replace(coalesce(p_name, ''), '[\u200B-\u200F\u202A-\u202E\u2060\u2066-\u2069]', '', 'g'),
           '[\t\n\u000B\f\r \u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+', ' ', 'g')))
$$;
revoke all on function study_private.course_key(text) from public;

create table if not exists public.study_courses (
  id           uuid        primary key default gen_random_uuid(),
  group_id     uuid        not null references public.study_groups (id) on delete cascade,
  name         text        not null check (char_length(btrim(name)) between 1 and 120),
  name_key     text        generated always as (study_private.course_key(name)) stored,
  exam_date    date        check (exam_date between date '2000-01-01' and date '2100-12-31'),
  exam_minutes int         check (exam_minutes between 10 and 600),
  exam_n       int         check (exam_n between 5 and 300),
  created_by   uuid        default auth.uid() references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (group_id, name_key)
);

-- A table made by an earlier S 1 (its key was lower(btrim(name))): the rows
-- the new key makes one keep the first made, and the key is made again.
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'study_courses' and column_name = 'name_key'
                and generation_expression not like '%course_key%') then
    delete from public.study_courses a using public.study_courses b
     where a.group_id = b.group_id and study_private.course_key(a.name) = study_private.course_key(b.name)
       and (b.created_at, b.id) < (a.created_at, a.id);
    alter table public.study_courses drop column name_key;
    alter table public.study_courses add column name_key text generated always as (study_private.course_key(name)) stored;
    alter table public.study_courses add constraint study_courses_group_id_name_key_key unique (group_id, name_key);
  end if;
end $$;

alter table public.study_courses enable row level security;
drop policy if exists "study courses read" on public.study_courses;
create policy "study courses read" on public.study_courses for select using (public.study_is_member(group_id));
revoke all on public.study_courses from anon, authenticated;
grant select on public.study_courses to authenticated;

-- The switch (on: phase 1 spends nothing new; VITE_STUDY_COURSES shows it).
insert into study_private.features (name, enabled) values ('courses', true) on conflict (name) do nothing;

-- Backfill: one row per distinct study_private.course_key(course) of the lectures and
-- exams, named as it was first written. Deleted lectures count too (a
-- restored one finds its course). Returns how many rows it made (0 on a
-- second run).
create or replace function study_private.course_backfill()
returns int language plpgsql volatile security definer set search_path = public as $$
declare n int;
begin
  insert into public.study_courses (group_id, name, created_by, created_at)
  select distinct on (x.group_id, study_private.course_key(x.course)) x.group_id, btrim(x.course), x.created_by, x.created_at
    from (select l.group_id, l.course, l.created_by, l.created_at from public.study_lectures l where study_private.course_key(l.course) <> ''
          union all
          select e.group_id, e.course, e.created_by, e.created_at from public.study_exams e where study_private.course_key(e.course) <> '') x
   order by x.group_id, study_private.course_key(x.course), x.created_at
  on conflict (group_id, name_key) do nothing;
  get diagnostics n = row_count;
  return n;
end;
$$;
revoke all on function study_private.course_backfill() from public;
do $$ begin perform study_private.course_backfill(); end $$;

-- One change to a group's courses at a time: the trigger, upsert, rename and
-- merge take this lock first (before any course row), so a rename racing an
-- upsert of the same name waits instead of failing on the unique key, and
-- two opposite merges run one after the other instead of deadlocking.
create or replace function study_private.course_lock(p_group uuid)
returns void language sql volatile as $$
  select pg_advisory_xact_lock(hashtext('study_course:' || p_group::text))
$$;
revoke all on function study_private.course_lock(uuid) from public;

-- A lecture or exam whose course has no row yet makes it (a course merged
-- away and then typed again comes back as a new row). A lecture or exam
-- moved to another course leaves its old course; when nothing of the group
-- has that course's text any more (deleted lectures count: a restored one
-- finds its course) and the course has no settings, its row goes, so the
-- lists do not keep an empty course.
create or replace function study_private.course_ensure()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  k_new text := study_private.course_key(new.course);
  k_old text := case when tg_op = 'UPDATE' then study_private.course_key(old.course) else '' end;
begin
  if k_new = '' and (k_old = '' or k_old = k_new) then return null; end if;
  perform study_private.course_lock(new.group_id);
  if k_new <> '' then
    insert into public.study_courses (group_id, name, created_by)
    values (new.group_id, btrim(new.course), auth.uid())
    on conflict (group_id, name_key) do update set deleted_at = null where public.study_courses.deleted_at is not null;
  end if;
  if k_old <> '' and k_old <> k_new then
    delete from public.study_courses c
     where c.group_id = old.group_id and c.name_key = k_old
       and c.exam_date is null and c.exam_minutes is null and c.exam_n is null
       and not exists (select 1 from public.study_lectures l where l.group_id = old.group_id and study_private.course_key(l.course) = k_old)
       and not exists (select 1 from public.study_exams e where e.group_id = old.group_id and study_private.course_key(e.course) = k_old);
  end if;
  return null;
end;
$$;
revoke all on function study_private.course_ensure() from public;
drop trigger if exists study_course_ensure on public.study_lectures;
create trigger study_course_ensure after insert or update of course on public.study_lectures
  for each row execute function study_private.course_ensure();
drop trigger if exists study_course_ensure on public.study_exams;
create trigger study_course_ensure after insert or update of course on public.study_exams
  for each row execute function study_private.course_ensure();

-- The caller's course, locked: 'course not found' unless she is a member of
-- its group and it is not deleted; 'off' while the switch is off.
create or replace function study_private.course_for(p_course uuid)
returns public.study_courses language plpgsql volatile security definer set search_path = public as $$
declare c public.study_courses;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course for update;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then
    raise exception 'course not found';
  end if;
  if not study_private.feature_on('courses') then raise exception 'off'; end if;
  return c;
end;
$$;
revoke all on function study_private.course_for(uuid) from public;

-- 'bad date', 'bad minutes', 'bad questions': the settings' ranges.
create or replace function study_private.course_settings_ok(p_exam_date date, p_minutes int, p_n int)
returns void language plpgsql immutable as $$
begin
  if p_exam_date is not null and p_exam_date not between date '2000-01-01' and date '2100-12-31' then raise exception 'bad date'; end if;
  if p_minutes is not null and p_minutes not between 10 and 600 then raise exception 'bad minutes'; end if;
  if p_n is not null and p_n not between 5 and 300 then raise exception 'bad questions'; end if;
end;
$$;
revoke all on function study_private.course_settings_ok(date, int, int) from public;

-- Every course text in the group that is p_from_key becomes p_to: the
-- lectures (deleted ones too), the exams and the members' plans (each plan's
-- list stays sorted and without repeats, as study_plan_save keeps it).
create or replace function study_private.course_retext(p_group uuid, p_from_key text, p_to text)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  update public.study_lectures l set course = p_to
   where l.group_id = p_group and study_private.course_key(l.course) = p_from_key and l.course is distinct from p_to;
  update public.study_exams e set course = p_to
   where e.group_id = p_group and study_private.course_key(e.course) = p_from_key and e.course is distinct from p_to;
  update public.study_plans p
     set courses = (select coalesce(array_agg(distinct x order by x), '{}')
                      from (select case when study_private.course_key(c) = p_from_key then p_to else btrim(c) end x from unnest(p.courses) c) y),
         updated_at = now()
   where p.group_id = p_group and exists (select 1 from unnest(p.courses) c where study_private.course_key(c) = p_from_key);
end;
$$;
revoke all on function study_private.course_retext(uuid, text, text) from public;

-- "קורס חדש" (or the course of a batch upload): the group's course of that
-- name, made when missing (a deleted one comes back); the settings given
-- (not null) are saved. Returns its id. 'not signed in', 'group not found',
-- 'off', 'bad name', and the settings' errors.
create or replace function public.study_course_upsert(p_group uuid, p_name text, p_exam_date date default null,
  p_minutes int default null, p_n int default null)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  nm text := btrim(coalesce(p_name, ''));
  v  uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not coalesce(public.study_is_member(p_group), false) then raise exception 'group not found'; end if;
  if not study_private.feature_on('courses') then raise exception 'off'; end if;
  if char_length(nm) not between 1 and 120 or study_private.course_key(nm) = '' then raise exception 'bad name'; end if;
  perform study_private.course_settings_ok(p_exam_date, p_minutes, p_n);
  perform study_private.course_lock(p_group);
  insert into public.study_courses as c (group_id, name, exam_date, exam_minutes, exam_n, created_by)
  values (p_group, nm, p_exam_date, p_minutes, p_n, auth.uid())
  on conflict (group_id, name_key) do update
     set deleted_at = null,
         exam_date = coalesce(excluded.exam_date, c.exam_date),
         exam_minutes = coalesce(excluded.exam_minutes, c.exam_minutes),
         exam_n = coalesce(excluded.exam_n, c.exam_n)
  returning c.id into v;
  return v;
end;
$$;

-- The course page's sheet: the exam date, its minutes and its number of
-- questions, each null to clear. 'course not found', 'off', the settings' errors.
create or replace function public.study_course_set(p_course uuid, p_exam_date date, p_minutes int, p_n int)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  perform study_private.course_for(p_course);
  perform study_private.course_settings_ok(p_exam_date, p_minutes, p_n);
  update public.study_courses c set exam_date = p_exam_date, exam_minutes = p_minutes, exam_n = p_n where c.id = p_course;
end;
$$;

-- "לשנות שם": the course and every text of it (lectures, exams, plans), in
-- one transaction. A name that is another course of the group: 'exists'
-- ("לאחד קורסים" is the way). 'course not found', 'off', 'bad name'.
create or replace function public.study_course_rename(p_course uuid, p_name text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  c  public.study_courses;
  g  uuid;
  nm text := btrim(coalesce(p_name, ''));
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  -- The group's lock before the row's (course_lock), then the row, read again.
  select x.group_id into g from public.study_courses x where x.id = p_course;
  if g is not null then perform study_private.course_lock(g); end if;
  c := study_private.course_for(p_course);
  if char_length(nm) not between 1 and 120 or study_private.course_key(nm) = '' then raise exception 'bad name'; end if;
  if exists (select 1 from public.study_courses x where x.group_id = c.group_id and x.name_key = study_private.course_key(nm) and x.id <> c.id) then
    raise exception 'exists';
  end if;
  update public.study_courses x set name = nm where x.id = c.id;
  perform study_private.course_retext(c.group_id, c.name_key, nm);
end;
$$;

-- "לאחד קורסים": p_from's lectures, exams and plans move to p_into's name,
-- its settings fill what p_into lacks, and its row goes. 'course not found',
-- 'off', 'same course'.
create or replace function public.study_course_merge(p_from uuid, p_into uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  f public.study_courses;
  t public.study_courses;
  g uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  -- The group's lock first (course_lock): two opposite merges wait for each
  -- other, and the second finds its course gone ('course not found').
  select x.group_id into g from public.study_courses x where x.id = p_into;
  if g is not null then perform study_private.course_lock(g); end if;
  f := study_private.course_for(p_from);
  t := study_private.course_for(p_into);
  if f.id = t.id then raise exception 'same course'; end if;
  if f.group_id <> t.group_id then raise exception 'course not found'; end if;
  update public.study_courses x
     set exam_date = coalesce(x.exam_date, f.exam_date), exam_minutes = coalesce(x.exam_minutes, f.exam_minutes),
         exam_n = coalesce(x.exam_n, f.exam_n)
   where x.id = t.id;
  delete from public.study_courses x where x.id = f.id;
  perform study_private.course_retext(t.group_id, f.name_key, t.name);
end;
$$;

-- The course page: its settings, days left (Israel time), its lectures
-- (count, ready), its past exams with their states (none until phase 2),
-- and how many of its questions can be practised now ("(184)": the
-- questions of its lectures a session may ask, study_session_counts' rule:
-- active, keyed, not hidden by two flags, not marked by a correction). A
-- build without VITE_STUDY_QTYPES also leaves out the new question types,
-- so its session can ask fewer. 'course not found', 'off'.
create or replace function public.study_course_overview(p_course uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c     public.study_courses;
  today date := (now() at time zone 'Asia/Jerusalem')::date;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then
    raise exception 'course not found';
  end if;
  if not study_private.feature_on('courses') then raise exception 'off'; end if;
  return jsonb_build_object(
    'id', c.id, 'name', c.name, 'exam_date', c.exam_date,
    'days_left', case when c.exam_date is not null then c.exam_date - today end,
    'exam_minutes', c.exam_minutes, 'exam_n', c.exam_n,
    'lectures', (select count(*) from public.study_lectures l
                  where l.group_id = c.group_id and l.deleted_at is null and study_private.course_key(l.course) = c.name_key),
    'ready', (select count(*) from public.study_lectures l
               where l.group_id = c.group_id and l.deleted_at is null and l.status = 'ready' and study_private.course_key(l.course) = c.name_key),
    -- S 2: an exam's moed, length and items, and how many it printed (the
    -- simulation's pace); a deleted exam is left out, and so is an upload
    -- that stopped more than a day ago (plpgsql binds the S 2 columns when
    -- it runs, after S 2 made them).
    'exams', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'title', e.title, 'year', e.year, 'status', e.status,
                                                           'moed', e.moed, 'minutes', e.minutes, 'key_source', e.key_source,
                                                           'hidden', e.hide_from_profile, 'created_at', e.created_at,
                                                           'questions', (select count(*) from public.study_questions q
                                                                          where q.exam_id = e.id and q.retired_at is null),
                                                           'printed', study_private.exam_printed(e.id))
                                        order by e.year desc nulls last, e.created_at desc), '[]'::jsonb)
                from public.study_exams e where e.group_id = c.group_id and study_private.course_key(e.course) = c.name_key
                 and e.deleted_at is null and not study_private.exam_stale(e)),
    'questions', (select count(*) from public.study_questions q join public.study_lectures l on l.id = q.lecture_id
                   where l.group_id = c.group_id and l.deleted_at is null and study_private.course_key(l.course) = c.name_key
                     and q.retired_at is null and q.hidden_at is null and q.stale_at is null and q.has_key));
end;
$$;

-- The library's course links: every course of the group with its lecture
-- and exam counts (deleted lectures left out), by name.
create or replace function public.study_courses_of(p_group uuid)
returns table (id uuid, name text, name_key text, exam_date date, exam_minutes int, exam_n int, lectures int, exams int)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not coalesce(public.study_is_member(p_group), false) then raise exception 'group not found'; end if;
  return query
  select c.id, c.name, c.name_key, c.exam_date, c.exam_minutes, c.exam_n,
         (select count(*)::int from public.study_lectures l
           where l.group_id = c.group_id and l.deleted_at is null and study_private.course_key(l.course) = c.name_key),
         (select count(*)::int from public.study_exams e where e.group_id = c.group_id and study_private.course_key(e.course) = c.name_key
           and e.deleted_at is null and not study_private.exam_stale(e))   -- S 2's column, bound when it runs
    from public.study_courses c
   where c.group_id = p_group and c.deleted_at is null
   order by c.name_key;
end;
$$;

-- ── A round over several lectures (sources.md B6.7): one request per
-- lecture, as before, sharing a plan id the phone makes. lecture_id stays
-- not null; study_request_create is unchanged.
alter table public.study_question_requests add column if not exists plan_id uuid;
create index if not exists study_question_requests_plan on public.study_question_requests (plan_id) where plan_id is not null;

-- After study_request_create (the op, with the key and the member's token):
-- puts the caller's request in the round p_plan. A round stays in one group,
-- touches at most 5 lectures, and asks at least 4 questions of each.
-- 'forbidden', 'not signed in', 'request not found', 'bad plan' (another
-- group's, or the request is in another round), 'round full', 'too few questions'.
create or replace function public.study_request_plan(p_request uuid, p_plan uuid, p_key text default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  r public.study_question_requests;
  n int;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_plan is null then raise exception 'bad plan'; end if;
  perform pg_advisory_xact_lock(hashtext('study_plan_round:' || p_plan::text));
  select * into r from public.study_question_requests x where x.id = p_request for update;
  if not found or r.created_by is distinct from auth.uid() or not coalesce(public.study_is_member(r.group_id), false) then
    raise exception 'request not found';
  end if;
  if r.plan_id is not null and r.plan_id <> p_plan then raise exception 'bad plan'; end if;
  if exists (select 1 from public.study_question_requests x where x.plan_id = p_plan and x.group_id <> r.group_id) then
    raise exception 'bad plan';
  end if;
  if r.count < 4 then raise exception 'too few questions'; end if;
  select count(distinct x.lecture_id)::int into n from public.study_question_requests x
   where x.plan_id = p_plan and x.lecture_id <> r.lecture_id;
  if n >= 5 then raise exception 'round full'; end if;
  update public.study_question_requests x set plan_id = p_plan where x.id = r.id;
  return n + 1;
end;
$$;

-- The op's call for a lecture of a round: study_request_create and then
-- study_request_plan, in one transaction, so a refused link ('round full',
-- 'bad plan', 'too few questions') leaves no request and no batches behind
-- (no round number of the lecture used up). The round's lock is taken
-- before the request is made: two phones adding the 5th and the 6th
-- lecture at once run one after the other, and the second is refused.
-- Each row as study_request_create's, with the round's lectures so far.
create or replace function public.study_request_create_in_plan(p_lecture uuid, p_request jsonb, p_batches jsonb, p_plan uuid,
  p_key text default null)
returns table (request_id uuid, round int, batch_id uuid, part_idx int, seq int, wanted int, lectures int)
language plpgsql volatile security definer set search_path = public as $$
declare
  made jsonb;
  n    int;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if p_plan is null then raise exception 'bad plan'; end if;
  perform pg_advisory_xact_lock(hashtext('study_plan_round:' || p_plan::text));
  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into made
    from public.study_request_create(p_lecture, p_request, p_batches, p_key) x;
  if jsonb_array_length(made) = 0 then return; end if;
  n := public.study_request_plan((made->0->>'request_id')::uuid, p_plan, p_key);
  return query
  select (e->>'request_id')::uuid, (e->>'round')::int, (e->>'batch_id')::uuid, (e->>'part_idx')::int,
         (e->>'seq')::int, (e->>'wanted')::int, n
    from jsonb_array_elements(made) e;
end;
$$;

revoke all on function public.study_course_upsert(uuid, text, date, int, int), public.study_course_set(uuid, date, int, int),
  public.study_course_rename(uuid, text), public.study_course_merge(uuid, uuid), public.study_course_overview(uuid),
  public.study_courses_of(uuid), public.study_request_plan(uuid, uuid, text),
  public.study_request_create_in_plan(uuid, jsonb, jsonb, uuid, text)
  from public, anon;
grant execute on function public.study_course_upsert(uuid, text, date, int, int), public.study_course_set(uuid, date, int, int),
  public.study_course_rename(uuid, text), public.study_course_merge(uuid, uuid), public.study_course_overview(uuid),
  public.study_courses_of(uuid)
  to authenticated;
-- Both need the key inside; the grant only lets the op's call reach them.
grant execute on function public.study_request_plan(uuid, uuid, text),
  public.study_request_create_in_plan(uuid, jsonb, jsonb, uuid, text) to authenticated;

insert into study_private.schema_sections (section, version) values ('S', 1)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ── S 2 · past exams (sources.md B1 S 2, B2, B6.2, B7, B9) ──
-- An exam is uploaded as page pictures (a PDF's pages or photos, 1500 px)
-- with the text lines a PDF had, read on the server in units of 4 pages
-- (study_private.exam_jobs, the worker's /api/study/work {exam}), its key
-- sheet merged by number, and the items left without a key solved and
-- marked "תשובה מוצעת · לא נבדקה". A simulation (study_mocks) replays an
-- exam against one clock. Everything is behind the switch 'exams' (off
-- until Yoad turns it on) and VITE_STUDY_EXAMS (S 2).
--
-- The pages are rows of study_exam_pages, not study_exams.pages: section Q
-- adds its 60-page check to that column again on every run of the file, and
-- an exam may now have 120 pages. New exams leave pages '[]'.

-- study_exams: the moed, the length, the key pages, the open questions
-- skipped, "לא לכלול בחישוב הנושאים", the soft delete, "לנסות שוב" a day.
alter table public.study_exams
  add column if not exists moed              text,
  add column if not exists minutes           int,
  add column if not exists n_questions       int,
  add column if not exists key_pages         int[]       not null default '{}',
  add column if not exists skipped_open      int         not null default 0,
  add column if not exists hide_from_profile boolean     not null default false,
  add column if not exists deleted_at        timestamptz,
  add column if not exists retries           int         not null default 0,
  add column if not exists retry_day         date;
do $$
declare c record;
begin
  if not exists (select 1 from pg_constraint where conname = 'study_exams_s2_x') then
    alter table public.study_exams add constraint study_exams_s2_x check (
      (moed is null or char_length(moed) <= 20) and (minutes is null or minutes between 10 and 600)
      and (n_questions is null or n_questions between 0 and 500) and skipped_open between 0 and 500
      and cardinality(key_pages) <= 120 and retries between 0 and 100);
  end if;
  -- Q's status list gains 'uploading' and 'linking' (the inline check is found by its definition).
  for c in select x.conname from pg_constraint x
            where x.conrelid = 'public.study_exams'::regclass and x.contype = 'c' and x.conname <> 'study_exams_status_x'
              and pg_get_constraintdef(x.oid) like '%reading%' loop
    execute format('alter table public.study_exams drop constraint %I', c.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conname = 'study_exams_status_x') then
    alter table public.study_exams add constraint study_exams_status_x
      check (status in ('new', 'uploading', 'reading', 'linking', 'ready', 'failed'));
  end if;
end $$;
-- Members no longer move an exam's state or key mode by hand (Q granted it; nothing used it).
revoke update (key_source, status, error) on public.study_exams from authenticated;

-- One row per page: { n, path "<group>/exams/<exam>/p<n>.jpg", w, h, the
-- PDF's text lines (none for a scan), is_key: a page of the separate key }.
create table if not exists public.study_exam_pages (
  exam_id uuid     not null references public.study_exams (id) on delete cascade,
  n       smallint not null check (n between 1 and 120),
  path    text     not null check (char_length(path) <= 200),
  w       int      not null check (w between 1 and 6000),
  h       int      not null check (h between 1 and 6000),
  lines   text[]   not null default '{}' check (cardinality(lines) <= 400),
  is_key  boolean  not null default false,
  primary key (exam_id, n)
);

-- study_questions: an exam item's reading (parse_conf 1-3, the page it
-- starts on) and phase 3's links, repeats and twins.
alter table public.study_questions
  add column if not exists parse_conf smallint,
  add column if not exists page       smallint,
  add column if not exists covered    boolean,
  add column if not exists linked_at  timestamptz,
  add column if not exists repeat_of  uuid references public.study_questions (id) on delete set null,
  add column if not exists twin_of    uuid references public.study_questions (id) on delete set null;
do $$
declare c record;
begin
  if not exists (select 1 from pg_constraint where conname = 'study_questions_s2_x') then
    alter table public.study_questions add constraint study_questions_s2_x
      check ((parse_conf is null or parse_conf between 1 and 3) and (page is null or page between 1 and 120));
  end if;
  -- The figure: a slide's picture (fig:N-K) or, now, a box of an exam page,
  -- pg:<page>:<x>,<y>,<w>,<h> in thousandths of the page.
  for c in select x.conname from pg_constraint x
            where x.conrelid = 'public.study_questions'::regclass and x.contype = 'c' and x.conname <> 'study_questions_figure_x'
              and pg_get_constraintdef(x.oid) like '%fig:%' loop
    execute format('alter table public.study_questions drop constraint %I', c.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conname = 'study_questions_figure_x') then
    alter table public.study_questions add constraint study_questions_figure_x check (
      figure = '' or figure ~ '^fig:[0-9]{1,4}-[0-9]{1,3}$'
      or figure ~ '^pg:[0-9]{1,3}:[0-9]{1,4},[0-9]{1,4},[0-9]{1,4},[0-9]{1,4}$');
  end if;
end $$;
-- One item per number of an exam: the worker's save is an upsert by it.
create unique index if not exists study_questions_exam_no on public.study_questions (exam_id, exam_no)
  where exam_id is not null and exam_no is not null;

-- Where an exam item's key came from (hidden with the key: a solved key
-- must not show before an answer): the exam's marks, the key sheet, solved
-- by the model (key_conf 1-3), or a member. Only a member confirms.
alter table public.study_question_keys
  add column if not exists key_origin text,
  add column if not exists key_conf   smallint;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'study_question_keys_origin_x') then
    alter table public.study_question_keys add constraint study_question_keys_origin_x
      check ((key_origin is null or key_origin in ('exam', 'sheet', 'solved', 'member')) and (key_conf is null or key_conf between 1 and 3));
  end if;
end $$;
-- Keys of exam items made before S 2: a member's, or the exam's.
update public.study_question_keys k
   set key_origin = case when k.key_by is not null then 'member' else 'exam' end
  from public.study_questions q
 where q.id = k.question_id and q.source = 'exam' and k.key_origin is null and (k.answer is not null or k.seq is not null);

-- The key log: every member change of an exam item's key and its undo
-- (written only by study_set_exam_key and study_exam_key_undo).
create table if not exists public.study_exam_key_log (
  id          bigint      generated always as identity primary key,
  question_id uuid        not null references public.study_questions (id) on delete cascade,
  exam_id     uuid        not null references public.study_exams (id) on delete cascade,
  old         smallint,
  new         smallint,
  origin_old  text,
  origin_new  text,
  conf_old    smallint,                                                     -- a solved key's confidence before (restored by an undo)
  by_old      uuid        references auth.users (id) on delete set null,   -- who had keyed it before (restored by an undo)
  undo_of     bigint      references public.study_exam_key_log (id) on delete set null,
  member_id   uuid        references auth.users (id) on delete set null default auth.uid(),
  at          timestamptz not null default now()
);
create index if not exists study_exam_key_log_q on public.study_exam_key_log (question_id, id);
-- Fixes of a badly read item: its question, case text, an option or a prompt.
create table if not exists public.study_exam_item_log (
  id          bigint      generated always as identity primary key,
  question_id uuid        not null references public.study_questions (id) on delete cascade,
  exam_id     uuid        not null references public.study_exams (id) on delete cascade,
  field       text        not null check (field in ('question', 'vignette', 'option', 'prompt')),
  idx         smallint,
  old         text        not null,
  new         text        not null,
  member_id   uuid        references auth.users (id) on delete set null default auth.uid(),
  at          timestamptz not null default now()
);
create index if not exists study_exam_item_log_q on public.study_exam_item_log (question_id, id);

-- Simulations: a shared definition (the questions in their order, the
-- minutes) and each member's own attempt and clock. The picks stay on the
-- attempt until it is submitted (an answer can change, as on paper); then
-- each counted pick becomes a study_answers row, mode 'exam', attempt_id.
create table if not exists public.study_mocks (
  id           uuid        primary key default gen_random_uuid(),
  group_id     uuid        not null references public.study_groups (id) on delete cascade,
  course_id    uuid        references public.study_courses (id) on delete set null,
  kind         text        not null check (kind in ('exam', 'mixed', 'new')),
  exam_id      uuid        references public.study_exams (id) on delete cascade,
  question_ids uuid[]      not null check (cardinality(question_ids) between 1 and 150),
  minutes      int         not null check (minutes between 1 and 600),
  spec         jsonb       not null default '{}'::jsonb,
  created_by   uuid        default auth.uid() references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);
create table if not exists public.study_mock_attempts (
  id          uuid        primary key default gen_random_uuid(),
  mock_id     uuid        not null references public.study_mocks (id) on delete cascade,
  member_id   uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  started_at  timestamptz not null default now(),
  deadline    timestamptz not null,
  finished_at timestamptz,
  auto        boolean     not null default false,                  -- submitted by the clock
  position    int         not null default 0 check (position between 0 and 149),
  flagged     int[]       not null default '{}' check (cardinality(flagged) <= 150),
  picks       jsonb       not null default '{}'::jsonb,              -- question id → {c, cs, ms}
  score       jsonb
);
create index if not exists study_mock_attempts_mine on public.study_mock_attempts (member_id, mock_id, started_at desc);
alter table public.study_answers add column if not exists attempt_id uuid references public.study_mock_attempts (id) on delete set null;
create index if not exists study_answers_attempt on public.study_answers (attempt_id) where attempt_id is not null;

-- ── The exam queue (private: no grants, the schema is not exposed) ──
-- One row per unit: 'read' (up to 4 pages and the next one as context),
-- 'key' (the key sheet's pages), 'solve' (up to 20 items left without a
-- key; not in B1's list: the solve is its own unit until phase 3's link
-- units solve with the slides); 'link', 'topics', 'explain_all' and
-- 'output' are later phases'. range: {pages:[n], next:n|null, reread} or
-- {items:[question ids]}.
create table if not exists study_private.exam_jobs (
  id          uuid          primary key default gen_random_uuid(),
  group_id    uuid          not null references public.study_groups (id) on delete cascade,
  course_id   uuid          references public.study_courses (id) on delete set null,
  exam_id     uuid          references public.study_exams (id) on delete cascade,
  kind        text          not null check (kind in ('read', 'key', 'solve', 'link', 'topics', 'explain_all', 'output')),
  range       jsonb         not null default '{}'::jsonb,
  status      text          not null default 'pending' check (status in ('pending', 'running', 'done', 'failed')),
  lease_id    uuid,
  lease_until timestamptz,
  attempts    int           not null default 0,
  retry_at    timestamptz,
  error       text,
  skipped     int           not null default 0,                     -- a read unit's open questions
  repeats     int           not null default 0,                     -- a read unit's items whose number another page already had (not saved)
  cost_usd    numeric(10,5) not null default 0,
  created_at  timestamptz   not null default now(),
  updated_at  timestamptz   not null default now()
);
create index if not exists exam_jobs_exam on study_private.exam_jobs (exam_id, status);
create index if not exists exam_jobs_live on study_private.exam_jobs (group_id) where status = 'running';
-- Per exam: the pages' signed links (48 h, signed by the member who
-- uploaded or retried: the worker has no Storage access of its own) and the
-- kicks, as study_private.jobs keeps them for lectures.
create table if not exists study_private.exam_queue (
  exam_id           uuid        primary key references public.study_exams (id) on delete cascade,
  group_id          uuid        not null references public.study_groups (id) on delete cascade,
  urls              jsonb       not null default '{}'::jsonb,
  urls_until        timestamptz,
  queued_by         uuid        references auth.users (id) on delete set null,
  queued_at         timestamptz not null default now(),
  last_kick_at      timestamptz,
  kicks_since_claim int         not null default 0
);
-- A key sheet's answers by number, kept until the item is read (the key
-- unit may finish before the read units) and applied by every save.
create table if not exists study_private.exam_sheet_keys (
  exam_id uuid       not null references public.study_exams (id) on delete cascade,
  exam_no int        not null check (exam_no between 1 and 500),
  answer  smallint   check (answer between 0 and 5),
  seq     smallint[] check (seq is null or cardinality(seq) between 2 and 6),
  state   text,      -- "בוטלה": the item is retired; 'several' answers accepted: the first is a suggested one (exam_sheet_keys_state_x)
  primary key (exam_id, exam_no)
);
-- Columns added after S 2's first draft (a database that ran it keeps its tables).
alter table study_private.exam_jobs add column if not exists repeats int not null default 0;
alter table study_private.exam_sheet_keys add column if not exists state text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'exam_sheet_keys_state_x') then
    alter table study_private.exam_sheet_keys add constraint exam_sheet_keys_state_x check (state is null or state in ('cancelled', 'several'));
  end if;
end $$;

-- Writers and exam units holding a live lease in a group: the writer's
-- (section W's, unchanged) plus the exam units', so summaries and exams
-- share the three of a group (B1: study_claim_exam counts both queues).
create or replace function study_private.group_live(p_group uuid)
returns int language sql stable security definer set search_path = public as $$
  select ((select count(*) from public.study_sections s join public.study_lectures l on l.id = s.lecture_id
            where l.group_id = p_group and s.status = 'writing'
              and coalesce(s.lease_until, s.updated_at + interval '6 minutes') > now())
        + (select count(*) from public.study_recording_notes n join public.study_lectures l on l.id = n.lecture_id
            where l.group_id = p_group and n.status = 'writing' and n.lease_until > now())
        + (select count(*) from public.study_lectures l
            where l.group_id = p_group and l.status = 'outlining'
              and coalesce(l.lease_until, l.updated_at + interval '3 minutes') > now())
        + (select count(*) from study_private.exam_jobs j
            where j.group_id = p_group and j.status = 'running' and j.lease_until > now()))::int
$$;

-- A unit that will still run: pending, holding a lease, or failed with a retry time.
create or replace function study_private.exam_job_active(j study_private.exam_jobs)
returns boolean language sql stable as $$
  select j.status in ('pending', 'running') or (j.status = 'failed' and j.attempts < 4 and j.retry_at is not null)
$$;

-- How many questions the exam printed, as far as its reading knows: the
-- items kept, the open questions skipped and the repeated numbers not saved
-- (the simulation's clock is the exam's minutes for all of them).
create or replace function study_private.exam_printed(p_exam uuid)
returns int language sql stable security definer set search_path = public as $$
  select (select count(*) from public.study_questions q where q.exam_id = p_exam and q.retired_at is null)::int
       + coalesce((select e.skipped_open from public.study_exams e where e.id = p_exam), 0)
       + coalesce((select sum(j.repeats) from study_private.exam_jobs j
                    where j.exam_id = p_exam and j.kind = 'read'
                      and not coalesce((j.range ->> 'reread')::boolean, false)), 0)::int
$$;

-- An upload that stopped more than a day ago: left out of the course's
-- list and counts (its pages may stay; nothing reads them).
create or replace function study_private.exam_stale(e public.study_exams)
returns boolean language sql stable as $$
  select e.status = 'uploading' and coalesce(e.updated_at, e.created_at) < now() - interval '1 day'
$$;

-- How many units a group may run at once, summaries and exams together:
-- three, or two while a lecture of the group waits to be written (summaries
-- keep priority). The claim and the sweeper both ask here, so the sweeper
-- never kicks for a unit the claim would refuse.
create or replace function study_private.exam_cap(p_group uuid)
returns int language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from study_private.jobs jb join public.study_lectures l on l.id = jb.lecture_id
                            where l.group_id = p_group and study_private.waiting(jb.lecture_id)) then 2 else 3 end
$$;

-- An exam item without a key: a one-answer item's answer, a set item's seq.
create or replace function study_private.exam_unkeyed(p_question uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select not exists (select 1 from public.study_question_keys k where k.question_id = p_question
                       and (k.answer is not null or k.seq is not null))
$$;


-- After each unit: when no read or key unit will run any more, the items
-- left without a key are queued to be solved (20 a unit, each item once);
-- when nothing will run, the exam is ready (or failed: no item at all).
create or replace function study_private.exam_advance(p_exam uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  e public.study_exams;
  ids uuid[];
  k int := 0;
begin
  select * into e from public.study_exams x where x.id = p_exam for update;
  if not found or e.status not in ('reading', 'linking', 'ready', 'failed') then return; end if;
  update public.study_exams x
     set skipped_open = least(500, coalesce((select sum(j.skipped) from study_private.exam_jobs j
                                              where j.exam_id = p_exam and j.kind = 'read' and j.status = 'done'
                                                and not coalesce((j.range ->> 'reread')::boolean, false)), 0)),
         n_questions = (select count(*) from public.study_questions q where q.exam_id = p_exam and q.retired_at is null)
   where x.id = p_exam;
  if not exists (select 1 from study_private.exam_jobs j
                  where j.exam_id = p_exam and j.kind in ('read', 'key') and study_private.exam_job_active(j)) then
    select array_agg(q.id order by q.exam_no) into ids
      from public.study_questions q
     where q.exam_id = p_exam and q.retired_at is null and study_private.exam_unkeyed(q.id)
       and not exists (select 1 from study_private.exam_jobs j
                        where j.exam_id = p_exam and j.kind = 'solve' and j.range -> 'items' ? q.id::text);
    while ids is not null and k < cardinality(ids) loop
      insert into study_private.exam_jobs (group_id, course_id, exam_id, kind, range)
      select e.group_id, (select c.id from public.study_courses c
                           where c.group_id = e.group_id and c.name_key = study_private.course_key(e.course)),
             p_exam, 'solve', jsonb_build_object('items', to_jsonb(ids[k + 1 : k + 20]));
      k := k + 20;
    end loop;
  end if;
  if exists (select 1 from study_private.exam_jobs j where j.exam_id = p_exam and study_private.exam_job_active(j)) then
    update public.study_exams set status = 'reading', updated_at = now() where id = p_exam and status <> 'reading';
  else
    update public.study_exams x
       set status = case when x.n_questions > 0 then 'ready' else 'failed' end,
           error = case when x.n_questions > 0 then null else 'no questions' end, updated_at = now()
     where x.id = p_exam;
  end if;
end;
$$;

-- A unit that died after its claim gets 4 attempts, then fails as 'lost'
-- (and the exam moves on without it).
create or replace function study_private.exam_give_up(p_exam uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  update study_private.exam_jobs j
     set status = 'failed', error = 'lost', retry_at = null, lease_id = null, lease_until = null, updated_at = now()
   where j.exam_id = p_exam and j.status = 'running' and j.attempts >= 4 and j.lease_until <= now();
  if found then perform study_private.exam_advance(p_exam); end if;
end;
$$;

-- Kick the worker for each exam with units the caps allow now, as
-- study_private.dispatch does for lectures (2 minutes between the sweeper's
-- kicks of one exam, none after 15 kicks nobody claimed).
create or replace function study_private.exam_dispatch(p_exam uuid default null, p_now boolean default false)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  q record; v_url text; v_key text; v_n int; v_total int := 0;
begin
  if not study_private.server_on() or not study_private.feature_on('exams') then return 0; end if;
  v_url := rtrim(study_private.secret('study_site_url'), '/') || '/api/study/work';
  v_key := study_private.secret('study_worker_key');
  for q in select x.exam_id, x.group_id, x.last_kick_at, x.kicks_since_claim from study_private.exam_queue x
            where p_exam is null or x.exam_id = p_exam order by x.queued_at loop
    perform study_private.exam_give_up(q.exam_id);
    select count(*) into v_n from study_private.exam_jobs j
     where j.exam_id = q.exam_id
       and (j.status = 'pending' or (j.status = 'running' and j.lease_until <= now() and j.attempts < 4)
            or (j.status = 'failed' and j.attempts < 4 and j.retry_at <= now()));
    v_n := least(v_n, study_private.exam_cap(q.group_id) - study_private.group_live(q.group_id));
    if v_n <= 0 or (not p_now and q.last_kick_at > now() - interval '2 minutes') or q.kicks_since_claim >= 15 then
      continue;
    end if;
    for i in 1..v_n loop
      perform net.http_post(
        url := v_url,
        body := jsonb_build_object('exam', q.exam_id),
        headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_key),
        timeout_milliseconds := 10000);
    end loop;
    update study_private.exam_queue set last_kick_at = now(), kicks_since_claim = kicks_since_claim + v_n where exam_id = q.exam_id;
    v_total := v_total + v_n;
  end loop;
  return v_total;
end;
$$;

-- The pages' signed links, as study_queue checks a lecture's pictures: each
-- one this project's Storage link signed for exactly that page.
create or replace function study_private.exam_urls_ok(p_exam uuid, p_urls jsonb)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare p record; v text;
begin
  if p_urls is null or jsonb_typeof(p_urls) <> 'object' or length(p_urls::text) > 400000 then return false; end if;
  for p in select x.path from public.study_exam_pages x where x.exam_id = p_exam loop
    v := p_urls ->> p.path;
    if v is null or v !~ '^https://[^/?#@]+/storage/v1/object/sign/study/[^?#]+\?token=[A-Za-z0-9._-]+$'
       or right(split_part(v, '?', 1), char_length('/storage/v1/object/sign/study/' || p.path)) <> '/storage/v1/object/sign/study/' || p.path then
      return false;
    end if;
  end loop;
  return true;
end;
$$;
revoke all on function study_private.exam_job_active(study_private.exam_jobs), study_private.exam_unkeyed(uuid), study_private.exam_cap(uuid),
  study_private.exam_printed(uuid), study_private.exam_stale(public.study_exams),
  study_private.exam_give_up(uuid), study_private.exam_advance(uuid), study_private.exam_dispatch(uuid, boolean),
  study_private.exam_urls_ok(uuid, jsonb) from public;

-- The exam a member may act on: hers to see, not deleted ('exam not found'),
-- while the switch is on ('off'); locked.
create or replace function study_private.exam_for(p_exam uuid)
returns public.study_exams language plpgsql volatile security definer set search_path = public as $$
declare e public.study_exams;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into e from public.study_exams x where x.id = p_exam for update;
  if not found or e.deleted_at is not null or not coalesce(public.study_is_member(e.group_id), false) then
    raise exception 'exam not found';
  end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  return e;
end;
$$;
revoke all on function study_private.exam_for(uuid) from public;

-- ── The member's RPCs ──

-- "העלאת מבחן קודם": the exam's row in its course, before its pages are
-- uploaded. p_meta: {year, moed, key_source (marked | separate | none),
-- minutes}. Returns {exam_id, prefix}: the pages go to <prefix>p<n>.jpg.
-- 'not signed in', 'course not found', 'off', 'bad exam'.
create or replace function public.study_exam_create(p_course uuid, p_meta jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c   public.study_courses;
  v   uuid := gen_random_uuid();
  yr  int;
  md  text := nullif(btrim(coalesce(p_meta ->> 'moed', '')), '');
  ks  text := coalesce(p_meta ->> 'key_source', 'marked');
  mn  int;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then
    raise exception 'course not found';
  end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  if jsonb_typeof(coalesce(p_meta, '{}'::jsonb)) <> 'object'
     or coalesce(p_meta ->> 'year', '') !~ '^([0-9]{4})?$' or coalesce(p_meta ->> 'minutes', '') !~ '^([0-9]{1,3})?$'
     or ks not in ('marked', 'separate', 'none') or char_length(coalesce(md, '')) > 20 then
    raise exception 'bad exam';
  end if;
  yr := nullif(p_meta ->> 'year', '')::int;
  mn := nullif(p_meta ->> 'minutes', '')::int;
  if (yr is not null and yr not between 1990 and 2100) or (mn is not null and mn not between 10 and 600) then raise exception 'bad exam'; end if;
  insert into public.study_exams (id, group_id, course, title, year, moed, minutes, key_source, status, created_by)
  values (v, c.group_id, c.name,
          left(btrim(case when md is not null then 'מועד ' || md || coalesce(' ' || yr, '')
                          when yr is not null then 'מבחן ' || yr else 'מבחן קודם' end), 200),
          yr, md, mn, ks, 'uploading', auth.uid());
  return jsonb_build_object('exam_id', v, 'prefix', c.group_id || '/exams/' || v || '/');
end;
$$;

-- After the pages are uploaded (the op exam_read, with the server key and
-- the member's token, once its reservation passed the budget and the 3
-- exams a day): the pages are saved, the units queued (4 pages each, the
-- key sheet's pages in a unit of their own) and the worker kicked.
-- p_pages: [{n, path, w, h, lines[], key}] (n 1..120 once each; path the
-- exam's own p<n>.jpg, uploaded); p_urls: path → signed link.
-- Returns {units, server}: server false = the phone drives the units.
-- 'forbidden', 'exam not found', 'off', 'already started', 'too many pages',
-- 'bad pages', 'missing pages', 'bad urls'.
create or replace function public.study_exam_pages_done(p_exam uuid, p_pages jsonb, p_urls jsonb, p_until timestamptz default null,
  p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  e      public.study_exams;
  p      jsonb;
  reads  int[];
  keys   int[];
  units  int := 0;
  cid    uuid;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  e := study_private.exam_for(p_exam);
  if e.created_by is distinct from auth.uid() then raise exception 'exam not found'; end if;
  if e.status <> 'uploading' then raise exception 'already started'; end if;
  if jsonb_typeof(p_pages) is distinct from 'array' or jsonb_array_length(p_pages) = 0 then raise exception 'bad pages'; end if;
  if jsonb_array_length(p_pages) > 120 then raise exception 'too many pages'; end if;
  for p in select x from jsonb_array_elements(p_pages) x loop
    if jsonb_typeof(p) <> 'object' or coalesce(p ->> 'n', '') !~ '^[0-9]{1,3}$' or (p ->> 'n')::int not between 1 and 120
       or p ->> 'path' is distinct from e.group_id || '/exams/' || e.id || '/p' || (p ->> 'n') || '.jpg'
       or coalesce(p ->> 'w', '') !~ '^[0-9]{1,4}$' or coalesce(p ->> 'h', '') !~ '^[0-9]{1,4}$'
       or (p ->> 'w')::int not between 1 and 6000 or (p ->> 'h')::int not between 1 and 6000
       or (p -> 'lines' is not null and (jsonb_typeof(p -> 'lines') <> 'array' or jsonb_array_length(p -> 'lines') > 400
                                         or length((p -> 'lines')::text) > 40000
                                         or exists (select 1 from jsonb_array_elements(p -> 'lines') l where jsonb_typeof(l) <> 'string')))
       or (p -> 'key' is not null and jsonb_typeof(p -> 'key') <> 'boolean') then
      raise exception 'bad pages';
    end if;
  end loop;
  if (select count(distinct (x ->> 'n')::int) from jsonb_array_elements(p_pages) x) <> jsonb_array_length(p_pages) then
    raise exception 'bad pages';
  end if;
  if exists (select 1 from jsonb_array_elements(p_pages) x
              where not exists (select 1 from storage.objects o where o.bucket_id = 'study' and o.name = x ->> 'path')) then
    raise exception 'missing pages';
  end if;
  select array_agg((x ->> 'n')::int order by (x ->> 'n')::int) filter (where not coalesce((x ->> 'key')::boolean, false)),
         array_agg((x ->> 'n')::int order by (x ->> 'n')::int) filter (where coalesce((x ->> 'key')::boolean, false))
    into reads, keys from jsonb_array_elements(p_pages) x;
  if reads is null or (e.key_source = 'separate') <> (keys is not null) then raise exception 'bad pages'; end if;

  delete from public.study_exam_pages where exam_id = e.id;
  insert into public.study_exam_pages (exam_id, n, path, w, h, lines, is_key)
  select e.id, (x ->> 'n')::int, x ->> 'path', (x ->> 'w')::int, (x ->> 'h')::int,
         coalesce((select array_agg(left(l, 500) order by o) from jsonb_array_elements_text(x -> 'lines') with ordinality t(l, o)), '{}'),
         coalesce((x ->> 'key')::boolean, false)
    from jsonb_array_elements(p_pages) x;
  if not study_private.exam_urls_ok(e.id, p_urls) then raise exception 'bad urls'; end if;

  select c.id into cid from public.study_courses c where c.group_id = e.group_id and c.name_key = study_private.course_key(e.course);
  for i in 0 .. (cardinality(reads) - 1) / 4 loop
    insert into study_private.exam_jobs (group_id, course_id, exam_id, kind, range)
    values (e.group_id, cid, e.id, 'read',
            jsonb_build_object('pages', to_jsonb(reads[i * 4 + 1 : i * 4 + 4]), 'next', reads[i * 4 + 5]));
    units := units + 1;
  end loop;
  if keys is not null then
    insert into study_private.exam_jobs (group_id, course_id, exam_id, kind, range)
    values (e.group_id, cid, e.id, 'key', jsonb_build_object('pages', to_jsonb(keys)));
    units := units + 1;
  end if;
  update public.study_exams x set status = 'reading', key_pages = coalesce(keys, '{}'), error = null, updated_at = now() where x.id = e.id;
  insert into study_private.exam_queue (exam_id, group_id, urls, urls_until, queued_by)
  values (e.id, e.group_id, p_urls, p_until, auth.uid())
  on conflict (exam_id) do update set urls = excluded.urls, urls_until = excluded.urls_until, queued_by = excluded.queued_by,
                                      queued_at = now(), kicks_since_claim = 0;
  perform study_private.exam_dispatch(e.id, true);
  return jsonb_build_object('units', units, 'server', study_private.server_on());
end;
$$;

-- "מעתיקים עמודים 9–12 מתוך 28…": the exam's state, its units and counts.
-- found: items; keyed: a key from the exam, its sheet or a member;
-- suggested: solved ("תשובה מוצעת"); unkeyed; unclear: parse_conf 1.
create or replace function public.study_exam_status(p_exam uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare e public.study_exams;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into e from public.study_exams x where x.id = p_exam;
  if not found or e.deleted_at is not null or not coalesce(public.study_is_member(e.group_id), false) then
    raise exception 'exam not found';
  end if;
  return jsonb_build_object(
    'id', e.id, 'title', e.title, 'year', e.year, 'moed', e.moed, 'minutes', e.minutes, 'key_source', e.key_source,
    'status', e.status, 'error', e.error, 'skipped_open', e.skipped_open, 'hidden', e.hide_from_profile,
    'pages', (select count(*) from public.study_exam_pages x where x.exam_id = e.id and not x.is_key),
    'key_pages', cardinality(e.key_pages),
    'units', coalesce((select jsonb_agg(jsonb_build_object('kind', j.kind, 'pages', j.range -> 'pages',
                                                           'items', jsonb_array_length(coalesce(j.range -> 'items', '[]'::jsonb)),
                                                           'status', case when j.status = 'failed' and study_private.exam_job_active(j) then 'pending' else j.status end,
                                                           'error', j.error, 'reread', coalesce((j.range ->> 'reread')::boolean, false))
                                        order by j.created_at, (j.range -> 'pages' ->> 0)::int, j.id)
                         from study_private.exam_jobs j where j.exam_id = e.id), '[]'::jsonb),
    'found', (select count(*) from public.study_questions q where q.exam_id = e.id and q.retired_at is null),
    'keyed', (select count(*) from public.study_questions q join public.study_question_keys k on k.question_id = q.id
               where q.exam_id = e.id and q.retired_at is null and k.key_origin in ('exam', 'sheet', 'member')
                 and (k.answer is not null or k.seq is not null)),
    'suggested', (select count(*) from public.study_questions q join public.study_question_keys k on k.question_id = q.id
                   where q.exam_id = e.id and q.retired_at is null and k.key_origin = 'solved'),
    'unkeyed', (select count(*) from public.study_questions q where q.exam_id = e.id and q.retired_at is null and study_private.exam_unkeyed(q.id)),
    'unclear', (select count(*) from public.study_questions q where q.exam_id = e.id and q.retired_at is null and q.parse_conf = 1),
    -- numbers another page had already (not saved), and items the key sheet says were cancelled
    'repeats', coalesce((select sum(j.repeats) from study_private.exam_jobs j
                          where j.exam_id = e.id and j.kind = 'read'
                            and not coalesce((j.range ->> 'reread')::boolean, false)), 0),
    'cancelled', (select count(*) from study_private.exam_sheet_keys s
                   where s.exam_id = e.id and s.state = 'cancelled'
                     and exists (select 1 from public.study_questions q where q.exam_id = e.id and q.exam_no = s.exam_no and q.retired_at is not null)));
end;
$$;

-- The review screen (E4): every item with its reading and its key, where
-- the key came from and who keyed it (B3: a member may see an exam item's
-- key here; a key a live quiz holds is not shown), whether it was fixed,
-- and both logs.
create or replace function public.study_exam_review(p_exam uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare e public.study_exams;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into e from public.study_exams x where x.id = p_exam;
  if not found or e.deleted_at is not null or not coalesce(public.study_is_member(e.group_id), false) then
    raise exception 'exam not found';
  end if;
  return jsonb_build_object(
    'exam', jsonb_build_object('id', e.id, 'title', e.title, 'status', e.status, 'key_source', e.key_source, 'hidden', e.hide_from_profile,
                               'by', (select m.name from public.study_members m where m.group_id = e.group_id and m.user_id = e.created_by)),
    'pages', coalesce((select jsonb_agg(jsonb_build_object('n', x.n, 'path', x.path, 'w', x.w, 'h', x.h, 'key', x.is_key) order by x.n)
                         from public.study_exam_pages x where x.exam_id = e.id), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'id', q.id, 'no', q.exam_no, 'kind', q.kind, 'form', q.form, 'vignette', q.vignette, 'question', q.question,
        'options', q.options, 'prompts', coalesce(q.layout -> 'prompts', '[]'::jsonb), 'figure', q.figure, 'page', q.page,
        'parse_conf', q.parse_conf, 'retired', q.retired_at is not null,
        'answer', case when k.held_until > now() then null else k.answer end,
        'seq', case when k.held_until > now() then null else k.seq end,
        'origin', k.key_origin, 'conf', k.key_conf,
        'key_by', (select m.name from public.study_members m where m.group_id = e.group_id and m.user_id = k.key_by),
        'fixed', exists (select 1 from public.study_exam_item_log l where l.question_id = q.id),
        -- answered by anyone: a page read again keeps its text (as a fix does)
        'answered', exists (select 1 from public.study_answers a where a.question_id = q.id)) order by q.exam_no)
      from public.study_questions q left join public.study_question_keys k on k.question_id = q.id
      where q.exam_id = e.id), '[]'::jsonb),
    'key_log', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'question_id', l.question_id, 'old', l.old, 'new', l.new,
                                                             'origin_old', l.origin_old, 'origin_new', l.origin_new, 'undo_of', l.undo_of,
                                                             'by', (select m.name from public.study_members m where m.group_id = e.group_id and m.user_id = l.member_id),
                                                             'at', l.at) order by l.id)
                           from public.study_exam_key_log l where l.exam_id = e.id), '[]'::jsonb),
    'item_log', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'question_id', l.question_id, 'field', l.field, 'idx', l.idx,
                                                              'old', l.old, 'new', l.new,
                                                              'by', (select m.name from public.study_members m where m.group_id = e.group_id and m.user_id = l.member_id),
                                                              'at', l.at) order by l.id)
                            from public.study_exam_item_log l where l.exam_id = e.id), '[]'::jsonb));
end;
$$;

-- "לא נקראה טוב · לתקן טקסט": a member fixes the question, the case text,
-- an option (p_idx) or a match prompt (p_idx), logged. 'question not found',
-- 'off', 'bad field', 'bad text'.
create or replace function public.study_exam_item_edit(p_question uuid, p_field text, p_idx int, p_text text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  q   public.study_questions;
  t   text := btrim(coalesce(p_text, ''));
  old text;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into q from public.study_questions x where x.id = p_question for update;
  if not found or q.source <> 'exam' or not coalesce(public.study_is_member(q.group_id), false)
     or exists (select 1 from public.study_exams e where e.id = q.exam_id and e.deleted_at is not null) then
    raise exception 'question not found';
  end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  if p_field = 'question' then
    if char_length(t) not between 5 and 600 then raise exception 'bad text'; end if;
    old := q.question;
    update public.study_questions set question = t where id = q.id;
  elsif p_field = 'vignette' then
    if char_length(t) > 2500 then raise exception 'bad text'; end if;
    old := q.vignette;
    update public.study_questions set vignette = t where id = q.id;
  elsif p_field = 'option' then
    if p_idx is null or p_idx not between 0 and cardinality(q.options) - 1 then raise exception 'bad field'; end if;
    if char_length(t) not between 1 and 400 then raise exception 'bad text'; end if;
    old := q.options[p_idx + 1];
    update public.study_questions set options[p_idx + 1] = t where id = q.id;
  elsif p_field = 'prompt' then
    if q.form <> 'match' or p_idx is null or p_idx not between 0 and jsonb_array_length(coalesce(q.layout -> 'prompts', '[]'::jsonb)) - 1 then
      raise exception 'bad field';
    end if;
    if char_length(t) not between 1 and 300 then raise exception 'bad text'; end if;
    old := q.layout -> 'prompts' ->> p_idx;
    update public.study_questions set layout = jsonb_set(layout, array['prompts', p_idx::text], to_jsonb(t)) where id = q.id;
  else
    raise exception 'bad field';
  end if;
  if old is distinct from t then
    insert into public.study_exam_item_log (question_id, exam_id, field, idx, old, new)
    values (q.id, q.exam_id, p_field, case when p_field in ('option', 'prompt') then p_idx end, coalesce(old, ''), t);
  end if;
end;
$$;

-- "לסמן תשובה": section Q's function, redefined. A member marks (or clears)
-- the answer of a one-answer exam item; the change is logged with the key
-- it replaced (study_exam_key_log) and its origin becomes 'member'.
-- Explanations depend on the key, so they are cleared. A set item (tf,
-- match) is not keyed by hand in phase 2 ('set question').
create or replace function public.study_set_exam_key(p_question uuid, p_answer int)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  q public.study_questions;
  k public.study_question_keys;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into q from public.study_questions x where x.id = p_question for update;
  if not found or not public.study_is_member(q.group_id) or q.source <> 'exam'
     or exists (select 1 from public.study_exams e where e.id = q.exam_id and e.deleted_at is not null) then
    raise exception 'question not found';
  end if;
  if q.form <> 'one' then raise exception 'set question'; end if;
  if p_answer is not null and (p_answer < 0 or p_answer >= cardinality(q.options)) then raise exception 'bad answer'; end if;
  select * into k from public.study_question_keys x where x.question_id = p_question for update;
  if k.held_until > now() then raise exception 'in quiz'; end if;                   -- quiz: added
  insert into public.study_exam_key_log (question_id, exam_id, old, new, origin_old, origin_new, conf_old, by_old)
  values (q.id, q.exam_id, k.answer, p_answer, k.key_origin, case when p_answer is not null then 'member' end, k.key_conf, k.key_by);
  update public.study_question_keys x
     set answer = p_answer, key_by = auth.uid(), key_at = now(), explanations = '{}', takeaway = '',
         key_origin = case when p_answer is not null then 'member' end, key_conf = null
   where x.question_id = p_question;
  update public.study_questions x set has_key = p_answer is not null where x.id = p_question;
end;
$$;

-- "לבטל": the item's last change in the log that is not undone goes back
-- (the key, its origin and confidence, and who had keyed it), logged as its undo. Returns
-- the key now. 'question not found', 'nothing to undo', 'in quiz', 'changed'
-- (the key is not what that change left: the sheet or a reading wrote it
-- since, and an undo would erase that).
create or replace function public.study_exam_key_undo(p_question uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  q public.study_questions;
  k public.study_question_keys;
  l public.study_exam_key_log;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into q from public.study_questions x where x.id = p_question for update;
  if not found or not public.study_is_member(q.group_id) or q.source <> 'exam' then raise exception 'question not found'; end if;
  select * into k from public.study_question_keys x where x.question_id = p_question for update;
  if k.held_until > now() then raise exception 'in quiz'; end if;
  select * into l from public.study_exam_key_log x
   where x.question_id = p_question and x.undo_of is null
     and not exists (select 1 from public.study_exam_key_log u where u.undo_of = x.id)
   order by x.id desc limit 1;
  if not found then raise exception 'nothing to undo'; end if;
  if (k.answer, k.key_origin) is distinct from (l.new, l.origin_new) then raise exception 'changed'; end if;
  insert into public.study_exam_key_log (question_id, exam_id, old, new, origin_old, origin_new, conf_old, by_old, undo_of)
  values (q.id, q.exam_id, k.answer, l.old, k.key_origin, l.origin_old, k.key_conf, k.key_by, l.id);
  update public.study_question_keys x
     set answer = l.old, key_origin = l.origin_old, key_conf = l.conf_old, key_by = l.by_old, key_at = now(),
         explanations = '{}', takeaway = ''
   where x.question_id = p_question;
  update public.study_questions x set has_key = l.old is not null or k.seq is not null where x.id = p_question;
  return jsonb_build_object('answer', l.old, 'origin', l.origin_old);
end;
$$;

-- "לאשר" of a true/false or match item's suggested answer (a set item is
-- not keyed by hand in phase 2): its origin becomes 'member', logged as a
-- confirmation (the answer column of the log stays empty for a set item;
-- "לבטל" brings the suggested origin and confidence back). 'question not
-- found', 'off', 'nothing to confirm', 'in quiz'.
create or replace function public.study_exam_key_confirm(p_question uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  q public.study_questions;
  k public.study_question_keys;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into q from public.study_questions x where x.id = p_question for update;
  if not found or not coalesce(public.study_is_member(q.group_id), false) or q.source <> 'exam'
     or exists (select 1 from public.study_exams e where e.id = q.exam_id and e.deleted_at is not null) then
    raise exception 'question not found';
  end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  select * into k from public.study_question_keys x where x.question_id = p_question for update;
  if k.held_until > now() then raise exception 'in quiz'; end if;
  if k.key_origin is distinct from 'solved' or (k.answer is null and k.seq is null) then raise exception 'nothing to confirm'; end if;
  insert into public.study_exam_key_log (question_id, exam_id, old, new, origin_old, origin_new, conf_old, by_old)
  values (q.id, q.exam_id, k.answer, k.answer, k.key_origin, 'member', k.key_conf, k.key_by);
  update public.study_question_keys x set key_origin = 'member', key_conf = null, key_by = auth.uid(), key_at = now()
   where x.question_id = p_question;
end;
$$;

-- "לנסות שוב" (p_pages null: every unit that failed starts over) or "לקרוא
-- שוב את עמוד 7" (p_pages {7}: one unit for that page, the next one as
-- context). Fresh links from the phone (the queue's last 48 hours). Three
-- a study day per exam. Returns the units queued. 'exam not found', 'off',
-- 'retry limit', 'nothing to retry', 'bad pages', 'bad urls'.
create or replace function public.study_exam_retry(p_exam uuid, p_pages int[], p_urls jsonb, p_until timestamptz default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  e     public.study_exams;
  v_day date := ((now() at time zone 'Asia/Jerusalem') - interval '4 hours')::date;
  n     int := 0;
  pg    int;
  nx    int;
begin
  e := study_private.exam_for(p_exam);
  if e.status in ('new', 'uploading') then raise exception 'nothing to retry'; end if;
  if not study_private.exam_urls_ok(e.id, p_urls) then raise exception 'bad urls'; end if;
  if e.retry_day is distinct from v_day then e.retries := 0; end if;
  if e.retries >= 3 then raise exception 'retry limit'; end if;
  if cardinality(coalesce(p_pages, '{}')) = 0 then
    update study_private.exam_jobs j
       set status = 'pending', attempts = 0, error = null, retry_at = null, lease_id = null, lease_until = null, updated_at = now()
     where j.exam_id = e.id and j.status = 'failed'
       and coalesce(j.error, '') <> 'versions';   -- a key sheet of several versions reads the same again: keyed by hand
    get diagnostics n = row_count;
    -- Nothing failed but units still wait (the worker stopped answering):
    -- fresh links and fresh kicks for them.
    if n = 0 then
      select count(*) into n from study_private.exam_jobs j where j.exam_id = e.id and study_private.exam_job_active(j);
    end if;
    if n = 0 then raise exception 'nothing to retry'; end if;
  else
    if cardinality(p_pages) > 4 then raise exception 'bad pages'; end if;
    foreach pg in array p_pages loop
      if not exists (select 1 from public.study_exam_pages x where x.exam_id = e.id and x.n = pg and not x.is_key) then
        raise exception 'bad pages';
      end if;
      select min(x.n) into nx from public.study_exam_pages x where x.exam_id = e.id and x.n > pg and not x.is_key;
      insert into study_private.exam_jobs (group_id, course_id, exam_id, kind, range)
      select e.group_id, (select c.id from public.study_courses c where c.group_id = e.group_id and c.name_key = study_private.course_key(e.course)),
             e.id, 'read', jsonb_build_object('pages', jsonb_build_array(pg), 'next', nx, 'reread', true);
      n := n + 1;
    end loop;
  end if;
  update public.study_exams x set retries = e.retries + 1, retry_day = v_day, status = 'reading', error = null, updated_at = now()
   where x.id = e.id;
  update study_private.exam_queue x set urls = p_urls, urls_until = p_until, queued_by = auth.uid(), kicks_since_claim = 0
   where x.exam_id = e.id;
  perform study_private.exam_dispatch(e.id, true);
  return n;
end;
$$;

-- "לא לכלול בחישוב הנושאים": the exam still practises; the profile and the
-- course's style leave it out.
create or replace function public.study_exam_hide(p_exam uuid, p_hide boolean)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  perform study_private.exam_for(p_exam);
  update public.study_exams set hide_from_profile = coalesce(p_hide, false), updated_at = now() where id = p_exam;
end;
$$;

-- The course's past-exam items for the question writer's style
-- (courseStyle in server/study/practice.ts): exams of the course (by its
-- key), not deleted or hidden; has_key only for a key from the exam, its
-- sheet or a member (a solved key is no example). The key itself never
-- comes out.
create or replace function public.study_course_style_items(p_group uuid, p_course text)
returns table (id uuid, exam_id uuid, exam_no int, kind text, vignette text, question text, options text[], has_key boolean,
               exam_created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  if auth.uid() is null or not coalesce(public.study_is_member(p_group), false) then raise exception 'forbidden'; end if;
  return query
  select q.id, q.exam_id, q.exam_no, q.kind, q.vignette, q.question, q.options,
         coalesce(k.key_origin in ('exam', 'sheet', 'member') and (k.answer is not null or k.seq is not null), false), e.created_at
    from public.study_exams e
    join public.study_questions q on q.exam_id = e.id and q.source = 'exam' and q.retired_at is null
    left join public.study_question_keys k on k.question_id = q.id
   where e.group_id = p_group and e.deleted_at is null and not e.hide_from_profile
     and study_private.course_key(e.course) = study_private.course_key(p_course) and study_private.course_key(p_course) <> '';
end;
$$;

-- ── The worker's RPCs (the server key; the worker alone, or the phone's
--    op with the member's token when server writing is off) ──

-- Takes the exam's next unit under a 330-second lease: at most 4 attempts,
-- at most three units of a group at once counting the summaries' (two
-- while a lecture of the group waits to be written: summaries keep
-- priority). Returns everything the unit needs (its pages with their links
-- and lines, the next page, the numbers already saved, or its items), or
-- null: nothing to take now.
create or replace function public.study_claim_exam(p_exam uuid, p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  e        public.study_exams;
  j        study_private.exam_jobs;
  q        study_private.exam_queue;
  v_lease  uuid := gen_random_uuid();
  v_server boolean := auth.uid() is null;
  v_cap    int;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  select * into e from public.study_exams x where x.id = p_exam;
  if not found then return null; end if;
  if not v_server and not coalesce(public.study_is_member(e.group_id), false) then raise exception 'forbidden'; end if;
  perform 1 from public.study_groups g where g.id = e.group_id for update;   -- study_claim takes the same lock
  perform study_private.exam_give_up(p_exam);
  if e.deleted_at is not null or not study_private.feature_on('exams') then return null; end if;
  -- The worker answered, so it is alive: a refused claim does not count as a
  -- kick nobody took (else the sweeper stops after 15 while summaries run).
  if v_server then update study_private.exam_queue set kicks_since_claim = 0 where exam_id = p_exam; end if;
  v_cap := study_private.exam_cap(e.group_id);
  if study_private.group_live(e.group_id) >= v_cap then return null; end if;
  select * into j from study_private.exam_jobs x
   where x.exam_id = p_exam
     and (x.status = 'pending'
          or (x.status = 'running' and x.lease_until <= now() and x.attempts < 4)
          or (x.status = 'failed' and x.attempts < 4 and x.retry_at is not null and (not v_server or x.retry_at <= now())))
   order by case x.kind when 'key' then 0 when 'read' then 1 else 2 end, x.created_at, (x.range -> 'pages' ->> 0)::int, x.id
   limit 1 for update;
  if not found then return null; end if;
  update study_private.exam_jobs x
     set status = 'running', lease_id = v_lease, lease_until = now() + interval '330 seconds', attempts = x.attempts + 1,
         retry_at = null, updated_at = now()
   where x.id = j.id;
  select * into q from study_private.exam_queue x where x.exam_id = p_exam;
  return jsonb_build_object(
    'job', j.id, 'kind', j.kind, 'lease', v_lease, 'attempt', j.attempts + 1, 'last_error', j.error,
    'reread', coalesce((j.range ->> 'reread')::boolean, false),
    'exam', jsonb_build_object('id', e.id, 'group_id', e.group_id, 'title', e.title, 'key_source', e.key_source),
    'pages', coalesce((select jsonb_agg(jsonb_build_object('n', p.n, 'path', p.path, 'w', p.w, 'h', p.h, 'lines', to_jsonb(p.lines),
                                                           'url', q.urls ->> p.path) order by p.n)
                         from public.study_exam_pages p
                        where p.exam_id = e.id and p.n in (select v::int from jsonb_array_elements_text(coalesce(j.range -> 'pages', '[]'::jsonb)) v)),
                      '[]'::jsonb),
    'next', (select jsonb_build_object('n', p.n, 'path', p.path, 'w', p.w, 'h', p.h, 'url', q.urls ->> p.path)
               from public.study_exam_pages p where p.exam_id = e.id and p.n = (j.range ->> 'next')::int),
    -- The page before the unit's first, as context too: a case printed there
    -- may belong to questions on the unit's pages ("המקרה הבא מתייחס לשאלות 12–14").
    'prev', case when j.kind = 'read' then
              (select jsonb_build_object('n', p.n, 'path', p.path, 'w', p.w, 'h', p.h, 'url', q.urls ->> p.path)
                 from public.study_exam_pages p
                where p.exam_id = e.id and not p.is_key and p.n < (j.range -> 'pages' ->> 0)::int
                order by p.n desc limit 1) end,
    -- The numbers saved already; a page read again leaves out its own (it is to copy them again).
    'seen', coalesce((select jsonb_agg(x.exam_no order by x.exam_no) from public.study_questions x
                       where x.exam_id = e.id
                         and not (coalesce((j.range ->> 'reread')::boolean, false)
                                  and coalesce(x.page, 0) in (select v::int from jsonb_array_elements_text(coalesce(j.range -> 'pages', '[]'::jsonb)) v))),
                     '[]'::jsonb),
    'items', case when j.kind = 'solve' then
               coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'no', x.exam_no, 'form', x.form, 'vignette', x.vignette,
                                                            'question', x.question, 'options', x.options,
                                                            'prompts', coalesce(x.layout -> 'prompts', '[]'::jsonb)) order by x.exam_no)
                           from public.study_questions x
                          where x.exam_id = e.id and j.range -> 'items' ? x.id::text and x.retired_at is null
                            and study_private.exam_unkeyed(x.id)), '[]'::jsonb) end);
end;
$$;

-- The holder of a unit's lease, or 'lease lost' (another writer took it).
create or replace function study_private.exam_job_held(p_job uuid, p_lease uuid)
returns study_private.exam_jobs language plpgsql volatile security definer set search_path = public as $$
declare j study_private.exam_jobs;
begin
  select * into j from study_private.exam_jobs x where x.id = p_job for update;
  if not found or j.lease_id is distinct from p_lease or j.status <> 'running' then raise exception 'lease lost'; end if;
  if auth.uid() is not null and not coalesce(public.study_is_member(j.group_id), false) then raise exception 'forbidden'; end if;
  return j;
end;
$$;
revoke all on function study_private.exam_job_held(uuid, uuid) from public;

-- One item's key as checked against it: a one-answer item's answer in
-- range, a set item's seq (tf: 1/0 per statement; match: a distinct
-- option per prompt). Null when it does not fit.
create or replace function study_private.exam_key_fit(q public.study_questions, p_answer int, p_seq int[])
returns jsonb language sql immutable as $$
  select case
    when q.form = 'one' and p_answer between 0 and cardinality(q.options) - 1 then jsonb_build_object('answer', p_answer)
    when q.form = 'tf' and cardinality(p_seq) = cardinality(q.options) and 0 <= all (p_seq) and 1 >= all (p_seq)
      then jsonb_build_object('seq', to_jsonb(p_seq))
    when q.form = 'match' and cardinality(p_seq) = jsonb_array_length(coalesce(q.layout -> 'prompts', '[]'::jsonb))
         and 0 <= all (p_seq) and cardinality(q.options) - 1 >= all (p_seq)
         and (select count(distinct v) from unnest(p_seq) v) = cardinality(p_seq)
      then jsonb_build_object('seq', to_jsonb(p_seq))
  end
$$;
revoke all on function study_private.exam_key_fit(public.study_questions, int, int[]) from public;

-- Writes a key onto an item unless a member's key is there (or a live quiz
-- holds it); with p_only_empty, only onto an item with no key yet.
create or replace function study_private.exam_key_put(p_question uuid, p_answer int, p_seq int[], p_origin text, p_conf int,
  p_only_empty boolean default false)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  q   public.study_questions;
  fit jsonb;
begin
  select * into q from public.study_questions x where x.id = p_question;
  fit := study_private.exam_key_fit(q, p_answer, p_seq);
  if fit is null then return false; end if;
  update public.study_question_keys k
     set answer = (fit ->> 'answer')::smallint,
         seq = (select array_agg(v::smallint order by o) from jsonb_array_elements_text(fit -> 'seq') with ordinality t(v, o)),
         key_origin = p_origin, key_conf = case when p_origin = 'solved' then p_conf end, key_by = null, key_at = now(),
         explanations = '{}', takeaway = ''
   where k.question_id = p_question and coalesce(k.key_origin, '') <> 'member' and (k.held_until is null or k.held_until <= now())
     and (not p_only_empty or (k.answer is null and k.seq is null));
  if not found then return false; end if;
  update public.study_questions set has_key = true where id = p_question;
  return true;
end;
$$;
revoke all on function study_private.exam_key_put(uuid, int, int[], text, int, boolean) from public;

-- The key sheet's line for one item: its answer (origin 'sheet'), or
-- "בוטלה" (the item is retired: it counts nowhere), or several answers
-- accepted (the first, as a suggested answer under confidence 3).
create or replace function study_private.exam_sheet_put(p_question uuid, sk study_private.exam_sheet_keys)
returns boolean language plpgsql volatile security definer set search_path = public as $$
begin
  if sk.state = 'cancelled' then
    update public.study_questions set retired_at = now() where id = p_question and retired_at is null;
    return found;
  elsif sk.state = 'several' then
    return study_private.exam_key_put(p_question, sk.answer, sk.seq::int[], 'solved', 1);
  end if;
  return study_private.exam_key_put(p_question, sk.answer, sk.seq::int[], 'sheet', null);
end;
$$;
revoke all on function study_private.exam_sheet_put(uuid, study_private.exam_sheet_keys) from public;

-- A read unit's items, saved by number (an upsert: a unit read again, or a
-- page read again, changes the same rows). p_items: [{no, kind, form,
-- vignette, question, options[], prompts[], answer (-1: not marked), seq[],
-- marked_by, figure 'pg:…' or '', parse_conf, page}]; p_skipped: the open
-- questions skipped. The units of one exam run side by side, so their saves
-- take turns (one number is never inserted twice at once). A number saved
-- already from another page: a question over two pages copied by both
-- units keeps its longer copy; from a page further away it is a repeated
-- number (an exam whose parts restart at 1, a misread number), not saved
-- and counted (the review says so). A page read again replaces its items.
-- An item a member fixed, or anyone answered, keeps its text. Marks count
-- only when the uploader said the answers are marked in the exam; a
-- handwritten mark is a suggested answer ("תשובה מוצעת", confidence 2),
-- not the exam's; a mark never replaces the sheet's, a suggested or a
-- member's key. The key sheet's answer by number wins. Returns {saved,
-- updated, skipped, repeats} (items that do not fit the table are
-- skipped). 'forbidden', 'lease lost'.
create or replace function public.study_exam_save_items(p_job uuid, p_lease uuid, p_items jsonb, p_skipped int default 0,
  p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  j       study_private.exam_jobs;
  e       public.study_exams;
  it      jsonb;
  qid     uuid;
  had     public.study_questions;
  n_new   int := 0;
  n_upd   int := 0;
  n_bad   int := 0;
  n_rep   int := 0;
  v_no    int;
  v_form  text;
  v_opts  text[];
  v_pr    jsonb;
  v_fig   text;
  v_lay   jsonb;
  v_ans   int;
  v_seq   int[];
  v_page  int;
  v_take  boolean;
  v_rr    boolean;
  sk      study_private.exam_sheet_keys;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  j := study_private.exam_job_held(p_job, p_lease);
  if j.kind <> 'read' then raise exception 'bad unit'; end if;
  select * into e from public.study_exams x where x.id = j.exam_id;
  perform pg_advisory_xact_lock(hashtext('study_exam_save:' || e.id::text));
  v_rr := coalesce((j.range ->> 'reread')::boolean, false);
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 120 then raise exception 'bad items'; end if;
  for it in select x from jsonb_array_elements(p_items) x loop
    begin
      v_no := (it ->> 'no')::int;
      v_form := coalesce(it ->> 'form', 'one');
      select array_agg(btrim(o) order by k) into v_opts from jsonb_array_elements_text(it -> 'options') with ordinality t(o, k);
      v_pr := case when v_form = 'match' then coalesce(it -> 'prompts', '[]'::jsonb) else '[]'::jsonb end;
      v_fig := coalesce(it ->> 'figure', '');
      v_ans := nullif((it ->> 'answer')::int, -1);
      v_page := (it ->> 'page')::int;
      select array_agg(v::int order by k) into v_seq from jsonb_array_elements_text(coalesce(it -> 'seq', '[]'::jsonb)) with ordinality t(v, k);
      if v_no is null or v_no not between 1 and 500 or v_form not in ('one', 'tf', 'match')
         or coalesce(it ->> 'kind', 'mcq') not in ('mcq', 'case')
         or char_length(btrim(coalesce(it ->> 'question', ''))) not between 5 and 600
         or char_length(coalesce(it ->> 'vignette', '')) > 2500
         or coalesce(cardinality(v_opts), 0) not between 2 and 6
         or exists (select 1 from unnest(v_opts) o where char_length(o) not between 1 and 400)
         or (v_form = 'match' and (jsonb_array_length(v_pr) not between 2 and 6
                                   or exists (select 1 from jsonb_array_elements(v_pr) p
                                               where jsonb_typeof(p) <> 'string' or char_length(btrim(p #>> '{}')) not between 1 and 300)))
         or (v_fig <> '' and v_fig !~ '^pg:[0-9]{1,3}:[0-9]{1,4},[0-9]{1,4},[0-9]{1,4},[0-9]{1,4}$')
         or coalesce((it ->> 'parse_conf')::int, 2) not between 1 and 3
         or (v_page is not null and v_page not between 1 and 120) then
        n_bad := n_bad + 1;
        continue;
      end if;
    exception when others then
      n_bad := n_bad + 1;
      continue;
    end;
    v_lay := case when v_form = 'match'
                  then jsonb_build_object('kind', 'match', 'prompts', (select jsonb_agg(btrim(p #>> '{}')) from jsonb_array_elements(v_pr) p)) end;
    select * into had from public.study_questions x where x.exam_id = e.id and x.exam_no = v_no;
    if not found then
      insert into public.study_questions (group_id, exam_id, exam_no, source, kind, vignette, question, options, form, layout,
                                          figure, parse_conf, page, has_key, created_by)
      values (e.group_id, e.id, v_no, 'exam', coalesce(it ->> 'kind', 'mcq'), btrim(coalesce(it ->> 'vignette', '')),
              btrim(it ->> 'question'), v_opts, v_form, v_lay, v_fig, coalesce((it ->> 'parse_conf')::int, 2),
              v_page, false, e.created_by)
      returning id into qid;
      insert into public.study_question_keys (question_id, answer) values (qid, null);
      n_new := n_new + 1;
      v_take := true;
    else
      qid := had.id;
      v_take := v_rr or had.page is null or v_page is null or had.page = v_page;
      if not v_take then
        if abs(had.page - v_page) = 1 then
          -- One question over two pages, copied by both units: the longer copy stays.
          v_take := char_length(btrim(coalesce(it ->> 'vignette', ''))) + char_length(btrim(it ->> 'question'))
                      + (select coalesce(sum(char_length(o)), 0) from unnest(v_opts) o)
                    > char_length(had.vignette) + char_length(had.question) + (select coalesce(sum(char_length(o)), 0) from unnest(had.options) o);
        else
          n_rep := n_rep + 1;
          continue;
        end if;
      end if;
      if v_take and not exists (select 1 from public.study_exam_item_log l where l.question_id = qid)
         and not exists (select 1 from public.study_answers a where a.question_id = qid) then
        update public.study_questions x
           set kind = coalesce(it ->> 'kind', 'mcq'), vignette = btrim(coalesce(it ->> 'vignette', '')), question = btrim(it ->> 'question'),
               options = v_opts, form = v_form, layout = v_lay, figure = v_fig,
               parse_conf = coalesce((it ->> 'parse_conf')::int, 2), page = v_page
         where x.id = qid;
        -- a different shape: a key from the earlier reading may not fit it any more
        update public.study_question_keys k set answer = null, seq = null, key_origin = null, key_conf = null
         where k.question_id = qid and coalesce(k.key_origin, '') not in ('member', 'sheet')
           and study_private.exam_key_fit((select x from public.study_questions x where x.id = qid), k.answer, k.seq::int[]) is null;
      end if;
      n_upd := n_upd + 1;
    end if;
    -- The exam's own mark, when the uploader said the answers are marked in
    -- it, onto an item with no key or only the exam's.
    if v_take and e.key_source = 'marked' and (v_ans is not null or v_seq is not null)
       and not exists (select 1 from public.study_question_keys k where k.question_id = qid and k.key_origin in ('sheet', 'solved', 'member')) then
      if coalesce(it ->> 'marked_by', '') = 'handwritten' then
        perform study_private.exam_key_put(qid, v_ans, v_seq, 'solved', 2);
      else
        perform study_private.exam_key_put(qid, v_ans, v_seq, 'exam', null);
      end if;
    end if;
    select * into sk from study_private.exam_sheet_keys s where s.exam_id = e.id and s.exam_no = v_no;
    if found then perform study_private.exam_sheet_put(qid, sk); end if;
    update public.study_questions x set has_key = not study_private.exam_unkeyed(qid) where x.id = qid;
  end loop;
  update study_private.exam_jobs x
     set skipped = least(500, greatest(0, coalesce(p_skipped, 0))), repeats = least(500, n_rep), updated_at = now()
   where x.id = j.id;
  return jsonb_build_object('saved', n_new, 'updated', n_upd, 'skipped', n_bad, 'repeats', n_rep);
end;
$$;

-- A key unit's sheet ({no, answer, seq, state}: merged by number, origin
-- 'sheet', over the exam's marks and suggested keys, never over a
-- member's; state 'cancelled' ("בוטלה") retires the item, 'several' (more
-- than one answer accepted) makes the first a suggested one that counts in
-- no score until a member confirms it), or a solve unit's answers ({no,
-- answer, seq, conf}: only onto items still without a key, origin
-- 'solved'; an item with a picture or a reading that is not sure is solved
-- from its text alone, so at most confidence 2). Returns how many items
-- took a key.
create or replace function public.study_exam_save_keys(p_job uuid, p_lease uuid, p_keys jsonb, p_key text default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  j   study_private.exam_jobs;
  it  jsonb;
  v_no int;
  v_ans int;
  v_seq int[];
  v_conf int;
  v_state text;
  qid uuid;
  q   public.study_questions;
  sk  study_private.exam_sheet_keys;
  n   int := 0;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  j := study_private.exam_job_held(p_job, p_lease);
  if j.kind not in ('key', 'solve') then raise exception 'bad unit'; end if;
  if jsonb_typeof(p_keys) is distinct from 'array' or jsonb_array_length(p_keys) > 500 then raise exception 'bad keys'; end if;
  perform pg_advisory_xact_lock(hashtext('study_exam_save:' || j.exam_id::text));
  for it in select x from jsonb_array_elements(p_keys) x loop
    begin
      v_no := (it ->> 'no')::int;
      v_ans := nullif((it ->> 'answer')::int, -1);
      select array_agg(v::int order by k) into v_seq from jsonb_array_elements_text(coalesce(it -> 'seq', '[]'::jsonb)) with ordinality t(v, k);
      v_conf := (it ->> 'conf')::int;
      v_state := case when j.kind = 'key' then nullif(it ->> 'state', '') end;
    exception when others then
      continue;
    end;
    if v_no is null or v_no not between 1 and 500 or (v_state is not null and v_state not in ('cancelled', 'several'))
       or (v_state = 'cancelled' and (v_ans is not null or v_seq is not null))
       or (coalesce(v_state, '') <> 'cancelled' and v_ans is null and v_seq is null)
       or (v_ans is not null and v_ans not between 0 and 5) or (v_seq is not null and (cardinality(v_seq) not between 2 and 6
                                                                                      or not (0 <= all (v_seq) and 5 >= all (v_seq)))) then
      continue;
    end if;
    select * into q from public.study_questions x where x.exam_id = j.exam_id and x.exam_no = v_no;
    qid := case when found then q.id end;
    if j.kind = 'key' then
      insert into study_private.exam_sheet_keys (exam_id, exam_no, answer, seq, state) values (j.exam_id, v_no, v_ans, v_seq::smallint[], v_state)
      on conflict (exam_id, exam_no) do update set answer = excluded.answer, seq = excluded.seq, state = excluded.state
      returning * into sk;
      if qid is not null and study_private.exam_sheet_put(qid, sk) then n := n + 1; end if;
    elsif qid is not null and j.range -> 'items' ? qid::text and coalesce(v_conf, 0) between 1 and 3
          and study_private.exam_key_put(qid, v_ans, v_seq, 'solved',
                                         case when q.figure <> '' or coalesce(q.parse_conf, 2) < 3 then least(v_conf, 2) else v_conf end, true) then
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;

-- A unit is done or failed. A model's own failure (timeout, refusal,
-- unreadable, truncated) gets one retry; a passing API error is retried
-- as a part's (backoff, 4 attempts); others wait for "לנסות שוב". The
-- unit's cost is kept for the status screen (the ledger is settled by
-- the caller). Then the exam moves on and the worker is kicked again.
create or replace function public.study_finish_exam_job(p_job uuid, p_lease uuid, p_status text, p_error text default null,
  p_cost numeric default 0, p_key text default null)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  j  study_private.exam_jobs;
  ok boolean;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if p_status not in ('done', 'failed') then raise exception 'bad finish'; end if;
  select * into j from study_private.exam_jobs x where x.id = p_job;
  if not found then return false; end if;
  if auth.uid() is not null and not coalesce(public.study_is_member(j.group_id), false) then raise exception 'forbidden'; end if;
  update study_private.exam_jobs x
     set status = p_status, error = case when p_status = 'failed' then left(coalesce(p_error, 'failed'), 200) end,
         cost_usd = least(99999, x.cost_usd + round(least(greatest(coalesce(p_cost, 0), 0), 99.99999), 5)),
         retry_at = case when p_status = 'done' then null
                         when p_error in ('timeout', 'refusal', 'unreadable', 'truncated', 'empty')
                           then case when x.attempts < 2 then now() + interval '1 minute' end
                         else study_private.retry_at('failed', p_error, x.attempts) end,
         lease_id = null, lease_until = null, updated_at = now()
   where x.id = p_job and x.lease_id = p_lease and x.status = 'running';
  ok := found;
  perform study_private.exam_advance(j.exam_id);
  if ok then perform study_private.exam_dispatch(j.exam_id, true); end if;
  return ok;
end;
$$;

-- ── Simulations (kind 'exam' in phase 2; 'mixed' and 'new' are phase 4's) ──

-- "סימולציה": a past exam's items, all (p_n null, at most 150) or p_n of
-- them (5..150; "רק שאלות שעוד לא ראיתי" takes the ones the caller never
-- answered first), in the exam's order, and the minutes (given, else the
-- exam's scaled to the length, else the course's, else 1.8 a question).
-- Returns {mock, questions, minutes, pool, missing: []}. 'course not
-- found', 'off', 'bad kind', 'exam not found', 'exam not ready', 'bad
-- questions', 'bad minutes', 'too few questions'.
create or replace function public.study_mock_create(p_course uuid, p_kind text, p_exam uuid, p_n int default null,
  p_minutes int default null, p_unseen_only boolean default true)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c    public.study_courses;
  e    public.study_exams;
  pool int;
  n    int;
  ids  uuid[];
  mins int;
  v    uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then raise exception 'course not found'; end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  if p_kind is distinct from 'exam' then raise exception 'bad kind'; end if;
  select * into e from public.study_exams x where x.id = p_exam;
  if not found or e.group_id <> c.group_id or e.deleted_at is not null or study_private.course_key(e.course) <> c.name_key then
    raise exception 'exam not found';
  end if;
  if e.status <> 'ready' then raise exception 'exam not ready'; end if;
  if p_n is not null and p_n not between 5 and 150 then raise exception 'bad questions'; end if;
  if p_minutes is not null and p_minutes not between 1 and 600 then raise exception 'bad minutes'; end if;
  select count(*) into pool from public.study_questions q where q.exam_id = e.id and q.retired_at is null and q.hidden_at is null;
  if pool < 5 then raise exception 'too few questions'; end if;
  n := least(coalesce(p_n, 150), pool, 150);
  select array_agg(x.id order by x.exam_no) into ids from (
    select q.id, q.exam_no from public.study_questions q
     where q.exam_id = e.id and q.retired_at is null and q.hidden_at is null
     order by case when coalesce(p_unseen_only, true)
                    and exists (select 1 from public.study_answers a where a.question_id = q.id and a.user_id = auth.uid()) then 1 else 0 end,
              case when n < pool then random() else 0 end, q.exam_no
     limit n) x;
  mins := least(600, greatest(1, coalesce(p_minutes,
            -- the exam's minutes were for all it printed, open questions and items not saved included
            case when e.minutes is not null then ceil(e.minutes::numeric * n / greatest(pool, study_private.exam_printed(e.id), 1))::int end,
            case when c.exam_minutes is not null and c.exam_n is not null then ceil(c.exam_minutes::numeric * n / c.exam_n)::int end,
            ceil(n * 1.8)::int)));
  insert into public.study_mocks (group_id, course_id, kind, exam_id, question_ids, minutes, spec, created_by)
  values (c.group_id, c.id, 'exam', e.id, ids, mins,
          jsonb_build_object('n', n, 'pool', pool, 'unseen_only', coalesce(p_unseen_only, true)), auth.uid())
  returning id into v;
  return jsonb_build_object('mock', v, 'questions', n, 'minutes', mins, 'pool', pool, 'missing', '[]'::jsonb);
end;
$$;

-- The caller's attempt, locked: 'attempt not found' unless it is hers and
-- she is still in its group (someone removed keeps no way to its keys).
create or replace function study_private.attempt_for(p_attempt uuid)
returns public.study_mock_attempts language plpgsql volatile security definer set search_path = public as $$
declare a public.study_mock_attempts;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into a from public.study_mock_attempts x where x.id = p_attempt for update;
  if not found or a.member_id <> auth.uid()
     or not coalesce(public.study_is_member((select m.group_id from public.study_mocks m where m.id = a.mock_id)), false) then
    raise exception 'attempt not found';
  end if;
  return a;
end;
$$;
revoke all on function study_private.attempt_for(uuid) from public;

-- Submits an attempt ("להגיש", or the clock): each pick of a counted item
-- becomes the caller's study_answers row (mode 'exam', attempt_id), and the
-- score is kept. Counted: a key, and not a solved key under confidence 3
-- (B7: those are "לא נספרה"); a solved key at 3 counts and is named. An
-- item left blank counts as wrong and writes no row. Returns the score:
-- {right, counted, total, answered, suggested, not_counted, auto, items:
-- [{id, no, form, answer, seq, choice, choices, correct, counted, origin,
-- ref_lecture, topic}]}. A second call returns the same score.
create or replace function public.study_mock_finish(p_attempt uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  a      public.study_mock_attempts;
  m      public.study_mocks;
  qid    uuid;
  pos    int;
  q      public.study_questions;
  k      public.study_question_keys;
  pick   jsonb;
  counted boolean;
  ok     boolean;
  items  jsonb := '[]'::jsonb;
  r int := 0; nc int := 0; na int := 0; ns int := 0;
  v_auto boolean;
  v_c    int;
  v_cs   int[];
begin
  a := study_private.attempt_for(p_attempt);
  if a.finished_at is not null then return a.score; end if;
  select * into m from public.study_mocks x where x.id = a.mock_id;
  v_auto := now() >= a.deadline;
  for qid, pos in select x, o from unnest(m.question_ids) with ordinality t(x, o) loop
    select * into q from public.study_questions x where x.id = qid;
    if not found then continue; end if;
    select * into k from public.study_question_keys x where x.question_id = qid;
    pick := a.picks -> qid::text;
    v_c := (pick ->> 'c')::int;
    select array_agg(v::int order by o2) into v_cs from jsonb_array_elements_text(coalesce(pick -> 'cs', '[]'::jsonb)) with ordinality t(v, o2);
    counted := q.retired_at is null and (k.held_until is null or k.held_until <= now())
               and ((q.form = 'one' and k.answer is not null) or (q.form <> 'one' and k.seq is not null))
               and not (k.key_origin = 'solved' and coalesce(k.key_conf, 0) < 3);
    ok := counted and case when q.form = 'one' then v_c is not null and v_c = k.answer
                           else v_cs is not null and v_cs = k.seq::int[] end;
    if counted then
      nc := nc + 1;
      if ok then r := r + 1; end if;
      if k.key_origin = 'solved' then ns := ns + 1; end if;
      if pick is not null then
        insert into public.study_answers (user_id, question_id, choice, choices, correct, mode, ms, attempt_id)
        values (a.member_id, qid, case when q.form = 'one' then v_c end, case when q.form <> 'one' then v_cs::smallint[] end,
                ok, 'exam', case when (pick ->> 'ms')::int between 0 and 3600000 then (pick ->> 'ms')::int end, a.id);
      end if;
    end if;
    if pick is not null then na := na + 1; end if;
    items := items || jsonb_build_object(
      'id', qid, 'pos', pos, 'no', q.exam_no, 'form', q.form,
      'answer', case when k.held_until > now() then null else k.answer end,
      'seq', case when k.held_until > now() then null else k.seq end,
      'choice', v_c, 'choices', to_jsonb(v_cs), 'correct', ok, 'counted', counted, 'origin', k.key_origin,
      'ref_lecture', q.ref_lecture, 'topic', q.topic);
  end loop;
  update public.study_mock_attempts x
     set finished_at = now(), auto = v_auto,
         score = jsonb_build_object('right', r, 'counted', nc, 'total', cardinality(m.question_ids), 'answered', na,
                                    'suggested', ns, 'not_counted', cardinality(m.question_ids) - nc, 'auto', v_auto, 'items', items)
   where x.id = a.id
  returning score into items;
  return items;
end;
$$;

-- The attempt to show or resume: its deadline and the server's now (the
-- phone's clock may be off), the questions in order, the caller's picks
-- and flags, and the score once submitted. Past the deadline it is
-- submitted first (the clock auto-submits on the next load).
create or replace function public.study_mock_get(p_attempt uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  a public.study_mock_attempts;
  m public.study_mocks;
begin
  a := study_private.attempt_for(p_attempt);
  if a.finished_at is null and now() >= a.deadline then
    perform public.study_mock_finish(a.id);
    select * into a from public.study_mock_attempts x where x.id = p_attempt;
  end if;
  select * into m from public.study_mocks x where x.id = a.mock_id;
  return jsonb_build_object(
    'attempt', a.id, 'mock', m.id, 'kind', m.kind, 'exam_id', m.exam_id, 'course_id', m.course_id, 'minutes', m.minutes,
    'started_at', a.started_at, 'deadline', a.deadline, 'now', now(), 'finished_at', a.finished_at,
    'position', a.position, 'flagged', to_jsonb(a.flagged), 'question_ids', to_jsonb(m.question_ids),
    'picks', a.picks, 'score', a.score);
end;
$$;

-- Starts the clock: the caller's open attempt of this mock comes back (a
-- second phone, a reload); an expired one is submitted and a new one starts.
-- 'mock not found', 'off'.
create or replace function public.study_mock_start(p_mock uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  m public.study_mocks;
  a public.study_mock_attempts;
  v uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into m from public.study_mocks x where x.id = p_mock;
  if not found or not coalesce(public.study_is_member(m.group_id), false) then raise exception 'mock not found'; end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  perform pg_advisory_xact_lock(hashtext('study_mock:' || p_mock::text || ':' || auth.uid()::text));
  select * into a from public.study_mock_attempts x
   where x.mock_id = p_mock and x.member_id = auth.uid() and x.finished_at is null order by x.started_at desc limit 1;
  if found and a.deadline > now() then return public.study_mock_get(a.id); end if;
  if found then perform public.study_mock_finish(a.id); end if;
  insert into public.study_mock_attempts (mock_id, member_id, deadline) values (p_mock, auth.uid(), now() + make_interval(mins => m.minutes))
  returning id into v;
  return public.study_mock_get(v);
end;
$$;

-- Where the caller is ("שאלה 37 מתוך 100") and "לסמן לחזרה", saved on
-- every move. False once submitted (the clock ran out: the screen reloads).
create or replace function public.study_mock_progress(p_attempt uuid, p_position int, p_flagged int[])
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  a public.study_mock_attempts;
  m public.study_mocks;
begin
  a := study_private.attempt_for(p_attempt);
  if a.finished_at is not null then return false; end if;
  -- The same 10 seconds' grace as a pick: a move on the last second must not
  -- submit before the last pick arrives.
  if now() >= a.deadline + interval '10 seconds' then perform public.study_mock_finish(a.id); return false; end if;
  select * into m from public.study_mocks x where x.id = a.mock_id;
  if p_position is null or p_position not between 0 and cardinality(m.question_ids) - 1
     or cardinality(coalesce(p_flagged, '{}')) > 150
     or exists (select 1 from unnest(coalesce(p_flagged, '{}')) f where f is null or f not between 0 and cardinality(m.question_ids) - 1) then
    raise exception 'bad progress';
  end if;
  update public.study_mock_attempts x
     set position = p_position, flagged = (select coalesce(array_agg(distinct f order by f), '{}') from unnest(coalesce(p_flagged, '{}')) f)
   where x.id = a.id;
  return true;
end;
$$;

-- One pick ("לא יודעים" or a cleared pick: both null), kept on the attempt
-- until it is submitted; it may change until then. Nothing comes back but
-- whether it was kept: false once the time is up (the attempt is submitted
-- now, 10 seconds' grace for a pick sent on the last second). 'attempt not
-- found', 'question not found', 'bad choice', 'bad choices'.
create or replace function public.study_mock_answer(p_attempt uuid, p_question uuid, p_choice int, p_choices int[], p_ms int default null)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  a public.study_mock_attempts;
  m public.study_mocks;
  q public.study_questions;
  np int;
begin
  a := study_private.attempt_for(p_attempt);
  if a.finished_at is not null then return false; end if;
  if now() >= a.deadline + interval '10 seconds' then perform public.study_mock_finish(a.id); return false; end if;
  select * into m from public.study_mocks x where x.id = a.mock_id;
  if not (p_question = any (m.question_ids)) then raise exception 'question not found'; end if;
  select * into q from public.study_questions x where x.id = p_question;
  if p_choice is null and p_choices is null then
    update public.study_mock_attempts x set picks = x.picks - p_question::text where x.id = a.id;
    return true;
  end if;
  if q.form = 'one' then
    if p_choices is not null or p_choice not between 0 and cardinality(q.options) - 1 then raise exception 'bad choice'; end if;
  else
    np := case when q.form = 'match' then jsonb_array_length(coalesce(q.layout -> 'prompts', '[]'::jsonb)) else cardinality(q.options) end;
    if p_choice is not null or cardinality(p_choices) <> np
       or exists (select 1 from unnest(p_choices) c where c is null or c < 0 or c >= cardinality(q.options))
       or (q.form = 'tf' and exists (select 1 from unnest(p_choices) c where c not in (0, 1)))
       or (q.form = 'match' and (select count(distinct c) from unnest(p_choices) c) <> np) then
      raise exception 'bad choices';
    end if;
  end if;
  update public.study_mock_attempts x
     set picks = x.picks || jsonb_build_object(p_question::text,
                   jsonb_strip_nulls(jsonb_build_object('c', p_choice, 'cs', to_jsonb(p_choices),
                                                        'ms', case when p_ms between 0 and 3600000 then p_ms end)))
   where x.id = a.id;
  return true;
end;
$$;

-- A suggested answer the app is not sure of (solved, confidence under 3)
-- counts in no score (decision 2): practising such an item writes no
-- answer row, whichever function answers it (study_answer_question,
-- study_answer_set, a quiz), so "הטעויות שלי", progress and repeats never
-- see it. Once a member confirms or marks the key, answers count again.
-- (A simulation leaves these items out itself: they are not counted.)
create or replace function study_private.answers_skip_unsure()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.study_question_keys k
              where k.question_id = new.question_id and k.key_origin = 'solved' and coalesce(k.key_conf, 0) < 3) then
    return null;
  end if;
  return new;
end;
$$;
revoke all on function study_private.answers_skip_unsure() from public;
drop trigger if exists study_answers_skip_unsure on public.study_answers;
create trigger study_answers_skip_unsure before insert on public.study_answers
  for each row execute function study_private.answers_skip_unsure();

-- ── RLS, grants ──
alter table public.study_exam_pages    enable row level security;
alter table public.study_exam_key_log  enable row level security;
alter table public.study_exam_item_log enable row level security;
alter table public.study_mocks         enable row level security;
alter table public.study_mock_attempts enable row level security;
drop policy if exists "study exam pages read" on public.study_exam_pages;
drop policy if exists "study exam key log read" on public.study_exam_key_log;
drop policy if exists "study exam item log read" on public.study_exam_item_log;
drop policy if exists "study mocks read" on public.study_mocks;
drop policy if exists "study mock attempts own" on public.study_mock_attempts;
create policy "study exam pages read" on public.study_exam_pages for select using (public.study_is_member(public.study_exam_group(exam_id)));
create policy "study exam key log read" on public.study_exam_key_log for select using (public.study_is_member(public.study_exam_group(exam_id)));
create policy "study exam item log read" on public.study_exam_item_log for select using (public.study_is_member(public.study_exam_group(exam_id)));
create policy "study mocks read" on public.study_mocks for select using (public.study_is_member(group_id));
create policy "study mock attempts own" on public.study_mock_attempts for select using (member_id = auth.uid());
revoke all on public.study_exam_pages, public.study_exam_key_log, public.study_exam_item_log, public.study_mocks,
  public.study_mock_attempts from anon, authenticated;
grant select on public.study_exam_pages, public.study_exam_key_log, public.study_exam_item_log, public.study_mocks,
  public.study_mock_attempts to authenticated;

-- Exam pages go only to an exam its member is uploading, as
-- <group>/exams/<exam>/p<n>.jpg exactly, while the switch is on (B1 S 2);
-- everything else in the bucket as before. The same page may be sent
-- again while it uploads (an upload that stopped, "לנסות שוב": Storage's
-- upsert needs an update policy). Only that uploader deletes a page, and
-- only while it uploads; a lecture's slides, a wall photo as before.
create or replace function public.study_exam_page_writable(p_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.study_feature_on('exams'), false)
     and p_name ~ '^[0-9a-f-]{36}/exams/[0-9a-f-]{36}/p[0-9]{1,3}\.jpg$'
     and exists (select 1 from public.study_exams e
                  where e.id::text = split_part(p_name, '/', 3) and e.group_id::text = split_part(p_name, '/', 1)
                    and e.status = 'uploading' and e.deleted_at is null and e.created_by = auth.uid())
$$;
revoke all on function public.study_exam_page_writable(text) from public, anon;
grant execute on function public.study_exam_page_writable(text) to authenticated;
drop policy if exists "study files add" on storage.objects;
create policy "study files add" on storage.objects
  for insert with check (
    bucket_id = 'study' and public.study_is_member_path(name)
    and (split_part(name, '/', 2) <> 'exams' or public.study_exam_page_writable(name)));
drop policy if exists "study exam pages replace" on storage.objects;
create policy "study exam pages replace" on storage.objects
  for update using (bucket_id = 'study' and public.study_is_member_path(name) and public.study_exam_page_writable(name))
  with check (bucket_id = 'study' and public.study_is_member_path(name) and public.study_exam_page_writable(name));
-- Section F's delete rule (slides of a live lecture, wall photos by their
-- author) and now exam pages: only while their uploader uploads them, or
-- once their exam is deleted.
drop policy if exists "study files delete" on storage.objects;
create policy "study files delete" on storage.objects
  for delete using (
    bucket_id = 'study' and public.study_is_member_path(name)
    and not (split_part(name, '/', 3) ~ '^s[0-9]+-[0-9]+\.jpg$'
             and exists (select 1 from public.study_lectures l
                          where l.id::text = split_part(name, '/', 2)
                            and (l.deleted_at is null or l.deleted_at > now() - interval '30 days')))
    and (split_part(name, '/', 2) <> 'wall' or owner_id = auth.uid()::text)
    and (split_part(name, '/', 2) <> 'exams' or public.study_exam_page_writable(name)
         or not exists (select 1 from public.study_exams e where e.id::text = split_part(name, '/', 3) and e.deleted_at is null)));

revoke all on function public.study_exam_create(uuid, jsonb), public.study_exam_pages_done(uuid, jsonb, jsonb, timestamptz, text),
  public.study_exam_status(uuid), public.study_exam_review(uuid), public.study_exam_item_edit(uuid, text, int, text),
  public.study_set_exam_key(uuid, int), public.study_exam_key_undo(uuid), public.study_exam_retry(uuid, int[], jsonb, timestamptz),
  public.study_exam_hide(uuid, boolean), public.study_course_style_items(uuid, text), public.study_claim_exam(uuid, text),
  public.study_exam_save_items(uuid, uuid, jsonb, int, text), public.study_exam_save_keys(uuid, uuid, jsonb, text),
  public.study_finish_exam_job(uuid, uuid, text, text, numeric, text), public.study_mock_create(uuid, text, uuid, int, int, boolean),
  public.study_mock_finish(uuid), public.study_mock_get(uuid), public.study_mock_start(uuid), public.study_mock_progress(uuid, int, int[]),
  public.study_mock_answer(uuid, uuid, int, int[], int), public.study_exam_key_confirm(uuid)
  from public, anon;
grant execute on function public.study_exam_create(uuid, jsonb), public.study_exam_status(uuid), public.study_exam_review(uuid),
  public.study_exam_item_edit(uuid, text, int, text), public.study_set_exam_key(uuid, int), public.study_exam_key_undo(uuid),
  public.study_exam_retry(uuid, int[], jsonb, timestamptz), public.study_exam_hide(uuid, boolean), public.study_course_style_items(uuid, text),
  public.study_mock_create(uuid, text, uuid, int, int, boolean), public.study_mock_finish(uuid), public.study_mock_get(uuid),
  public.study_mock_start(uuid), public.study_mock_progress(uuid, int, int[]), public.study_mock_answer(uuid, uuid, int, int[], int),
  public.study_exam_key_confirm(uuid)
  to authenticated;
-- The worker's: the key inside; the worker calls as anon, the phone's op with the member's token.
grant execute on function public.study_exam_pages_done(uuid, jsonb, jsonb, timestamptz, text) to authenticated;
grant execute on function public.study_claim_exam(uuid, text), public.study_exam_save_items(uuid, uuid, jsonb, int, text),
  public.study_exam_save_keys(uuid, uuid, jsonb, text), public.study_finish_exam_job(uuid, uuid, text, text, numeric, text)
  to anon, authenticated;

-- The exams' sweeper: every minute, beside section W's (only with pg_cron).
do $$
begin
  if to_regnamespace('cron') is not null then
    perform cron.schedule('study-exam-dispatch', '* * * * *', 'select study_private.exam_dispatch()');
  end if;
end $$;

-- The switch 'exams' is section F's row, off; S 2 leaves it off (Yoad turns it on).
insert into study_private.features (name) values ('exams') on conflict (name) do nothing;

insert into study_private.schema_sections (section, version) values ('S', 2)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ════ END SECTION S ════

-- ════ BEGIN SECTION I · the personal code (package I) ════
--  docs/study/personal-code.md; decision 1 of 17 Nov 2026, amended.
--  A member's personal code brings back the SAME member on any device: the
--  same anonymous auth user, so the same name, progress, answers and cards.
--  No row moves between users and Row Level Security does not change.
--
--  How a device comes back: /api/study/code (the server key, the caller's
--  address) calls study_code_redeem(code). For 3 minutes at most, the
--  member's own auth user gets a random address and a random one-time
--  password; the device signs in with them at once (Auth's password sign-in,
--  supabase.auth.signInWithPassword) and calls study_code_finish(), which
--  puts the user back as it was: no address, no password, still anonymous.
--  study_private.code_restore() does the same for a device that never
--  finished (every redeem, every status read, and pg_cron every 5 minutes).
--
--  The code: 16 characters from 32 (80 bits), stored only as sha256. Wrong
--  tries: 10 per address per 15 minutes, 1000 in all per hour (a backstop
--  only: at 80 bits even that guesses nothing; low enough a cap would let a
--  few addresses lock every member out).
--
--  A new code, the opener's code and "seen" need a session Auth still has
--  (auth.sessions): "ניתוק המכשירים האחרים" deletes the other sessions, and
--  their access tokens, good up to an hour, can no longer mint a code.
--
--  The switch "codes" (study_private.features; no row = on) stops new
--  codes and every redeem at once, without touching sessions:
--    insert into study_private.features (name, enabled) values ('codes', false)
--    on conflict (name) do update set enabled = excluded.enabled, changed_at = now();
--
--  Re-runnable. Part 9 of supabase/parts starts with this section; the
--  sections after it (R, notifications, first) follow it there.

-- The install check, before anything is created: the definer (postgres on
-- Supabase) writes these auth.users columns, bypasses the table's row level
-- security (as study_member_saved already does to read it), reads
-- auth.sessions, and pgcrypto is in schema extensions. Otherwise the run
-- stops here and nothing changes.
do $$
declare c text;
begin
  foreach c in array array['email', 'encrypted_password', 'email_confirmed_at', 'updated_at', 'email_change',
                           'email_change_token_new', 'email_change_token_current', 'email_change_confirm_status'] loop
    if not has_column_privilege('auth.users', c, 'UPDATE') then
      raise exception 'section I: this role cannot update auth.users.% (the personal code needs it)', c;
    end if;
  end loop;
  if not (select r.rolbypassrls or r.rolsuper from pg_roles r where r.rolname = current_user) then
    raise exception 'section I: this role does not bypass row level security on auth.users';
  end if;
  if to_regclass('auth.sessions') is null or not has_table_privilege('auth.sessions', 'SELECT') then
    raise exception 'section I: this role cannot read auth.sessions (a code needs a live session)';
  end if;
  if to_regprocedure('extensions.crypt(text,text)') is null or to_regprocedure('extensions.gen_salt(text,integer)') is null
     or to_regprocedure('extensions.gen_random_bytes(integer)') is null then
    raise exception 'section I: pgcrypto is not in schema extensions (Database → Extensions → pgcrypto)';
  end if;
end $$;

create table if not exists study_private.member_codes (
  user_id    uuid        primary key references auth.users (id) on delete cascade,
  code_hash  bytea       not null unique,          -- code_hash(code); the code itself is never stored
  created_at timestamptz not null default now(),
  issued_by  uuid        references auth.users (id) on delete set null,  -- the member, or the group's opener
  seen_at    timestamptz,                          -- the member saw "the opener made you a new code"
  used_at    timestamptz,
  uses       int         not null default 0,
  replaced   boolean     not null default false     -- this code replaced an earlier one
);
alter table study_private.member_codes add column if not exists replaced boolean not null default false;
-- Wrong (and right) tries, for the limits; ip is a hash of the address, kept a day.
create table if not exists study_private.code_tries (
  id bigint      generated always as identity primary key,
  at timestamptz not null default now(),
  ok boolean     not null,
  ip text        not null default ''
);
create index if not exists code_tries_at on study_private.code_tries (at);
-- A user who has a one-time address and password right now, and what to put back.
create table if not exists study_private.code_pending (
  user_id    uuid        primary key references auth.users (id) on delete cascade,
  email      text        not null,
  until      timestamptz not null,
  prev_email text,
  prev_pw    text,
  prev_conf  timestamptz
);
-- Who made which code, and each redeem (no code, no address).
create table if not exists study_private.code_log (
  id      bigint      generated always as identity primary key,
  user_id uuid        not null,
  event   text        not null check (event in ('new', 'issued', 'redeemed', 'dropped')),
  by_user uuid,
  at      timestamptz not null default now()
);

-- 16 characters from 32 (no 0/O, no 1/I): 80 bits. 256 is a multiple of 32,
-- so a random byte mod 32 has no bias. Shown as XXXX-XXXX-XXXX-XXXX.
create or replace function study_private.code_make()
returns text language plpgsql volatile set search_path = '' as $$
declare
  alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  b bytea := extensions.gen_random_bytes(16);
  c text := '';
begin
  for i in 0..15 loop
    c := c || substr(alphabet, 1 + get_byte(b, i) % 32, 1);
  end loop;
  return substr(c, 1, 4) || '-' || substr(c, 5, 4) || '-' || substr(c, 9, 4) || '-' || substr(c, 13, 4);
end $$;

-- The 16 characters, upper case, without dashes or spaces; '' for anything else.
create or replace function study_private.code_norm(p text)
returns text language sql immutable set search_path = '' as $$
  select case when x ~ '^[2-9A-HJ-NP-Z]{16}$' then x else '' end
    from (select upper(regexp_replace(coalesce(p, ''), '[\s-]', '', 'g')) as x) s
$$;

create or replace function study_private.code_hash(p text)
returns bytea language sql immutable set search_path = '' as $$
  select sha256(convert_to('tamtzit-code-v1:' || study_private.code_norm(p), 'UTF8'))
$$;

-- Only an anonymous study member with no real address carries a code, so a
-- password is never written on another app's user in the shared project.
create or replace function study_private.code_target_ok(p_user uuid)
returns boolean language sql stable set search_path = '' as $$
  select exists (select 1 from auth.users u
                  where u.id = p_user and u.is_anonymous and not coalesce(u.is_sso_user, false)
                    and (u.email is null or u.email = '' or u.email like 'c-%@code.tamtzit.invalid'))
     and exists (select 1 from public.study_members m where m.user_id = p_user)
$$;

-- The caller's session is one Auth still has. "ניתוק המכשירים האחרים"
-- (signOut scope "others") deletes the other sessions at once, but their
-- access tokens stay valid until they expire (an hour): without this, such
-- a token could make a new code and undo the rotation that came with it.
create or replace function study_private.code_session_ok()
returns boolean language sql stable set search_path = '' as $$
  select exists (select 1 from auth.sessions s
                  where s.id::text = auth.jwt() ->> 'session_id' and s.user_id = auth.uid())
$$;

create or replace function study_private.code_set(p_user uuid, p_by uuid)
returns text language plpgsql volatile set search_path = '' as $$
declare v text := study_private.code_make();
begin
  insert into study_private.member_codes (user_id, code_hash, issued_by)
  values (p_user, study_private.code_hash(v), p_by)
  on conflict (user_id) do update
    set code_hash = excluded.code_hash, created_at = now(), issued_by = excluded.issued_by,
        seen_at = null, used_at = null, uses = 0, replaced = true;
  insert into study_private.code_log (user_id, event, by_user)
  values (p_user, case when p_by = p_user then 'new' else 'issued' end, p_by);
  return v;
end $$;

-- Puts back each user whose 3 minutes are over (all of them for null; with
-- p_user, also that one now): the address, password and confirmation from
-- before, and no email change waiting (one asked for in the 3 minutes must
-- never complete). One-time tokens go too, where this role may delete them.
create or replace function study_private.code_restore(p_user uuid default null)
returns int language plpgsql volatile set search_path = '' as $$
declare n int; ids uuid[];
begin
  if not exists (select 1 from study_private.code_pending p where p.until < now() or p.user_id = p_user) then
    return 0;
  end if;
  -- The redeem's lock (re-entrant inside a redeem): a sweep or a status read
  -- must never restore and delete a pending row while a redeem reads the
  -- user's one-time values as the member's own "before".
  perform pg_advisory_xact_lock(hashtext('study_code_redeem'));
  select coalesce(array_agg(p.user_id), '{}') into ids from study_private.code_pending p
   where p.until < now() or p.user_id = p_user;
  if cardinality(ids) = 0 then return 0; end if;
  update auth.users u
     set email = p.prev_email, encrypted_password = coalesce(p.prev_pw, ''), email_confirmed_at = p.prev_conf,
         email_change = '', email_change_token_new = '', email_change_token_current = '',
         email_change_confirm_status = 0, updated_at = now()
    from study_private.code_pending p
   where p.user_id = u.id and p.user_id = any (ids);
  get diagnostics n = row_count;
  delete from study_private.code_pending p where p.user_id = any (ids);
  if to_regclass('auth.one_time_tokens') is not null then
    begin
      execute 'delete from auth.one_time_tokens where user_id = any ($1)' using ids;
    exception when insufficient_privilege then null;
    end;
  end if;
  return n;
end $$;

-- ── The member's own code ──
-- A new code for the caller; the one before stops working at once.
create or replace function public.study_code_new()
returns text language plpgsql volatile security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not study_private.code_session_ok() then raise exception 'session ended'; end if;
  if not study_private.feature_on('codes') then raise exception 'off'; end if;
  if not study_private.code_target_ok(auth.uid()) then raise exception 'no code here'; end if;
  return study_private.code_set(auth.uid(), auth.uid());
end $$;

-- Whether the caller has a code, since when, whether the group's opener made
-- it (and who), whether the member has yet to see that, whether it replaced
-- an earlier code, and when and how often it brought a device in (so a
-- member sees an opener's code that someone already used).
drop function if exists public.study_code_status();
create or replace function public.study_code_status()
returns table (has_code boolean, created_at timestamptz, by_opener boolean, by_name text, notice boolean,
               replaced boolean, used_at timestamptz, uses int)
language plpgsql volatile security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform study_private.code_restore();
  return query
  select c.user_id is not null, c.created_at,
         coalesce(c.issued_by is distinct from c.user_id, false),
         (select m.name from public.study_members m
           where m.user_id = c.issued_by and c.issued_by is distinct from c.user_id
             and m.group_id in (select x.group_id from public.study_members x where x.user_id = auth.uid())
           limit 1),
         coalesce(c.issued_by is distinct from c.user_id and c.seen_at is null, false),
         coalesce(c.replaced, false), c.used_at, coalesce(c.uses, 0)
    from (select auth.uid() as me) w
    left join study_private.member_codes c on c.user_id = w.me;
end $$;

create or replace function public.study_code_seen()
returns void language sql volatile security definer set search_path = '' as $$
  update study_private.member_codes set seen_at = now()
   where user_id = auth.uid() and seen_at is null and study_private.code_session_ok()
$$;

-- ── The group's opener makes a new code for a member who lost theirs ──
create or replace function public.study_code_issue(p_group uuid, p_user uuid)
returns text language plpgsql volatile security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not study_private.code_session_ok() then raise exception 'session ended'; end if;
  if not exists (select 1 from public.study_groups g where g.id = p_group and g.created_by = auth.uid()) then
    raise exception 'not the creator';
  end if;
  if not exists (select 1 from public.study_members m where m.group_id = p_group and m.user_id = p_user) then
    raise exception 'member not found';
  end if;
  -- A code is the member's whole identity: never one for a member who is
  -- also in a group the caller did not open (one group today; a guard for
  -- the day study_create_group allows more).
  if exists (select 1 from public.study_members m join public.study_groups g on g.id = m.group_id
              where m.user_id = p_user and g.created_by is distinct from auth.uid()) then
    raise exception 'not the creator';
  end if;
  if not study_private.feature_on('codes') then raise exception 'off'; end if;
  if not study_private.code_target_ok(p_user) then raise exception 'no code here'; end if;
  return study_private.code_set(p_user, auth.uid());
end $$;

-- ── Any device: the code in, a one-time sign-in out ──
-- Only /api/study/code calls it (the server key; p_ip is the caller's
-- address as Vercel saw it). Never raises for a wrong code: a raise would
-- undo the try's row, and the limit would count nothing. Answers
-- {"error": "code not found" | "too many tries" | "codes off"} or
-- {"email": …, "password": …} for Auth's password sign-in, good 3 minutes.
create or replace function public.study_code_redeem(p_code text, p_ip text, p_key text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare
  v_ip text;
  who  uuid;
  em   text;
  pw   text;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  -- The address, hashed with the server key: not recoverable from the row.
  v_ip := encode(sha256(convert_to('tamtzit-ip:' || coalesce(study_private.secret('study_worker_key'), '') || ':'
                                   || coalesce(p_ip, ''), 'UTF8')), 'hex');
  perform pg_advisory_xact_lock(hashtext('study_code_redeem'));
  perform study_private.code_restore();
  if not study_private.feature_on('codes') then return jsonb_build_object('error', 'codes off'); end if;
  if (select count(*) from study_private.code_tries t where not t.ok and t.at > now() - interval '1 hour') >= 1000
     or (select count(*) from study_private.code_tries t
          where not t.ok and t.ip = v_ip and t.at > now() - interval '15 minutes') >= 10 then
    return jsonb_build_object('error', 'too many tries');
  end if;
  select c.user_id into who from study_private.member_codes c
   where c.code_hash = study_private.code_hash(p_code) and study_private.code_norm(p_code) <> '' for update;
  if who is null or not study_private.code_target_ok(who) then
    insert into study_private.code_tries (ok, ip) values (false, v_ip);
    return jsonb_build_object('error', 'code not found');
  end if;
  insert into study_private.code_tries (ok, ip) values (true, v_ip);
  delete from study_private.code_tries t where t.at < now() - interval '1 day';
  em := 'c-' || encode(extensions.gen_random_bytes(9), 'hex') || '@code.tamtzit.invalid';
  pw := encode(extensions.gen_random_bytes(24), 'hex');
  -- The first redeem's "before" is kept: a second one inside the 3 minutes
  -- must not take the first's one-time values for the member's own. And a
  -- one-time address is never a "before" (a member has none of their own).
  insert into study_private.code_pending (user_id, email, until, prev_email, prev_pw, prev_conf)
  select u.id, em, now() + interval '3 minutes',
         case when synth then null else u.email end,
         case when synth then '' else u.encrypted_password end,
         case when synth then null else u.email_confirmed_at end
    from auth.users u, lateral (select coalesce(u.email like 'c-%@code.tamtzit.invalid', false) as synth) x
   where u.id = who
  on conflict (user_id) do update set email = excluded.email, until = excluded.until;
  -- bcrypt at cost 10 ($2a$10$, what GoTrue writes): GoTrue neither
  -- rehashes nor rewrites it on sign-in.
  update auth.users u
     set email = em, encrypted_password = extensions.crypt(pw, extensions.gen_salt('bf', 10)),
         email_confirmed_at = now(), updated_at = now()
   where u.id = who;
  if not found then return jsonb_build_object('error', 'codes off'); end if;
  update study_private.member_codes c set used_at = now(), uses = c.uses + 1 where c.user_id = who;
  insert into study_private.code_log (user_id, event) values (who, 'redeemed');
  return jsonb_build_object('email', em, 'password', pw);
end $$;

-- Right after the sign-in: the caller's user goes back to how it was.
create or replace function public.study_code_finish()
returns void language plpgsql volatile security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform study_private.code_restore(auth.uid());
end $$;

-- A member who leaves (or is removed from) their last group loses the code.
create or replace function study_private.code_drop_on_leave()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.study_members m where m.user_id = old.user_id) then
    delete from study_private.member_codes c where c.user_id = old.user_id;
    if found then insert into study_private.code_log (user_id, event, by_user) values (old.user_id, 'dropped', auth.uid()); end if;
  end if;
  return old;
end $$;
drop trigger if exists study_members_code_drop on public.study_members;
create trigger study_members_code_drop after delete on public.study_members
  for each row execute function study_private.code_drop_on_leave();

-- The chip beside a name ("יש קוד"): a saved account (none since decision 1)
-- or a personal code. Same name, arguments and result as section F's.
create or replace function public.study_member_saved(p_group uuid)
returns table (user_id uuid, saved boolean) language sql stable security definer set search_path = public as $$
  select m.user_id, not coalesce(u.is_anonymous, true)
                    or exists (select 1 from study_private.member_codes c where c.user_id = m.user_id)
    from public.study_members m left join auth.users u on u.id = m.user_id
   where m.group_id = p_group and public.study_is_member(p_group)
$$;

revoke all on function study_private.code_make(), study_private.code_norm(text), study_private.code_hash(text),
  study_private.code_target_ok(uuid), study_private.code_set(uuid, uuid), study_private.code_restore(uuid),
  study_private.code_drop_on_leave() from public;
revoke all on function public.study_code_new(), public.study_code_status(), public.study_code_seen(),
  public.study_code_issue(uuid, uuid), public.study_code_finish() from public, anon;
revoke all on function public.study_code_redeem(text, text, text) from public, anon, authenticated;
grant execute on function public.study_code_new(), public.study_code_status(), public.study_code_seen(),
  public.study_code_issue(uuid, uuid), public.study_code_finish() to authenticated;
-- The server calls it with the anon key; it refuses without the server key (F27's allow-list).
grant execute on function public.study_code_redeem(text, text, text) to anon;

-- Every 5 minutes, beside section W's sweeper (only with pg_cron).
do $$
begin
  if to_regnamespace('cron') is not null then
    perform cron.schedule('study-code-restore', '*/5 * * * *', 'select study_private.code_restore()');
  end if;
end $$;

insert into study_private.schema_sections (section, version) values ('I', 1)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ════ END SECTION I ════

-- ════ BEGIN SECTION R · notifications and the inbox (package R) ════
--  docs/study/DECISIONS-2026-11-26.md (notifications, section R, revision 2).
--  A member hears about the few things worth a tap. Every notice is first a
--  row in the member's inbox (public.study_notices, the bell); a push to the
--  member's phones and computers is only a way of delivering it, kept apart
--  in study_private.notify_outbox so Realtime never carries push state.
--
--  R 1: the tables, the kind registry, notice_add() (the one way any
--  package adds a notice), the member and worker RPCs, the hooks of a group
--  quiz opened, a reply in a thread, a summary ready or stopped, a member
--  leaving, the "someone signed in with your personal code" scan, the minute
--  job and the switches.
--  R 2 (this version): the remaining hooks (a group challenge, the reading
--  started, a credit asked, a dispute opened and decided, a past exam read,
--  "עדכון", a correction waiting, a meeting set, a new summary for the rest
--  of the group) and, in the minute job, the meeting in 15 minutes, the
--  study day in 30, "שאלה פתוחה שאפשר לעזור בה" at 17:00 and the daily
--  reminder at each person's hour (off by default).
--
--  The database stores no Hebrew: a notice keeps kind, args, count, route
--  and obj; shared/study/notifyCopy.ts writes the words for the lock screen
--  and the inbox. No lock screen ever shows a quiz title, a name, or comment,
--  question or summary text.
--
--  The switches (study_private.features):
--    notify        inserted off: nothing is pushed, except to the users in
--                  study_private.notify_pilot; the inbox keeps filling.
--    notify_hooks  inserted on: off, no new notice at all (every hook stops
--                  at its first line).
--      update study_private.features set enabled = true, changed_at = now() where name = 'notify';
--
--  Another package adds notices only through
--    study_private.notice_add(user, group, kind, args, route, obj, dedupe, lecture, ends)
--  after checking to_regprocedure('study_private.notice_add(uuid,uuid,text,jsonb,jsonb,text,text,uuid,timestamptz)'),
--  and registers its kinds in study_private.notice_kinds. An unknown kind is
--  safe: it stays in the inbox for a day and never pushes.
--
--  A hook never fails the write that fired it: each catches its own errors,
--  and notice_add gives up on a lock after 200 ms.
--
--  Realtime carries study_notices only so the bell can count: its INSERT and
--  UPDATE events follow the select-own policy, but Supabase sends DELETE
--  events (the primary key only) to any subscriber of the table. Those ids
--  and their timing are all it can leak; the app subscribes to inserts and
--  updates only.
--
--  Needs sections F and W (feature_on, server_on, secret, is_worker) and I
--  (code_log, for the sign-in scan). Re-runnable throughout.

-- ── Devices: one row per push subscription; a member has several ──
create table if not exists public.study_push_subs (
  id         bigint      generated always as identity primary key,
  user_id    uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  endpoint   text        not null unique check (char_length(endpoint) between 20 and 1000),
  p256dh     text        not null check (p256dh ~ '^[A-Za-z0-9_-]{86,88}$'),
  auth       text        not null check (auth ~ '^[A-Za-z0-9_-]{21,24}$'),
  key_id     text        not null check (char_length(key_id) between 8 and 16),   -- prefix of sha256(the VAPID public key)
  device     text        not null default 'other'
                         check (device in ('iphone', 'ipad', 'android', 'mac', 'windows', 'linux', 'other')),
  browser    text        not null default '' check (char_length(browser) <= 20),
  created_at timestamptz not null default now(),
  seen_at    timestamptz not null default now(),   -- the app's last resync on that device
  ok_at      timestamptz,                          -- the push service's last 2xx
  fails      int         not null default 0
);
create index if not exists study_push_subs_user on public.study_push_subs (user_id);
alter table public.study_push_subs enable row level security;   -- no policy: only the definer RPCs below
revoke all on public.study_push_subs from anon, authenticated;

-- ── Each person's settings (the defaults are Yoad's answers of 26 Nov 2026) ──
-- No row: the defaults (study_private.notify_prefs_of, which a check compares).
create table if not exists public.study_notify_prefs (
  user_id    uuid        primary key default auth.uid() references auth.users (id) on delete cascade,
  live       boolean     not null default true,    -- "עכשיו בקבוצה": a quiz opened, a meeting starting
  mine       boolean     not null default true,    -- "בשבילך": replies, answers, what I uploaded is ready
  digest     boolean     not null default false,   -- the daily reminder (R 2), off by default
  digest_at  time        not null default '19:30',
  quiet      boolean     not null default true,    -- no push at night
  quiet_from time        not null default '23:00',
  quiet_to   time        not null default '07:30',
  shabbat    boolean     not null default false,   -- Friday 16:00 to Saturday 20:30, Israel time
  updated_at timestamptz not null default now()
);
alter table public.study_notify_prefs enable row level security;
drop policy if exists "study notify prefs own" on public.study_notify_prefs;
create policy "study notify prefs own" on public.study_notify_prefs for select to authenticated using (user_id = auth.uid());
revoke all on public.study_notify_prefs from anon, authenticated;
grant select on public.study_notify_prefs to authenticated;

-- ── The inbox. A row changes only when it is added, coalesced or seen ──
-- obj: what a screen "sees" ('lec:<id>', 'quiz:<id>', 'exam:<id>', 'meet:<id>',
-- 'disp:<id>', 'wall:<id>'): opening that screen marks the row seen.
-- dedupe: rows with the same key coalesce (count + 1) while unseen.
create table if not exists public.study_notices (
  id         bigint      generated always as identity primary key,
  user_id    uuid        not null references auth.users (id) on delete cascade,
  group_id   uuid        references public.study_groups (id) on delete cascade,     -- null: the security notice
  lecture_id uuid        references public.study_lectures (id) on delete cascade,   -- titles go with their lecture
  kind       text        not null check (kind ~ '^[a-z_]{2,20}$'),
  cat        text        not null check (cat in ('live', 'mine', 'digest', 'security', 'inapp')),
  args       jsonb       not null default '{}' check (jsonb_typeof(args) = 'object' and pg_column_size(args) <= 1200),
  route      jsonb       not null default '{}' check (jsonb_typeof(route) = 'object' and pg_column_size(route) <= 400),
  obj        text        check (char_length(obj) <= 60),
  count      int         not null default 1 check (count between 1 and 999),
  dedupe     text        not null check (char_length(dedupe) between 1 and 120),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  seen_at    timestamptz,
  ends_at    timestamptz
);
-- Coalescing: only an unseen row conflicts, so a seen row never swallows a new event.
create unique index if not exists study_notices_open on public.study_notices (user_id, dedupe) where seen_at is null;
create index if not exists study_notices_mine on public.study_notices (user_id, updated_at desc);
create index if not exists study_notices_obj on public.study_notices (user_id, obj) where seen_at is null;
create index if not exists study_notices_lecture on public.study_notices (lecture_id) where lecture_id is not null;
create index if not exists study_notices_group on public.study_notices (group_id, user_id);
-- The minute job's ending of live rows (a quiz over, a meeting cancelled) reads only unseen live rows.
create index if not exists study_notices_live on public.study_notices (kind) where seen_at is null and cat = 'live';
alter table public.study_notices enable row level security;
drop policy if exists "study notices own" on public.study_notices;
create policy "study notices own" on public.study_notices for select to authenticated using (user_id = auth.uid());
revoke all on public.study_notices from anon, authenticated;
grant select on public.study_notices to authenticated;
do $$ begin
  alter publication supabase_realtime add table public.study_notices;
exception
  when duplicate_object then null;
  when undefined_object then raise notice 'no supabase_realtime publication: the bell updates on each open only';
end $$;

-- ── The push side, private: members never read it and Realtime never carries it ──
create table if not exists study_private.notify_outbox (
  notice_id   bigint      primary key references public.study_notices (id) on delete cascade,
  user_id     uuid        not null,
  group_id    uuid,
  kind        text        not null,
  cat         text        not null,
  state       text        not null default 'due'
              check (state in ('due', 'sending', 'sent', 'quiet', 'capped', 'held', 'nosub', 'off', 'none', 'failed', 'expired')),
  not_before  timestamptz not null default now(),
  expires_at  timestamptz not null,
  lease_until timestamptz,
  attempts    int         not null default 0,
  again       boolean     not null default false,   -- coalesced while 'sending': send once more
  pushed_at   timestamptz
);
create index if not exists notify_outbox_due on study_private.notify_outbox (not_before) where state = 'due';
create index if not exists notify_outbox_sent on study_private.notify_outbox (user_id, pushed_at) where state = 'sent';
create index if not exists notify_outbox_group on study_private.notify_outbox (group_id, kind, pushed_at);
create index if not exists notify_outbox_lease on study_private.notify_outbox (lease_until) where state = 'sending';

-- ── The kind registry. cat: live, mine, digest, security or inapp; push
-- false means inbox only; delay holds the push (a quiz's 15 s, so a host can
-- still uncheck "להודיע לקבוצה"; a summary's 90 s, so a member watching it
-- finish gets no push). Each package registers its own kinds in its section.
create table if not exists study_private.notice_kinds (
  kind  text     primary key check (kind ~ '^[a-z_]{2,20}$'),
  cat   text     not null check (cat in ('live', 'mine', 'digest', 'security', 'inapp')),
  ttl   interval not null,
  delay interval not null default '0',
  push  boolean  not null default true
);
insert into study_private.notice_kinds (kind, cat, ttl, delay, push) values
  ('quiz_open',      'live',     '20 minutes', '15 seconds', true),
  ('reply',          'mine',     '3 days',     '0',          true),
  ('answer',         'mine',     '3 days',     '0',          true),
  ('summary_ready',  'mine',     '2 days',     '90 seconds', true),
  ('summary_failed', 'mine',     '2 days',     '90 seconds', true),
  ('code_used',      'security', '1 day',      '0',          true),
  ('test',           'security', '10 minutes', '5 seconds',  true),
  -- R 2: live in the group (a challenge held 15 s like a quiz; a meeting in
  -- 15 minutes; the reading started; a study day in 30 minutes)
  ('boss_open',      'live',     '20 minutes', '15 seconds', true),
  ('meeting_soon',   'live',     '15 minutes', '0',          true),
  ('reading',        'live',     '1 hour',     '0',          true),
  ('session_soon',   'live',     '30 minutes', '0',          true),
  -- R 2: for this member (a past exam read is held 90 s like a summary)
  ('credit_ask',     'mine',     '7 days',     '0',          true),
  ('dispute',        'mine',     '3 days',     '0',          true),
  ('dispute_done',   'mine',     '3 days',     '0',          true),
  ('needs_me',       'mine',     '6 hours',    '0',          true),
  ('exam_ready',     'mine',     '2 days',     '90 seconds', true),
  ('exam_failed',    'mine',     '2 days',     '90 seconds', true),
  -- R 2: the daily reminder (only for those who turned it on)
  ('digest',         'digest',   '12 hours',   '0',          true),
  -- R 2: inbox only
  ('update',         'inapp',    '7 days',     '0',          false),
  ('edit_wait',      'inapp',    '7 days',     '0',          false),
  ('lecture_new',    'inapp',    '7 days',     '0',          false),
  ('meeting_set',    'inapp',    '7 days',     '0',          false),
  -- Reserved for packages not built yet (Yoad, 26 Nov 2026): their sections
  -- wire them. A practice set shared with the group, similar questions
  -- ready, a new run of the model comparison.
  ('set_shared',     'mine',     '7 days',     '0',          true),
  ('similar_ready',  'mine',     '2 days',     '90 seconds', true),
  ('lab_new',        'inapp',    '7 days',     '0',          false)
on conflict (kind) do update set cat = excluded.cat, ttl = excluded.ttl, delay = excluded.delay, push = excluded.push;

-- What was pushed: ids and the push service's status only (never an endpoint, args or a key).
create table if not exists study_private.push_log (
  id        bigint      generated always as identity primary key,
  notice_id bigint,
  sub_id    bigint,
  status    int,
  at        timestamptz not null default now()
);
create index if not exists push_log_at on study_private.push_log (at);
-- The kick to /api/study/work, its throttle and its circuit breaker.
create table if not exists study_private.notify_kick (
  id                int         primary key default 1 check (id = 1),
  at                timestamptz,
  kicks_since_claim int         not null default 0,
  stuck_at          timestamptz
);
insert into study_private.notify_kick (id) values (1) on conflict (id) do nothing;
-- Who gets pushes while the switch "notify" is off (the pilot, OD5).
create table if not exists study_private.notify_pilot (
  user_id  uuid        primary key,
  added_at timestamptz not null default now()
);
-- How far the sign-in scan has read study_private.code_log.
create table if not exists study_private.notify_cursor (
  name    text   primary key,
  last_id bigint not null default 0
);
-- Devices a member removed (this device, another one, "ניתוק המכשירים
-- האחרים", or the 10-device cap) within 10 minutes of a sign-in with their
-- personal code, kept aside for 15 minutes: the notice "נכנסו עם הקוד האישי"
-- still reaches them, so whoever signed in with the code cannot silence it by
-- removing the other devices first (study_private.push_set_aside).
create table if not exists study_private.push_removed (
  id         bigint      generated always as identity primary key,
  user_id    uuid        not null references auth.users (id) on delete cascade,
  endpoint   text        not null,
  p256dh     text        not null,
  auth       text        not null,
  key_id     text        not null,
  seen_at    timestamptz not null,
  removed_at timestamptz not null default now()
);
create index if not exists push_removed_user on study_private.push_removed (user_id, removed_at);
-- Quizzes whose host unchecked "להודיע לקבוצה".
create table if not exists study_private.quiz_quiet (
  quiz_id uuid        primary key,
  at      timestamptz not null default now()
);

insert into study_private.features (name, enabled) values ('notify', false), ('notify_hooks', true)
on conflict (name) do nothing;

-- ── Helpers ──

-- A push endpoint the server may post to: https, one of the push services'
-- hosts, no user, no port (OD: the same list as server/study/push.ts).
create or replace function study_private.push_host_ok(p_endpoint text)
returns boolean language plpgsql immutable set search_path = public as $$
declare m text[];
begin
  if p_endpoint is null or char_length(p_endpoint) not between 20 and 1000 then return false; end if;
  m := regexp_match(p_endpoint, '^https://([a-z0-9.-]+)(/[!-~]*)?$');
  if m is null then return false; end if;
  return m[1] in ('fcm.googleapis.com', 'updates.push.services.mozilla.com', 'web.push.apple.com')
      or m[1] ~ '^[a-z0-9-]+(\.[a-z0-9-]+)*\.push\.apple\.com$'
      or m[1] ~ '^[a-z0-9-]+(\.[a-z0-9-]+)*\.notify\.windows\.com$';
end;
$$;

-- A route's id, or null when it is not one (a route is data: never a failed cast).
create or replace function study_private.uuid_or_null(p text)
returns uuid language sql immutable set search_path = public as $$
  select case when p ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then p::uuid end
$$;

-- Devices about to be removed by their member, set aside for 15 minutes when
-- that member's personal code was redeemed in the last 10 (see push_removed).
create or replace function study_private.push_set_aside(p_user uuid, p_ids bigint[])
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if p_user is null or cardinality(coalesce(p_ids, '{}')) = 0 or to_regclass('study_private.code_log') is null then return; end if;
  if not exists (select 1 from study_private.code_log l
                  where l.user_id = p_user and l.event = 'redeemed' and l.at > now() - interval '10 minutes') then
    return;
  end if;
  insert into study_private.push_removed (user_id, endpoint, p256dh, auth, key_id, seen_at)
  select s.user_id, s.endpoint, s.p256dh, s.auth, s.key_id, s.seen_at
    from public.study_push_subs s where s.user_id = p_user and s.id = any (p_ids);
end;
$$;

-- Whether a security notice still has somewhere to go: a device, or one set aside.
create or replace function study_private.push_reachable(p_user uuid, p_cat text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.study_push_subs s where s.user_id = p_user)
      or (p_cat = 'security' and exists (select 1 from study_private.push_removed r
                                          where r.user_id = p_user and r.removed_at > now() - interval '15 minutes'))
$$;

-- Who created the meeting or the study day a live notice is about (for the
-- per-creator throttle), or null.
create or replace function study_private.notify_live_by(p_kind text, p_m text)
returns uuid language plpgsql stable security definer set search_path = public as $$
declare v uuid;
begin
  if p_kind = 'session_soon' then
    if to_regclass('public.study_marathons') is null then return null; end if;
    select k.created_by into v from public.study_marathons k where k.id = study_private.uuid_or_null(p_m);
  elsif p_kind in ('meeting_soon', 'reading') then
    if to_regclass('public.study_meetings') is null then return null; end if;
    select m.created_by into v from public.study_meetings m where m.id = study_private.uuid_or_null(p_m);
  end if;
  return v;
end;
$$;

-- A person's settings, or the defaults when there is no row (the column defaults above).
create or replace function study_private.notify_prefs_of(p_user uuid)
returns public.study_notify_prefs language sql stable security definer set search_path = public as $$
  select coalesce(
    (select p from public.study_notify_prefs p where p.user_id = p_user),
    row(p_user, true, true, false, time '19:30', true, time '23:00', time '07:30', false, null::timestamptz)::public.study_notify_prefs)
$$;

-- Does this person want pushes of this category? Security always; inapp never.
create or replace function study_private.notify_cat_on(p_user uuid, p_cat text)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare p public.study_notify_prefs := study_private.notify_prefs_of(p_user);
begin
  return case p_cat when 'live' then p.live when 'mine' then p.mine when 'digest' then p.digest
                    when 'security' then true else false end;
end;
$$;

-- Null when a push may go now; otherwise when the person's quiet window (the
-- night, Shabbat) ends, Israel time. Windows that touch are passed together
-- (a night ending inside Shabbat waits for Shabbat's end).
-- shared/study/notifyQuiet.ts is the same rule for the settings screen.
create or replace function study_private.notify_quiet(p_user uuid, p_at timestamptz default now())
returns timestamptz language plpgsql stable security definer set search_path = public as $$
declare
  p  public.study_notify_prefs := study_private.notify_prefs_of(p_user);
  t  timestamptz := p_at;
  e  timestamptz;
  lt timestamp;
  tm time;
  dw int;
begin
  for i in 1..4 loop
    e := null;
    lt := t at time zone 'Asia/Jerusalem';
    tm := lt::time;
    if p.quiet and p.quiet_from <> p.quiet_to then
      if p.quiet_from < p.quiet_to then
        if tm >= p.quiet_from and tm < p.quiet_to then e := (lt::date + p.quiet_to) at time zone 'Asia/Jerusalem'; end if;
      elsif tm >= p.quiet_from then
        e := ((lt::date + 1) + p.quiet_to) at time zone 'Asia/Jerusalem';
      elsif tm < p.quiet_to then
        e := (lt::date + p.quiet_to) at time zone 'Asia/Jerusalem';
      end if;
    end if;
    if p.shabbat then
      dw := extract(isodow from lt)::int;
      if (dw = 5 and tm >= time '16:00') or (dw = 6 and tm < time '20:30') then
        e := greatest(e, ((lt::date + case when dw = 5 then 1 else 0 end) + time '20:30') at time zone 'Asia/Jerusalem');
      end if;
    end if;
    exit when e is null or e <= t;
    t := e;
  end loop;
  return case when t = p_at then null else t end;
end;
$$;

-- The one way to add a notice (§4.2 of the design). Never raises: a notice is
-- never worth a failed quiz, comment or upload. Coalesces with the person's
-- unseen row of the same dedupe key, then queues the push when the kind
-- pushes, the person's category is on and the person has a device.
create or replace function study_private.notice_add(
  p_user uuid, p_group uuid, p_kind text, p_args jsonb, p_route jsonb, p_obj text, p_dedupe text,
  p_lecture uuid default null, p_ends timestamptz default null)
returns bigint language plpgsql volatile security definer set search_path = public set lock_timeout = '200ms' as $$
declare
  k    study_private.notice_kinds;
  v_id bigint;
begin
  if p_user is null or not study_private.feature_on('notify_hooks') then return null; end if;
  select * into k from study_private.notice_kinds where kind = p_kind;
  if not found then
    k := row(p_kind, 'inapp', interval '1 day', interval '0', false)::study_private.notice_kinds;
  end if;
  insert into public.study_notices as n (user_id, group_id, lecture_id, kind, cat, args, route, obj, dedupe, ends_at)
  values (p_user, p_group, p_lecture, p_kind, k.cat, coalesce(p_args, '{}'), coalesce(p_route, '{}'), p_obj,
          coalesce(p_dedupe, p_kind), p_ends)
  on conflict (user_id, dedupe) where seen_at is null
  do update set count = least(n.count + 1, 999), args = excluded.args, route = excluded.route,
                ends_at = excluded.ends_at, updated_at = now()
  returning n.id into v_id;
  if k.push and study_private.notify_cat_on(p_user, k.cat) and study_private.push_reachable(p_user, k.cat) then
    insert into study_private.notify_outbox as o (notice_id, user_id, group_id, kind, cat, state, not_before, expires_at)
    values (v_id, p_user, p_group, p_kind, k.cat, 'due', now() + k.delay, now() + k.ttl)
    on conflict (notice_id) do update set
      again       = o.state = 'sending' or o.again,
      state       = case when o.state = 'sending' then 'sending' else 'due' end,
      not_before  = case when o.state = 'sending' then o.not_before else excluded.not_before end,
      attempts    = case when o.state = 'sending' then o.attempts else 0 end,
      lease_until = case when o.state = 'sending' then o.lease_until end,
      expires_at  = excluded.expires_at;
  end if;
  return v_id;
exception when others then
  raise warning 'notice_add % %', p_kind, sqlstate;
  return null;
end;
$$;

-- notice_add for every member of a group but one (the person who did it).
create or replace function study_private.notice_group(
  p_group uuid, p_except uuid, p_kind text, p_args jsonb, p_route jsonb, p_obj text, p_dedupe text,
  p_lecture uuid default null, p_ends timestamptz default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare u uuid; n int := 0;
begin
  for u in select m.user_id from public.study_members m
            where m.group_id = p_group and m.user_id is distinct from p_except order by m.user_id loop
    if study_private.notice_add(u, p_group, p_kind, p_args, p_route, p_obj, p_dedupe, p_lecture, p_ends) is not null then
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;

-- Kick /api/study/work {notify:true} when a push is due (or within 20 s: the
-- worker waits for a held quiz instead of the next minute). Once a 3 s with
-- p_now, once a 50 s otherwise. After 15 kicks nobody claimed (no VAPID keys,
-- a broken deploy) it stops, except one probe an hour; a claim resets it.
create or replace function study_private.notify_dispatch(p_now boolean default false)
returns int language plpgsql volatile security definer set search_path = public as $$
declare k study_private.notify_kick;
begin
  if not study_private.server_on() then return 0; end if;
  if not exists (select 1 from study_private.notify_outbox o
                  where o.state = 'due' and o.not_before <= now() + interval '20 seconds'
                    and (study_private.feature_on('notify')
                         or exists (select 1 from study_private.notify_pilot p where p.user_id = o.user_id))
                    and study_private.push_reachable(o.user_id, o.cat)) then
    return 0;
  end if;
  select * into k from study_private.notify_kick where id = 1 for update skip locked;
  if not found then return 0; end if;   -- another caller is kicking now
  if k.at > now() - (case when p_now then interval '3 seconds' else interval '50 seconds' end) then return 0; end if;
  if k.kicks_since_claim >= 15 then
    update study_private.notify_kick set stuck_at = coalesce(stuck_at, now()) where id = 1;
    if k.at > now() - interval '1 hour' then return 0; end if;
  end if;
  perform net.http_post(
    url := rtrim(study_private.secret('study_site_url'), '/') || '/api/study/work',
    body := jsonb_build_object('notify', true),
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || study_private.secret('study_worker_key')),
    timeout_milliseconds := 10000);
  update study_private.notify_kick set at = now(), kicks_since_claim = kicks_since_claim + 1 where id = 1;
  return 1;
end;
$$;

-- (R 2) Once a day between 17:00 and 21:00 (Israel time, p_local): an open
-- question a member could help with ("הקבוצה צריכה אותך", section G), only
-- for those who turned it on there, at most one a day. study_needs_me()
-- decides it for the member it is asked as, so each opted-in member is asked
-- in turn, as that member, inside this transaction only; the caller's own
-- claims are put back after.
create or replace function study_private.notify_needs(p_local timestamp)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  v_today date := p_local::date;
  v_day   bigint := to_char(p_local::date, 'YYYYMMDD')::bigint;
  r       record;
  v_q     jsonb;
  v_e     jsonb;
  v_sub   text := current_setting('request.jwt.claim.sub', true);
  v_clm   text := current_setting('request.jwt.claims', true);
  v_n     int := 0;
begin
  if p_local::time not between time '17:00' and time '21:00' or to_regprocedure('public.study_needs_me(uuid)') is null
     or to_regclass('public.study_member_prefs') is null
     or coalesce((select c.last_id from study_private.notify_cursor c where c.name = 'needs'), 0) >= v_day then
    return 0;
  end if;
  insert into study_private.notify_cursor (name, last_id) values ('needs', v_day)
  on conflict (name) do update set last_id = excluded.last_id;
  for r in select distinct on (p.user_id) p.user_id, p.group_id
             from public.study_member_prefs p
             join public.study_members m on m.user_id = p.user_id and m.group_id = p.group_id
            where p.needs_me
              and not exists (select 1 from public.study_notices n where n.user_id = p.user_id and n.dedupe = 'needs:' || v_today)
            order by p.user_id, p.updated_at desc loop
    perform set_config('request.jwt.claim.sub', r.user_id::text, true);
    perform set_config('request.jwt.claims', jsonb_build_object('sub', r.user_id, 'role', 'authenticated')::text, true);
    begin
      v_q := public.study_needs_me(r.group_id);
    exception when others then
      v_q := '[]'::jsonb;
    end;
    v_e := null;
    select e into v_e from jsonb_array_elements(coalesce(v_q, '[]'::jsonb)) e where e ->> 'kind' = 'question' limit 1;
    if v_e is not null and study_private.notice_add(r.user_id, r.group_id, 'needs_me',
         jsonb_strip_nulls(jsonb_build_object('lecture', left(v_e ->> 'lecture_title', 120))),
         jsonb_build_object('v', 'lecture', 'l', v_e ->> 'lecture_id',
                            'at', jsonb_build_object('part', (v_e ->> 'part')::int, 'anchor', (v_e ->> 'anchor')::int)),
         null, 'needs:' || v_today, study_private.uuid_or_null(v_e ->> 'lecture_id'), null) is not null then
      v_n := v_n + 1;
    end if;
  end loop;
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  perform set_config('request.jwt.claims', coalesce(v_clm, ''), true);
  return v_n;
end;
$$;

-- (R 2) The daily reminder, at each person's hour (within half an hour of
-- it; p_local is Israel time), once a day, only for those who turned it on,
-- and only when there is something to say: cards to review today, today's
-- meeting still to come, an exam within 14 days (of the person's latest group).
create or replace function study_private.notify_digest(p_local timestamp)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  v_today date := p_local::date;
  v_end   timestamptz := (p_local::date + 1)::timestamp at time zone 'Asia/Jerusalem';
  r       record;
  v_grp   uuid;
  v_cards int;
  v_meet  timestamptz;
  v_crs   text;
  v_days  int;
  v_n     int := 0;
begin
  for r in select p.user_id from public.study_notify_prefs p
            where p.digest and p_local::time >= p.digest_at and p_local::time < p.digest_at + interval '30 minutes'
              and not exists (select 1 from public.study_notices n where n.user_id = p.user_id and n.dedupe = 'digest:' || v_today) loop
    v_grp := null;
    select m.group_id into v_grp from public.study_members m where m.user_id = r.user_id order by m.joined_at desc limit 1;
    continue when v_grp is null;
    v_cards := 0; v_meet := null; v_crs := null; v_days := null;
    if to_regclass('public.study_card_states') is not null then
      select count(*) into v_cards from public.study_card_states s join public.study_cards c on c.id = s.card_id
       where s.user_id = r.user_id and c.group_id = v_grp and not s.suspended and s.due is not null and s.due < v_end;
    end if;
    if to_regclass('public.study_meetings') is not null then
      select min(m.starts_at) into v_meet from public.study_meetings m
       where m.group_id = v_grp and m.cancelled_at is null and m.starts_at >= now() and m.starts_at < v_end;
    end if;
    if to_regclass('public.study_courses') is not null then
      select left(c.name, 120), c.exam_date - v_today into v_crs, v_days from public.study_courses c
       where c.group_id = v_grp and c.deleted_at is null and c.exam_date between v_today and v_today + 14
       order by c.exam_date, c.name limit 1;
    end if;
    continue when v_cards = 0 and v_meet is null and v_crs is null;
    if study_private.notice_add(r.user_id, v_grp, 'digest',
         jsonb_strip_nulls(jsonb_build_object('cards', nullif(v_cards, 0), 'meet', v_meet, 'course', v_crs, 'days', v_days)),
         jsonb_build_object('v', 'today'), null, 'digest:' || v_today, null, v_end) is not null then
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;

-- Every minute (pg_cron), before notify_dispatch():
--   1. the sign-in scan: each new 'redeemed' row of study_private.code_log
--      becomes a code_used notice for that member, when the member has a
--      device to warn (not inside the redeem itself, which stays as it was);
--      the first run only notes where the log ends;
--   2. pushes whose worker died go back to 'due'; 3. pushes past their
--      time-to-live are dropped; 4. a quiz that ended ends its inbox row, and
--      so does a meeting cancelled or a reading stopped;
--   R 2: 5. a meeting starting in 15 minutes (each member once, not those
--      already in it); 6. a study day starting in 30 minutes (those who said
--      in or maybe); 7. once a day between 17:00 and 21:00, an open question
--      a member could help with ("הקבוצה צריכה אותך", only for those who turned it
--      on, at most one a day); 8. the daily reminder at each person's hour,
--      only for those who turned it on, and only when there is something to
--      say (cards to review today, today's meeting, an exam within 14 days).
create or replace function study_private.notify_plan()
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  v_last  bigint;
  v_max   bigint;
  r       record;
  u       uuid;
  v_n     int := 0;
  v_local timestamp := now() at time zone 'Asia/Jerusalem';
begin
  if to_regclass('study_private.code_log') is not null then
    select c.last_id into v_last from study_private.notify_cursor c where c.name = 'code' for update;
    if not found then
      insert into study_private.notify_cursor (name, last_id)
      values ('code', coalesce((select max(l.id) from study_private.code_log l), 0))
      on conflict (name) do nothing;
    else
      select max(x.id) into v_max from (select l.id from study_private.code_log l where l.id > v_last order by l.id limit 500) x;
      if v_max is not null then
        for r in select l.id, l.user_id, l.at from study_private.code_log l
                  where l.id > v_last and l.id <= v_max and l.event = 'redeemed' order by l.id loop
          if (exists (select 1 from public.study_push_subs s where s.user_id = r.user_id)
              or exists (select 1 from study_private.push_removed x where x.user_id = r.user_id and x.removed_at >= r.at))
             and study_private.notice_add(r.user_id, null, 'code_used', jsonb_build_object('at', r.at),
                                          jsonb_build_object('v', 'me'), null, 'code:' || r.id) is not null then
            v_n := v_n + 1;
          end if;
        end loop;
        update study_private.notify_cursor set last_id = v_max where name = 'code';
      end if;
    end if;
  end if;
  delete from study_private.push_removed where removed_at < now() - interval '15 minutes';
  update study_private.notify_outbox set state = 'due', lease_until = null
   where state = 'sending' and lease_until < now();
  update study_private.notify_outbox set state = 'expired', lease_until = null
   where state = 'due' and expires_at < now();
  update public.study_notices n set ends_at = coalesce(q.ended_at, q.updated_at)
    from public.study_quizzes q
   where n.kind in ('quiz_open', 'boss_open') and n.cat = 'live' and n.ends_at is null and n.seen_at is null
     and q.id = study_private.uuid_or_null(n.route ->> 'q') and q.state in ('ended', 'cancelled');
  if to_regclass('public.study_meetings') is not null then
    -- (A cancelled meeting's rows say so: args.off, "הפגישה בוטלה".)
    update public.study_notices n set ends_at = now(),
           args = case when m.cancelled_at is not null and n.kind = 'meeting_soon' then n.args || '{"off": true}'::jsonb else n.args end
      from public.study_meetings m
     where n.kind in ('meeting_soon', 'reading') and n.cat = 'live' and n.seen_at is null and n.ends_at > now()
       and m.id = study_private.uuid_or_null(n.route ->> 'm')
       and (m.cancelled_at is not null or (n.kind = 'reading' and not m.reading));

    -- 5. The meeting in 15 minutes (12 to 15 ahead, so a missed minute is caught).
    for r in select m.id, m.group_id, m.starts_at, m.lecture_id, left(l.title, 120) as lec
               from public.study_meetings m join public.study_lectures l on l.id = m.lecture_id and l.deleted_at is null
              where m.cancelled_at is null and not m.reading
                and m.starts_at > now() + interval '12 minutes' and m.starts_at <= now() + interval '15 minutes' loop
      for u in select mm.user_id from public.study_members mm
                where mm.group_id = r.group_id
                  and not exists (select 1 from public.study_meeting_presence pr where pr.meeting_id = r.id and pr.user_id = mm.user_id)
                  and not exists (select 1 from public.study_notices n where n.user_id = mm.user_id and n.dedupe = 'meet15:' || r.id) loop
        if study_private.notice_add(u, r.group_id, 'meeting_soon', jsonb_build_object('lecture', r.lec, 'at', r.starts_at),
                                    jsonb_build_object('v', 'meeting', 'm', r.id), 'meet:' || r.id, 'meet15:' || r.id,
                                    r.lecture_id, r.starts_at + interval '1 hour') is not null then
          v_n := v_n + 1;
        end if;
      end loop;
    end loop;
  end if;

  -- 6. The study day in 30 minutes (27 to 30 ahead), to those who said in or maybe.
  if to_regclass('public.study_marathons') is not null then
    for r in select k.id, k.group_id, k.starts_at, k.minutes, left(k.title, 120) as title
               from public.study_marathons k
              where k.state = 'planned' and k.starts_at > now() + interval '27 minutes' and k.starts_at <= now() + interval '30 minutes' loop
      for u in select p.user_id from public.study_marathon_people p
                where p.marathon_id = r.id and p.answer in ('in', 'maybe')
                  and exists (select 1 from public.study_members mm where mm.group_id = r.group_id and mm.user_id = p.user_id)
                  and not exists (select 1 from public.study_notices n where n.user_id = p.user_id and n.dedupe = 'mara30:' || r.id) loop
        if study_private.notice_add(u, r.group_id, 'session_soon', jsonb_build_object('title', r.title, 'at', r.starts_at),
                                    jsonb_build_object('v', 'marathon', 'm', r.id), null, 'mara30:' || r.id,
                                    null, r.starts_at + make_interval(mins => r.minutes)) is not null then
          v_n := v_n + 1;
        end if;
      end loop;
    end loop;
  end if;

  -- 7, 8. (R 2) Kept apart so a check can give them the hour.
  v_n := v_n + study_private.notify_needs(v_local) + study_private.notify_digest(v_local);

  if v_n > 0 then perform study_private.notify_dispatch(true); end if;
  return v_n;
end;
$$;

-- A member RPC's caller: signed in and a member of this group (or, with no
-- group, of some group). Otherwise 'forbidden'.
create or replace function study_private.notify_member(p_group uuid)
returns uuid language plpgsql stable security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null or not exists (select 1 from public.study_members m
                                where m.user_id = me and (p_group is null or m.group_id = p_group)) then
    raise exception 'forbidden';
  end if;
  return me;
end;
$$;

revoke all on function study_private.push_host_ok(text), study_private.notify_prefs_of(uuid),
  study_private.notify_cat_on(uuid, text), study_private.notify_quiet(uuid, timestamptz),
  study_private.notice_add(uuid, uuid, text, jsonb, jsonb, text, text, uuid, timestamptz),
  study_private.notice_group(uuid, uuid, text, jsonb, jsonb, text, text, uuid, timestamptz),
  study_private.notify_dispatch(boolean), study_private.notify_plan(), study_private.notify_member(uuid),
  study_private.notify_needs(timestamp), study_private.notify_digest(timestamp),
  study_private.push_set_aside(uuid, bigint[]), study_private.push_reachable(uuid, text),
  study_private.notify_live_by(text, text) from public;

-- ── The worker's RPCs (/api/study/work {notify:true}, the server key) ──

-- Claims up to p_limit due pushes, oldest first, and decides each one now:
--   off     the switch is off and the person is not in the pilot;
--   none    the category is off, the notice was seen (never a security
--           notice: opening the inbox does not silence it), its lecture was
--           deleted, a "budget" stop of this lecture was already pushed this
--           month, or "the reading started" after "the meeting starts in 15
--           minutes" was pushed;
--   held    the quiz ended, or its host unchecked "להודיע לקבוצה"; the
--           meeting was cancelled, or its reading stopped;
--   capped  another quiz of the group was pushed in the last 10 minutes, or
--           of the same host in the last 30; the same for meetings and study
--           days (another one of the group in 10 minutes, of the same creator
--           in 30); or the person's day is full
--           (Israel day: 6 in "בשבילך", 12 in all, 3 security notices);
--   quiet   a live notice inside the person's quiet hours (the inbox has it);
--           a "בשבילך" one waits for the window's end; a security one goes
--           now, silently;
--   nosub   no device left (a security notice also goes to the devices set
--           aside in push_removed after the sign-in).
-- The rest become 'sending' for 180 s with their devices. At most 60 pushes
-- a minute in all. more: another push is due within 20 s (wait_ms from now).
create or replace function public.study_notify_claim(p_key text, p_limit int default 20)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  o       record;
  n       public.study_notices;
  q       public.study_quizzes;
  v_lim   int := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_on    boolean;
  v_day   timestamptz := ((now() at time zone 'Asia/Jerusalem')::date)::timestamp at time zone 'Asia/Jerusalem';
  v_month timestamptz := date_trunc('month', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem';
  v_min   int;
  v_n     int := 0;
  v_rows  jsonb := '[]';
  v_subs  jsonb;
  v_quiet timestamptz;
  v_silent boolean;
  v_at    timestamptz;
  v_full  boolean := false;
  v_next  timestamptz;
  v_m     text;
  v_by    uuid;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  update study_private.notify_kick set kicks_since_claim = 0, stuck_at = null where id = 1;
  perform pg_advisory_xact_lock(hashtext('study_notify'));
  v_on := study_private.feature_on('notify');
  select count(*) into v_min from study_private.notify_outbox x
   where (x.state = 'sent' and x.pushed_at > now() - interval '1 minute') or x.state = 'sending';
  for o in select x.* from study_private.notify_outbox x
            where x.state = 'due' and x.not_before <= now()
            order by x.not_before, x.notice_id
            for update skip locked loop
    exit when v_n >= v_lim;
    select * into n from public.study_notices where id = o.notice_id;
    if not found then continue; end if;
    if not v_on and not exists (select 1 from study_private.notify_pilot p where p.user_id = o.user_id) then
      update study_private.notify_outbox set state = 'off' where notice_id = o.notice_id; continue;
    end if;
    if not study_private.notify_cat_on(o.user_id, o.cat) or (n.seen_at is not null and o.cat <> 'security')
       or (n.lecture_id is not null and exists (select 1 from public.study_lectures l where l.id = n.lecture_id and l.deleted_at is not null)) then
      update study_private.notify_outbox set state = 'none' where notice_id = o.notice_id; continue;
    end if;
    if o.kind in ('quiz_open', 'boss_open') then
      select * into q from public.study_quizzes x where x.id = study_private.uuid_or_null(n.route ->> 'q');
      if not found or q.state in ('ended', 'cancelled')
         or exists (select 1 from study_private.quiz_quiet z where z.quiz_id = q.id) then
        update study_private.notify_outbox set state = 'held' where notice_id = o.notice_id; continue;
      end if;
      -- The members of one quiz are never capped against each other (same dedupe).
      if exists (select 1 from study_private.notify_outbox o2 join public.study_notices n2 on n2.id = o2.notice_id
                  where o2.group_id = o.group_id and o2.kind in ('quiz_open', 'boss_open') and n2.dedupe <> n.dedupe
                    and ((o2.state = 'sent' and o2.pushed_at > now() - interval '10 minutes') or o2.state = 'sending'))
         or exists (select 1 from study_private.notify_outbox o2 join public.study_notices n2 on n2.id = o2.notice_id
                      join public.study_quizzes q2 on q2.id = study_private.uuid_or_null(n2.route ->> 'q')
                  where o2.kind in ('quiz_open', 'boss_open') and n2.dedupe <> n.dedupe and q2.created_by = q.created_by
                    and ((o2.state = 'sent' and o2.pushed_at > now() - interval '30 minutes') or o2.state = 'sending')) then
        update study_private.notify_outbox set state = 'capped' where notice_id = o.notice_id; continue;
      end if;
    end if;
    -- R 2: a meeting cancelled meanwhile sends nothing; one push a meeting
    -- a member (no "the reading started" after "the meeting starts in 15
    -- minutes" was pushed).
    if o.kind in ('meeting_soon', 'reading') and to_regclass('public.study_meetings') is not null then
      if exists (select 1 from public.study_meetings m where m.id = study_private.uuid_or_null(n.route ->> 'm')
                    and (m.cancelled_at is not null or (o.kind = 'reading' and not m.reading))) then
        update study_private.notify_outbox set state = 'held' where notice_id = o.notice_id; continue;
      end if;
      if o.kind = 'reading' and exists (
           select 1 from study_private.notify_outbox o2 join public.study_notices n2 on n2.id = o2.notice_id
            where o2.user_id = o.user_id and o2.kind = 'meeting_soon' and n2.obj = n.obj and o2.state in ('sent', 'sending')) then
        update study_private.notify_outbox set state = 'none' where notice_id = o.notice_id; continue;
      end if;
    end if;
    -- Meetings and study days, like quizzes: one of the group in 10 minutes,
    -- one of the same creator in 30 (one member cannot spend the others' day
    -- of live pushes). The members of one meeting are never capped against each other.
    if o.kind in ('meeting_soon', 'reading', 'session_soon') then
      v_m := coalesce(n.route ->> 'm', '');
      v_by := study_private.notify_live_by(o.kind, v_m);
      if exists (select 1 from study_private.notify_outbox o2 join public.study_notices n2 on n2.id = o2.notice_id
                  where o2.group_id = o.group_id and o2.kind in ('meeting_soon', 'reading', 'session_soon')
                    and coalesce(n2.route ->> 'm', '') <> v_m
                    and ((o2.state = 'sent' and o2.pushed_at > now() - interval '10 minutes') or o2.state = 'sending'))
         or (v_by is not null and exists (
               select 1 from study_private.notify_outbox o2 join public.study_notices n2 on n2.id = o2.notice_id
                where o2.kind in ('meeting_soon', 'reading', 'session_soon') and coalesce(n2.route ->> 'm', '') <> v_m
                  and ((o2.state = 'sent' and o2.pushed_at > now() - interval '30 minutes') or o2.state = 'sending')
                  and study_private.notify_live_by(o2.kind, n2.route ->> 'm') = v_by)) then
        update study_private.notify_outbox set state = 'capped' where notice_id = o.notice_id; continue;
      end if;
    end if;
    v_silent := false;
    v_quiet := study_private.notify_quiet(o.user_id, now());
    if v_quiet is not null then
      if o.cat = 'live' then
        update study_private.notify_outbox set state = 'quiet' where notice_id = o.notice_id; continue;
      elsif o.cat = 'security' then
        v_silent := true;
      else
        update study_private.notify_outbox set not_before = v_quiet where notice_id = o.notice_id; continue;
      end if;
    end if;
    if o.kind <> 'test' and (
         (o.cat in ('mine', 'digest') and (select count(*) from study_private.notify_outbox x
             where x.user_id = o.user_id and x.cat in ('mine', 'digest')
               and ((x.state = 'sent' and x.pushed_at >= v_day) or x.state = 'sending')) >= 6)
      or (o.cat <> 'security' and (select count(*) from study_private.notify_outbox x
             where x.user_id = o.user_id and x.cat <> 'security'
               and ((x.state = 'sent' and x.pushed_at >= v_day) or x.state = 'sending')) >= 12)
      or (o.cat = 'security' and (select count(*) from study_private.notify_outbox x
             where x.user_id = o.user_id and x.cat = 'security' and x.kind <> 'test'
               and ((x.state = 'sent' and x.pushed_at >= v_day) or x.state = 'sending')) >= 3)) then
      update study_private.notify_outbox set state = 'capped' where notice_id = o.notice_id; continue;
    end if;
    if o.kind = 'summary_failed' and n.args ->> 'why' in ('budget', 'reserve', 'member_share')
       and exists (select 1 from study_private.notify_outbox o2 join public.study_notices n2 on n2.id = o2.notice_id
                    where o2.user_id = o.user_id and o2.kind = 'summary_failed' and n2.lecture_id = n.lecture_id
                      and n2.args ->> 'why' in ('budget', 'reserve', 'member_share') and o2.pushed_at >= v_month) then
      update study_private.notify_outbox set state = 'none' where notice_id = o.notice_id; continue;
    end if;
    -- The security notice skips the devices that synced after the sign-in
    -- (most likely the device that signed in).
    v_at := null;
    if o.kind = 'code_used' then
      begin v_at := (n.args ->> 'at')::timestamptz; exception when others then v_at := null; end;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth, 'key_id', s.key_id) order by s.id), '[]')
      into v_subs from public.study_push_subs s where s.user_id = o.user_id and (v_at is null or s.seen_at < v_at);
    -- …and the devices removed after the sign-in (set aside 15 minutes; their ids negative: done() leaves them be).
    if o.kind = 'code_used' and v_at is not null then
      v_subs := v_subs || coalesce((select jsonb_agg(jsonb_build_object('id', -r.id, 'endpoint', r.endpoint, 'p256dh', r.p256dh, 'auth', r.auth, 'key_id', r.key_id) order by r.id)
                                      from study_private.push_removed r
                                     where r.user_id = o.user_id and r.seen_at < v_at and r.removed_at >= v_at
                                       and r.removed_at > now() - interval '15 minutes'
                                       and not exists (select 1 from public.study_push_subs s where s.endpoint = r.endpoint)), '[]'::jsonb);
    end if;
    if jsonb_array_length(v_subs) = 0 then
      update study_private.notify_outbox set state = 'nosub' where notice_id = o.notice_id; continue;
    end if;
    if v_min >= 60 then v_full := true; exit; end if;   -- stays due for the next minute
    update study_private.notify_outbox
       set state = 'sending', lease_until = now() + interval '180 seconds', attempts = attempts + 1, again = false
     where notice_id = o.notice_id;
    v_min := v_min + 1;
    v_n := v_n + 1;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'notice', jsonb_build_object('id', n.id, 'kind', n.kind, 'cat', n.cat, 'args', n.args, 'route', n.route,
                                   'count', n.count, 'dedupe', n.dedupe, 'expires_at', o.expires_at, 'silent', v_silent),
      'subs', v_subs));
  end loop;
  if not v_full then
    select min(x.not_before) into v_next from study_private.notify_outbox x
     where x.state = 'due' and x.not_before <= now() + interval '20 seconds'
       and (v_on or exists (select 1 from study_private.notify_pilot p where p.user_id = x.user_id))
       and study_private.push_reachable(x.user_id, x.cat);
  end if;
  return jsonb_build_object('rows', v_rows, 'more', v_next is not null,
    'wait_ms', case when v_next is null then null else greatest(0, ceil(extract(epoch from v_next - now()) * 1000))::int end);
end;
$$;

-- The worker's report as rows: [{notice, sub, status, retry_after?}].
create or replace function study_private.notify_results(p jsonb)
returns table (nid bigint, sid bigint, status int, retry int) language sql immutable set search_path = public as $$
  select (e ->> 'notice')::bigint, (e ->> 'sub')::bigint, coalesce((e ->> 'status')::int, 0),
         least(greatest(coalesce((e ->> 'retry_after')::int, 0), 0), 86400)
    from jsonb_array_elements(p) e
$$;
revoke all on function study_private.notify_results(jsonb), study_private.uuid_or_null(text) from public;

-- The worker reports after each batch: [{notice, sub, status, retry_after?}].
-- A device: 2xx fine; 404/410 gone (deleted); 400/401/403 three times and it
-- goes. A push: any 2xx is sent (and sent again if it coalesced meanwhile);
-- no device left is nosub; 413 failed; anything else (429, 5xx, a redirect,
-- 0 for a timeout) tries again later, five tries within its time to live.
create or replace function public.study_notify_done(p_key text, p_results jsonb)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  r record;
  o study_private.notify_outbox;
  v_n int := 0;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if jsonb_typeof(p_results) is distinct from 'array' or jsonb_array_length(p_results) > 500 then
    raise exception 'bad results';
  end if;
  insert into study_private.push_log (notice_id, sub_id, status)
  select nid, sid, status from study_private.notify_results(p_results);
  update public.study_push_subs s set ok_at = now(), fails = 0
   where s.id in (select sid from study_private.notify_results(p_results) where status between 200 and 299);
  delete from public.study_push_subs s
   where s.id in (select sid from study_private.notify_results(p_results) where status in (404, 410));
  update public.study_push_subs s set fails = s.fails + 1
   where s.id in (select sid from study_private.notify_results(p_results) where status in (400, 401, 403));
  delete from public.study_push_subs s
   where s.fails >= 3 and s.id in (select sid from study_private.notify_results(p_results) where status in (400, 401, 403));
  for r in select nid, bool_or(status between 200 and 299) as ok, bool_or(status = 413) as big, max(retry) as retry
             from study_private.notify_results(p_results) where nid is not null group by nid loop
    select * into o from study_private.notify_outbox where notice_id = r.nid and state = 'sending' for update;
    if not found then continue; end if;
    v_n := v_n + 1;
    if r.ok then
      update study_private.notify_outbox
         set state = case when o.again then 'due' else 'sent' end, pushed_at = now(), lease_until = null,
             again = false, not_before = now(), attempts = case when o.again then 0 else o.attempts end
       where notice_id = r.nid;
    elsif not study_private.push_reachable(o.user_id, o.cat) then
      update study_private.notify_outbox set state = 'nosub', lease_until = null where notice_id = r.nid;
    elsif r.big or o.attempts >= 5 or o.expires_at <= now() then
      update study_private.notify_outbox set state = 'failed', lease_until = null where notice_id = r.nid;
    else
      update study_private.notify_outbox
         set state = 'due', lease_until = null,
             not_before = now() + greatest(make_interval(secs => r.retry), interval '1 minute' * power(2, o.attempts))
       where notice_id = r.nid;
    end if;
  end loop;
  return v_n;
end;
$$;

-- For /api/study/health: is sending wired, on, piloted or stuck? No ids, no counts.
create or replace function public.study_notify_ok()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'wired', study_private.server_on(),
    'on', study_private.feature_on('notify'),
    'pilot', exists (select 1 from study_private.notify_pilot),
    'stuck', coalesce((select k.stuck_at is not null from study_private.notify_kick k where k.id = 1), false))
$$;

-- ── The member's RPCs (signed in, a member of a group) ──

-- May this member turn pushes on at all (the switch, or the pilot)?
create or replace function public.study_notify_state()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me uuid := study_private.notify_member(null);
begin
  return jsonb_build_object('send', study_private.feature_on('notify')
                                    or exists (select 1 from study_private.notify_pilot p where p.user_id = me));
end;
$$;

-- This device's push subscription. An endpoint another member saved moves to
-- the caller only with the same keys (the same browser subscription, now
-- signed in as the caller); with other keys it is refused ('bad endpoint'),
-- so nobody can take over a device whose endpoint they learned.
-- At most 10 devices a person: the longest unseen goes.
create or replace function public.study_push_subscribe(p_endpoint text, p_p256dh text, p_auth text, p_key_id text,
                                                       p_device text default 'other', p_browser text default '')
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare
  me    uuid := study_private.notify_member(null);
  v_id  bigint;
  v_old public.study_push_subs;
begin
  if not study_private.push_host_ok(p_endpoint) then raise exception 'bad endpoint'; end if;
  if coalesce(p_p256dh, '') !~ '^[A-Za-z0-9_-]{86,88}$' or coalesce(p_auth, '') !~ '^[A-Za-z0-9_-]{21,24}$'
     or coalesce(char_length(p_key_id), 0) not between 8 and 16 then
    raise exception 'bad keys';
  end if;
  select * into v_old from public.study_push_subs s where s.endpoint = p_endpoint;
  if found and v_old.user_id <> me and (v_old.p256dh <> p_p256dh or v_old.auth <> p_auth) then
    raise exception 'bad endpoint';
  end if;
  insert into public.study_push_subs as s (user_id, endpoint, p256dh, auth, key_id, device, browser)
  values (me, p_endpoint, p_p256dh, p_auth, p_key_id,
          case when p_device in ('iphone', 'ipad', 'android', 'mac', 'windows', 'linux') then p_device else 'other' end,
          left(coalesce(p_browser, ''), 20))
  on conflict (endpoint) do update set
    user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth, key_id = excluded.key_id,
    device = excluded.device, browser = excluded.browser, seen_at = now(), fails = 0,
    created_at = case when s.user_id = excluded.user_id then s.created_at else now() end
  returning s.id into v_id;
  perform study_private.push_set_aside(me, array(
    select s.id from public.study_push_subs s
     where s.user_id = me and s.id not in (select x.id from public.study_push_subs x where x.user_id = me
                                            order by x.seen_at desc, x.id desc limit 10)));
  delete from public.study_push_subs s
   where s.user_id = me and s.id not in (select x.id from public.study_push_subs x where x.user_id = me
                                          order by x.seen_at desc, x.id desc limit 10);
  return v_id;
end;
$$;

-- This device stops (sign-out, "לא במכשיר הזה"). The three removals below
-- act only on the caller's own rows, so they need a signed-in caller, not a
-- membership: a member removed from every group can still stop their devices.
create or replace function public.study_push_unsubscribe(p_endpoint text)
returns int language plpgsql volatile security definer set search_path = public as $$
declare me uuid := auth.uid(); v_n int;
begin
  if me is null then raise exception 'forbidden'; end if;
  perform study_private.push_set_aside(me, array(select id from public.study_push_subs where user_id = me and endpoint = p_endpoint));
  delete from public.study_push_subs where user_id = me and endpoint = p_endpoint;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

-- The caller's devices, without keys or endpoints; "this" marks the one asking.
create or replace function public.study_push_devices(p_endpoint text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me uuid := study_private.notify_member(null);
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'device', s.device, 'browser', s.browser,
                                                       'created_at', s.created_at, 'seen_at', s.seen_at, 'ok_at', s.ok_at,
                                                       'this', s.endpoint = p_endpoint) order by s.seen_at desc, s.id desc)
                     from public.study_push_subs s where s.user_id = me), '[]'::jsonb);
end;
$$;

create or replace function public.study_push_remove(p_id bigint)
returns int language plpgsql volatile security definer set search_path = public as $$
declare me uuid := auth.uid(); v_n int;
begin
  if me is null then raise exception 'forbidden'; end if;
  perform study_private.push_set_aside(me, array[p_id]);
  delete from public.study_push_subs where user_id = me and id = p_id;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

-- "ניתוק המכשירים האחרים": every device of the caller's but this one.
create or replace function public.study_push_keep_only(p_endpoint text)
returns int language plpgsql volatile security definer set search_path = public as $$
declare me uuid := auth.uid(); v_n int;
begin
  if me is null then raise exception 'forbidden'; end if;
  perform study_private.push_set_aside(me, array(select id from public.study_push_subs where user_id = me and endpoint is distinct from p_endpoint));
  delete from public.study_push_subs where user_id = me and endpoint is distinct from p_endpoint;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

-- Settings: only the known keys, each of its type; times on the half hour,
-- the reminder between 06:00 and 22:00. Answers the whole row (times "HH:MM").
create or replace function public.study_notify_prefs_set(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me uuid := study_private.notify_member(null);
  k  text;
  r  public.study_notify_prefs;
begin
  if jsonb_typeof(p) is distinct from 'object' then raise exception 'bad prefs'; end if;
  for k in select jsonb_object_keys(p) loop
    if k in ('live', 'mine', 'digest', 'quiet', 'shabbat') then
      if jsonb_typeof(p -> k) <> 'boolean' then raise exception 'bad prefs'; end if;
    elsif k in ('digest_at', 'quiet_from', 'quiet_to') then
      if jsonb_typeof(p -> k) <> 'string' or (p ->> k) !~ '^([01][0-9]|2[0-3]):(00|30)$' then raise exception 'bad prefs'; end if;
      if k = 'digest_at' and (p ->> k)::time not between time '06:00' and time '22:00' then raise exception 'bad prefs'; end if;
    else
      raise exception 'bad prefs';
    end if;
  end loop;
  insert into public.study_notify_prefs (user_id) values (me) on conflict (user_id) do nothing;
  update public.study_notify_prefs set
    live       = coalesce((p ->> 'live')::boolean, live),
    mine       = coalesce((p ->> 'mine')::boolean, mine),
    digest     = coalesce((p ->> 'digest')::boolean, digest),
    digest_at  = coalesce((p ->> 'digest_at')::time, digest_at),
    quiet      = coalesce((p ->> 'quiet')::boolean, quiet),
    quiet_from = coalesce((p ->> 'quiet_from')::time, quiet_from),
    quiet_to   = coalesce((p ->> 'quiet_to')::time, quiet_to),
    shabbat    = coalesce((p ->> 'shabbat')::boolean, shabbat),
    updated_at = now()
  where user_id = me
  returning * into r;
  return jsonb_build_object('live', r.live, 'mine', r.mine, 'digest', r.digest, 'digest_at', to_char(r.digest_at, 'HH24:MI'),
                            'quiet', r.quiet, 'quiet_from', to_char(r.quiet_from, 'HH24:MI'), 'quiet_to', to_char(r.quiet_to, 'HH24:MI'),
                            'shabbat', r.shabbat);
end;
$$;

-- The inbox: the caller's rows of this group and the group-less ones, last
-- changed first, 30 days back; p_before is the last row of the page before.
create or replace function public.study_notices_mine(p_group uuid, p_before bigint default null, p_limit int default 50)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  me uuid := study_private.notify_member(p_group);
  c  public.study_notices;
begin
  if p_before is not null then
    select * into c from public.study_notices where id = p_before and user_id = me;
    if not found then return '[]'::jsonb; end if;
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'group_id', x.group_id, 'lecture_id', x.lecture_id, 'kind', x.kind, 'cat', x.cat,
                                                       'args', x.args, 'route', x.route, 'obj', x.obj, 'count', x.count,
                                                       'created_at', x.created_at, 'updated_at', x.updated_at,
                                                       'seen_at', x.seen_at, 'ends_at', x.ends_at) order by x.updated_at desc, x.id desc)
                     from (select n.* from public.study_notices n
                            where n.user_id = me and (n.group_id = p_group or n.group_id is null) and n.kind <> 'test'
                              and n.updated_at > now() - interval '30 days'
                              and (p_before is null or (n.updated_at, n.id) < (c.updated_at, c.id))
                              and not exists (select 1 from public.study_lectures l where l.id = n.lecture_id and l.deleted_at is not null)
                            order by n.updated_at desc, n.id desc
                            limit least(greatest(coalesce(p_limit, 50), 1), 100)) x), '[]'::jsonb);
end;
$$;

-- The bell: how many unseen (at most 99; no test, no live row already over),
-- and which objects they are about (so a screen knows to mark its own seen).
create or replace function public.study_notices_unseen(p_group uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me uuid := study_private.notify_member(p_group);
begin
  return jsonb_build_object(
    'n', (select count(*) from (select 1 from public.study_notices n
                                 where n.user_id = me and n.seen_at is null and (n.group_id = p_group or n.group_id is null)
                                   and n.kind <> 'test' and not (n.cat = 'live' and coalesce(n.ends_at < now(), false))
                                   and not exists (select 1 from public.study_lectures l where l.id = n.lecture_id and l.deleted_at is not null) limit 99) x),
    'objs', coalesce((select jsonb_agg(o order by o) from (select distinct n.obj as o from public.study_notices n
                                 where n.user_id = me and n.seen_at is null and n.obj is not null
                                   and (n.group_id = p_group or n.group_id is null) and n.kind <> 'test'
                                   and not exists (select 1 from public.study_lectures l where l.id = n.lecture_id and l.deleted_at is not null) limit 50) y), '[]'::jsonb));
end;
$$;

-- Seen: these rows, whichever of the caller's groups they are in (a push
-- about another group tapped while the app shows this one); null: all of this
-- group's and the group-less ones. A push still waiting for them is dropped,
-- except a security notice's (opening the inbox never silences it).
create or replace function public.study_notices_seen(p_group uuid, p_ids bigint[] default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  me    uuid := study_private.notify_member(p_group);
  v_ids bigint[];
begin
  with s as (update public.study_notices n set seen_at = now()
              where n.user_id = me and n.seen_at is null
                and (case when p_ids is null then n.group_id = p_group or n.group_id is null else n.id = any (p_ids) end)
             returning n.id)
  select array_agg(id) into v_ids from s;
  update study_private.notify_outbox set state = 'none', lease_until = null
   where notice_id = any (coalesce(v_ids, '{}')) and state = 'due' and cat <> 'security';
  return coalesce(cardinality(v_ids), 0);
end;
$$;

-- Seen: the caller's unseen rows about one object (the screen just opened).
create or replace function public.study_notices_seen_obj(p_group uuid, p_obj text)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  me    uuid := study_private.notify_member(p_group);
  v_ids bigint[];
begin
  with s as (update public.study_notices n set seen_at = now()
              where n.user_id = me and n.seen_at is null and n.obj = p_obj
                and (n.group_id = p_group or n.group_id is null)
             returning n.id)
  select array_agg(id) into v_ids from s;
  update study_private.notify_outbox set state = 'none', lease_until = null
   where notice_id = any (coalesce(v_ids, '{}')) and state = 'due' and cat <> 'security';
  return coalesce(cardinality(v_ids), 0);
end;
$$;

-- "שליחת התראת ניסיון": a test push to the caller's devices in about 5 s.
-- Never in the inbox. 3 an hour a person, 30 an hour in all ('too many').
create or replace function public.study_notify_test()
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare
  me   uuid := study_private.notify_member(null);
  v_id bigint;
begin
  if (select count(*) from public.study_notices n where n.user_id = me and n.kind = 'test' and n.created_at > now() - interval '1 hour') >= 3
     or (select count(*) from public.study_notices n where n.kind = 'test' and n.created_at > now() - interval '1 hour') >= 30 then
    raise exception 'too many';
  end if;
  v_id := study_private.notice_add(me, null, 'test', '{}'::jsonb, jsonb_build_object('v', 'me'), null,
                                   'test:' || md5(random()::text || clock_timestamp()::text));
  perform study_private.notify_dispatch(true);
  return v_id;
end;
$$;

-- The host unchecked "להודיע לקבוצה" (within 2 minutes of opening the quiz):
-- the quiz's pushes, still held for 15 s, are not sent. The inbox keeps it.
create or replace function public.study_quiz_quiet(p_quiz uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  me uuid := study_private.notify_member(null);
  q  public.study_quizzes;
begin
  select * into q from public.study_quizzes where id = p_quiz;
  if not found or me is distinct from q.host_id and me is distinct from q.created_by then raise exception 'forbidden'; end if;
  if q.created_at < now() - interval '2 minutes' then raise exception 'too late'; end if;
  insert into study_private.quiz_quiet (quiz_id) values (p_quiz) on conflict (quiz_id) do nothing;
  update study_private.notify_outbox o set state = 'held', lease_until = null
    from public.study_notices n
   where n.id = o.notice_id and n.dedupe = 'quiz:' || p_quiz and o.state = 'due';
end;
$$;

-- ── The hooks (R 1). Each stops at its first line when notify_hooks is off,
-- and never fails the write that fired it. ──

-- A group quiz opened: every other member, held 15 s (study_quiz_quiet).
-- The lock screen shows the first lecture's title, never the quiz's title or a name.
-- R 2: a group challenge (mode 'boss', section H) is "אתגר קבוצתי נפתח
-- עכשיו" with its course (the lectures' one course, or the first lecture).
create or replace function study_private.r_quiz()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_who  uuid;
  v_lec  text;
  v_name text;
  v_crs  text;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  v_who := coalesce(new.created_by, new.host_id);
  select left(l.title, 120) into v_lec from public.study_lectures l where l.id = new.lecture_ids[1];
  select left(m.name, 60) into v_name from public.study_members m where m.group_id = new.group_id and m.user_id = v_who;
  if new.mode = 'boss' then
    select case when count(distinct btrim(l.course)) = 1 and min(btrim(l.course)) <> '' then left(min(btrim(l.course)), 120) end
      into v_crs from public.study_lectures l where l.id = any (new.lecture_ids);
    perform study_private.notice_group(new.group_id, v_who, 'boss_open',
      jsonb_strip_nulls(jsonb_build_object('course', coalesce(v_crs, v_lec), 'name', v_name)),
      jsonb_build_object('v', 'quiz', 'q', new.id), 'quiz:' || new.id, 'quiz:' || new.id, new.lecture_ids[1], null);
    perform study_private.notify_dispatch(true);
    return null;
  end if;
  perform study_private.notice_group(new.group_id, v_who, 'quiz_open',
    jsonb_strip_nulls(jsonb_build_object('mode', new.mode, 'lecture', v_lec, 'more', nullif(cardinality(new.lecture_ids) - 1, 0),
                                         'title', left(new.title, 120), 'name', v_name)),
    jsonb_build_object('v', 'quiz', 'q', new.id), 'quiz:' || new.id, 'quiz:' || new.id, new.lecture_ids[1], null);
  perform study_private.notify_dispatch(true);
  return null;
exception when others then
  raise warning 'study_r_quiz %', sqlstate;
  return null;
end;
$$;

-- A reply in a thread: its opener ("יש תשובה לשאלה שלך" when it opened with
-- a question) and everyone who replied before, except the one replying, while
-- still members. One row a thread, counting replies until seen.
create or replace function study_private.r_reply()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_root public.study_comments;
  v_grp  uuid;
  v_lec  text;
  u      uuid;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  with recursive up (id, parent_id, depth) as (
    select c.id, c.parent_id, 0 from public.study_comments c where c.id = new.parent_id
    union all
    select c.id, c.parent_id, up.depth + 1 from public.study_comments c join up on c.id = up.parent_id where up.depth < 50)
  select c.* into v_root from public.study_comments c where c.id = (select up.id from up where up.parent_id is null limit 1);
  if not found then return null; end if;
  select l.group_id, left(l.title, 120) into v_grp, v_lec from public.study_lectures l where l.id = new.lecture_id;
  for u in
    with recursive down (id) as (
      select v_root.id
      union
      select c.id from public.study_comments c join down on c.parent_id = down.id)
    select distinct c.author_id from public.study_comments c join down on down.id = c.id
     where c.id <> new.id and c.author_id <> new.author_id
       and exists (select 1 from public.study_members m where m.group_id = v_grp and m.user_id = c.author_id)
  loop
    perform study_private.notice_add(u, v_grp,
      case when u = v_root.author_id and v_root.kind = 'question' then 'answer' else 'reply' end,
      jsonb_strip_nulls(jsonb_build_object('lecture', v_lec, 'part', new.part_idx + 1)),
      jsonb_build_object('v', 'lecture', 'l', new.lecture_id, 'at', jsonb_build_object('part', new.part_idx, 'anchor', new.anchor)),
      null, 'reply:' || v_root.id, new.lecture_id, null);
  end loop;
  return null;
exception when others then
  raise warning 'study_r_reply %', sqlstate;
  return null;
end;
$$;

-- A summary ready, or stopped (why: the stop's code, such as 'budget'), to
-- the member who uploaded it. R 2: the first time it is ready, the rest of
-- the group gets "סיכום חדש בספרייה" in the inbox (never pushed).
create or replace function study_private.r_lecture()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  if new.status = 'ready' and new.deleted_at is null
     and not exists (select 1 from public.study_notices n where n.lecture_id = new.id and n.kind = 'lecture_new') then
    perform study_private.notice_group(new.group_id, new.created_by, 'lecture_new',
      jsonb_build_object('lecture', left(new.title, 120)), jsonb_build_object('v', 'lecture', 'l', new.id),
      'lec:' || new.id, 'new:' || new.id, new.id, null);
  end if;
  if not exists (select 1 from public.study_members m where m.group_id = new.group_id and m.user_id = new.created_by) then
    return null;
  end if;
  perform study_private.notice_add(new.created_by, new.group_id,
    case new.status when 'ready' then 'summary_ready' else 'summary_failed' end,
    jsonb_strip_nulls(jsonb_build_object('lecture', left(new.title, 120),
                                         'why', case when new.status = 'failed' then left(new.error, 40) end)),
    jsonb_build_object('v', 'lecture', 'l', new.id), 'lec:' || new.id, 'lec:' || new.id || ':' || new.status, new.id, null);
  return null;
exception when others then
  raise warning 'study_r_lecture %', sqlstate;
  return null;
end;
$$;

-- Leaving a group (or being removed) takes that group's notices with it,
-- whatever the switch.
create or replace function study_private.r_leave()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  delete from public.study_notices where user_id = old.user_id and group_id = old.group_id;
  return null;
exception when others then
  raise warning 'study_r_leave %', sqlstate;
  return null;
end;
$$;

revoke all on function study_private.r_quiz(), study_private.r_reply(), study_private.r_lecture(), study_private.r_leave() from public;

do $$
begin
  if to_regclass('public.study_quizzes') is not null then
    drop trigger if exists study_r_quiz on public.study_quizzes;
    create trigger study_r_quiz after insert on public.study_quizzes
      for each row when (new.state = 'lobby') execute function study_private.r_quiz();
  end if;
  drop trigger if exists study_r_reply on public.study_comments;
  create trigger study_r_reply after insert on public.study_comments
    for each row when (new.parent_id is not null) execute function study_private.r_reply();
  drop trigger if exists study_r_lecture on public.study_lectures;
  create trigger study_r_lecture after update of status on public.study_lectures
    for each row when (old.status is distinct from new.status and new.status in ('ready', 'failed'))
    execute function study_private.r_lecture();
  drop trigger if exists study_r_leave on public.study_members;
  create trigger study_r_leave after delete on public.study_members
    for each row execute function study_private.r_leave();
end $$;

-- ── The hooks of R 2. Each on another section's table, created only when
-- that table is there; each stops at its first line when notify_hooks is
-- off and never fails the write that fired it. ──

-- A member started reading aloud: the members not already in the meeting,
-- once a meeting (the claim skips the push for those who got "the meeting
-- starts in 15 minutes"). The inbox says who reads; the lock screen never does.
create or replace function study_private.r_reading()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_lec  text;
  v_name text;
  u      uuid;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  select left(l.title, 120) into v_lec from public.study_lectures l where l.id = new.lecture_id;
  select left(m.name, 60) into v_name from public.study_members m where m.group_id = new.group_id and m.user_id = new.reader_id;
  for u in select mm.user_id from public.study_members mm
            where mm.group_id = new.group_id and mm.user_id is distinct from new.reader_id
              and not exists (select 1 from public.study_meeting_presence pr where pr.meeting_id = new.id and pr.user_id = mm.user_id)
              and not exists (select 1 from public.study_notices n where n.user_id = mm.user_id and n.dedupe = 'read:' || new.id) loop
    perform study_private.notice_add(u, new.group_id, 'reading',
      jsonb_strip_nulls(jsonb_build_object('lecture', v_lec, 'name', v_name)),
      jsonb_build_object('v', 'meeting', 'm', new.id), 'meet:' || new.id, 'read:' || new.id, new.lecture_id, now() + interval '2 hours');
  end loop;
  perform study_private.notify_dispatch(true);
  return null;
exception when others then
  raise warning 'study_r_reading %', sqlstate;
  return null;
end;
$$;

-- A meeting set, or moved to another time: the rest of the group, inbox only.
create or replace function study_private.r_meeting()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_lec text;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  if new.cancelled_at is not null or new.starts_at <= now()
     or (tg_op = 'UPDATE' and old.starts_at is not distinct from new.starts_at) then
    return null;
  end if;
  select left(l.title, 120) into v_lec from public.study_lectures l where l.id = new.lecture_id;
  perform study_private.notice_group(new.group_id,
    coalesce(case when tg_op = 'UPDATE' then new.updated_by end, new.created_by, auth.uid()), 'meeting_set',
    jsonb_strip_nulls(jsonb_build_object('lecture', v_lec, 'at', new.starts_at)),
    jsonb_build_object('v', 'meeting', 'm', new.id), 'meet:' || new.id, 'meetset:' || new.id, new.lecture_id, null);
  return null;
exception when others then
  raise warning 'study_r_meeting %', sqlstate;
  return null;
end;
$$;

-- "בקשה לקרדיט על דרך לזכור": the member asked to share the credit.
create or replace function study_private.r_credit()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  a     public.study_aids;
  v_lec text;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  select * into a from public.study_aids x where x.id = new.aid_id;
  if not found or new.user_id is not distinct from auth.uid()
     or not exists (select 1 from public.study_members m where m.group_id = a.group_id and m.user_id = new.user_id) then
    return null;
  end if;
  select left(l.title, 120) into v_lec from public.study_lectures l where l.id = a.lecture_id;
  perform study_private.notice_add(new.user_id, a.group_id, 'credit_ask', jsonb_strip_nulls(jsonb_build_object('lecture', v_lec)),
    jsonb_build_object('v', 'wall', 'l', a.lecture_id), 'wall:' || a.lecture_id, 'credit:' || new.aid_id, a.lecture_id, null);
  return null;
exception when others then
  raise warning 'study_r_credit %', sqlstate;
  return null;
end;
$$;

-- A dispute opened about a correction: the member who proposed it (when not
-- the one disputing).
create or replace function study_private.r_dispute()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_who uuid;
  v_grp uuid;
  v_lec text;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  if new.proposal_id is null then return null; end if;
  select p.proposed_by into v_who from public.study_edit_proposals p where p.id = new.proposal_id;
  if v_who is null or v_who is not distinct from new.author_a then return null; end if;
  select l.group_id, left(l.title, 120) into v_grp, v_lec from public.study_lectures l where l.id = new.lecture_id;
  if not exists (select 1 from public.study_members m where m.group_id = v_grp and m.user_id = v_who) then return null; end if;
  perform study_private.notice_add(v_who, v_grp, 'dispute', jsonb_strip_nulls(jsonb_build_object('lecture', v_lec)),
    jsonb_build_object('v', 'dispute', 'd', new.id), 'disp:' || new.id, 'disp:' || new.id, new.lecture_id, null);
  return null;
exception when others then
  raise warning 'study_r_dispute %', sqlstate;
  return null;
end;
$$;

-- A dispute decided: both sides and the correction's proposer, except the
-- member who decided.
create or replace function study_private.r_dispute_done()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_grp uuid;
  v_lec text;
  v_by  uuid;
  u     uuid;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  select l.group_id, left(l.title, 120) into v_grp, v_lec from public.study_lectures l where l.id = new.lecture_id;
  if new.proposal_id is not null then
    select p.proposed_by into v_by from public.study_edit_proposals p where p.id = new.proposal_id;
  end if;
  for u in select distinct x.u from unnest(array[new.author_a, new.author_b, v_by]) as x(u)
            where x.u is not null and x.u is distinct from coalesce(new.decided_by, auth.uid())
              and exists (select 1 from public.study_members m where m.group_id = v_grp and m.user_id = x.u) loop
    perform study_private.notice_add(u, v_grp, 'dispute_done', jsonb_strip_nulls(jsonb_build_object('lecture', v_lec)),
      jsonb_build_object('v', 'dispute', 'd', new.id), 'disp:' || new.id, 'dispdone:' || new.id, new.lecture_id, null);
  end loop;
  return null;
exception when others then
  raise warning 'study_r_dispute_done %', sqlstate;
  return null;
end;
$$;

-- A past exam read (or not): the member who uploaded it, held 90 s like a
-- summary. kind: 'sheet' once uploaded sheets come (section O); why: the
-- stop's code.
create or replace function study_private.r_exam()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  j jsonb := to_jsonb(new);
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  if (j ->> 'deleted_at') is not null
     or not exists (select 1 from public.study_members m where m.group_id = new.group_id and m.user_id = new.created_by) then
    return null;
  end if;
  perform study_private.notice_add(new.created_by, new.group_id,
    case new.status when 'ready' then 'exam_ready' else 'exam_failed' end,
    jsonb_strip_nulls(jsonb_build_object('course', nullif(left(new.course, 120), ''), 'year', new.year,
                                         'moed', nullif(left(j ->> 'moed', 20), ''), 'kind', left(j ->> 'kind', 20),
                                         'why', case when new.status = 'failed' then left(new.error, 40) end)),
    jsonb_build_object('v', 'exams', 'e', new.id), 'exam:' || new.id, 'exam:' || new.id || ':' || new.status, null, null);
  return null;
exception when others then
  raise warning 'study_r_exam %', sqlstate;
  return null;
end;
$$;

-- "עדכון": a correction reached a line this member studied (section V
-- already chose who): inbox only, one row a lecture until seen.
create or replace function study_private.r_update()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_grp uuid;
  v_lec text;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  select l.group_id, left(l.title, 120) into v_grp, v_lec from public.study_lectures l where l.id = new.lecture_id;
  if not exists (select 1 from public.study_members m where m.group_id = v_grp and m.user_id = new.user_id) then return null; end if;
  perform study_private.notice_add(new.user_id, v_grp, 'update', jsonb_strip_nulls(jsonb_build_object('lecture', v_lec)),
    jsonb_build_object('v', 'lecture', 'l', new.lecture_id, 'at', jsonb_build_object('part', new.part_idx, 'anchor', new.anchor)),
    'lec:' || new.lecture_id, 'upd:' || new.lecture_id, new.lecture_id, null);
  return null;
exception when others then
  raise warning 'study_r_update %', sqlstate;
  return null;
end;
$$;

-- A correction waiting for approval: the rest of the group, inbox only, one
-- row a lecture until seen.
create or replace function study_private.r_edit()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_grp uuid;
  v_lec text;
begin
  if not study_private.feature_on('notify_hooks') then return null; end if;
  select l.group_id, left(l.title, 120) into v_grp, v_lec from public.study_lectures l where l.id = new.lecture_id;
  if v_grp is null then return null; end if;
  perform study_private.notice_group(v_grp, coalesce(new.proposed_by, auth.uid()), 'edit_wait',
    jsonb_strip_nulls(jsonb_build_object('lecture', v_lec)), jsonb_build_object('v', 'lecture', 'l', new.lecture_id),
    'lec:' || new.lecture_id, 'edit:' || new.lecture_id, new.lecture_id, null);
  return null;
exception when others then
  raise warning 'study_r_edit %', sqlstate;
  return null;
end;
$$;

revoke all on function study_private.r_reading(), study_private.r_meeting(), study_private.r_credit(),
  study_private.r_dispute(), study_private.r_dispute_done(), study_private.r_exam(), study_private.r_update(),
  study_private.r_edit() from public;

do $$
begin
  if to_regclass('public.study_meetings') is not null then
    drop trigger if exists study_r_reading on public.study_meetings;
    create trigger study_r_reading after update of reading on public.study_meetings
      for each row when (not old.reading and new.reading and new.cancelled_at is null) execute function study_private.r_reading();
    drop trigger if exists study_r_meeting on public.study_meetings;
    create trigger study_r_meeting after insert or update of starts_at on public.study_meetings
      for each row execute function study_private.r_meeting();
  end if;
  if to_regclass('public.study_aid_credits') is not null then
    drop trigger if exists study_r_credit on public.study_aid_credits;
    create trigger study_r_credit after insert on public.study_aid_credits
      for each row when (new.state = 'asked') execute function study_private.r_credit();
  end if;
  if to_regclass('public.study_disputes') is not null then
    drop trigger if exists study_r_dispute on public.study_disputes;
    create trigger study_r_dispute after insert on public.study_disputes
      for each row execute function study_private.r_dispute();
    drop trigger if exists study_r_dispute_done on public.study_disputes;
    create trigger study_r_dispute_done after update of state, decided_at on public.study_disputes
      for each row when (old.state is distinct from new.state and new.state in ('accepted', 'overridden', 'closed'))
      execute function study_private.r_dispute_done();
  end if;
  if to_regclass('public.study_exams') is not null then
    drop trigger if exists study_r_exam on public.study_exams;
    create trigger study_r_exam after update of status on public.study_exams
      for each row when (old.status is distinct from new.status and new.status in ('ready', 'failed'))
      execute function study_private.r_exam();
  end if;
  if to_regclass('public.study_updates') is not null then
    drop trigger if exists study_r_update on public.study_updates;
    create trigger study_r_update after insert on public.study_updates
      for each row execute function study_private.r_update();
  end if;
  if to_regclass('public.study_edit_proposals') is not null then
    drop trigger if exists study_r_edit on public.study_edit_proposals;
    create trigger study_r_edit after insert on public.study_edit_proposals
      for each row when (new.state = 'pending') execute function study_private.r_edit();
  end if;
end $$;

-- ── Who may call what ──
revoke all on function public.study_notify_claim(text, int), public.study_notify_done(text, jsonb), public.study_notify_ok() from public;
-- The server calls these with the anon key; claim and done refuse without the server key (F27's allow-list).
grant execute on function public.study_notify_claim(text, int), public.study_notify_done(text, jsonb), public.study_notify_ok() to anon, authenticated;
revoke all on function public.study_notify_state(), public.study_push_subscribe(text, text, text, text, text, text),
  public.study_push_unsubscribe(text), public.study_push_devices(text), public.study_push_remove(bigint),
  public.study_push_keep_only(text), public.study_notify_prefs_set(jsonb), public.study_notices_mine(uuid, bigint, int),
  public.study_notices_unseen(uuid), public.study_notices_seen(uuid, bigint[]), public.study_notices_seen_obj(uuid, text),
  public.study_notify_test(), public.study_quiz_quiet(uuid) from public, anon;
grant execute on function public.study_notify_state(), public.study_push_subscribe(text, text, text, text, text, text),
  public.study_push_unsubscribe(text), public.study_push_devices(text), public.study_push_remove(bigint),
  public.study_push_keep_only(text), public.study_notify_prefs_set(jsonb), public.study_notices_mine(uuid, bigint, int),
  public.study_notices_unseen(uuid), public.study_notices_seen(uuid, bigint[]), public.study_notices_seen_obj(uuid, text),
  public.study_notify_test(), public.study_quiz_quiet(uuid) to authenticated;

-- ── Every minute, and the daily clean-up (only with pg_cron) ──
do $$
begin
  if to_regnamespace('cron') is null then
    raise notice 'pg_cron is off: notices fill the inbox, but nothing is pushed. Integrations → Cron → enable pg_cron, then run this part again.';
  else
    perform cron.schedule('study-notify', '* * * * *', 'select study_private.notify_plan(); select study_private.notify_dispatch()');
    perform cron.schedule('study-notify-clean', '41 3 * * *', $c$
      delete from public.study_notices where seen_at < now() - interval '30 days' or created_at < now() - interval '60 days'
         or (kind = 'test' and created_at < now() - interval '1 day');
      delete from study_private.push_log where at < now() - interval '14 days';
      delete from public.study_push_subs where seen_at < now() - interval '120 days' and (ok_at is null or ok_at < now() - interval '120 days');
      delete from study_private.quiz_quiet where at < now() - interval '1 day';
      delete from cron.job_run_details where jobid in (select jobid from cron.job where jobname like 'study-notify%') and end_time < now() - interval '2 days'$c$);
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'net' and p.proname = 'http_post')
     or coalesce(length(study_private.secret('study_worker_key')), 0) < 32
     or coalesce(study_private.secret('study_site_url'), '') not like 'https://%' then
    raise notice 'Server writing is not set up (pg_net, Vault): the inbox works, pushes wait until it is (section W).';
  end if;
end $$;

insert into study_private.schema_sections (section, version) values ('R', 2)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ════ END SECTION R ════

-- ════ BEGIN SECTION L · practice sets (package L, "lists") ════
--  docs/study/sets.md; design-practice revision 2, §7; the decisions are in
--  docs/study/DECISIONS-2026-11-26.md ("Practice sets").
--  A set ("סט") is a titled, fixed, ordered list of bank questions with an
--  author and a date. The questions stay in the group's single bank
--  (decision 2): a set is a view over them. Every set is on the group's
--  shelf from the moment it is created (OD3): no private set, no unshare.
--  Any member hides a set for themselves; the author or the group's creator
--  deletes it (a soft delete; the questions stay in the bank).
--
--  L 1 (this version): the tables, their row security, the member RPCs
--  (shelf, open, progress, rename, delete, hide, seen, attempts, the answer
--  wrappers, the group's numbers, the names choice, the sets line's and the
--  day's figures), the op's RPCs (begin, attach, abandon, style, autokeep),
--  the trigger that fills a set from the bank, the hooks for the exams
--  design's sheet sets, the notices through R (set_shared to the group,
--  coalesced, at most one push a member a day; set_solved to the author's
--  inbox), the switches, kind_on and the nightly job.
--
--  Group numbers follow the floor of 3 (study_private.pulse_floor(), OD5):
--  "פותרים: k" and the member's own score always; the average and the
--  per-question bands only when at least 3 OTHER members whom Pulse counts
--  (7 days in the group, not opted out) finished, both computed without the
--  viewer over a fixed bucket (the first 3, 6, … of them to finish), the
--  average rounded to 0.1; no best score. Each member counts with their
--  first finished attempt, scored on the first answer per question in it
--  (recorded on the attempt when given). Raw answers stay private
--  (study_answers): a set's attempt is stamped on them by the wrappers, and
--  only definer RPCs read other members' rows.
--
--  The switches (study_private.features):
--    qsets            on: set features. Off: begin refuses ('off') and the
--                     shelf is empty; the questions stay in the bank.
--    qsets_auto_keep  off (OD15): study_qset_autokeep does nothing.
--    questions_paid   on (OD14): off stops every question-writing kind
--                     (kind_on: practice, solver, reword, style, points,
--                     bank) without a redeploy.
--      update study_private.features set enabled = false, changed_at = now() where name = 'questions_paid';
--
--  Order: after I and R in this file. Part 10 of supabase/parts starts with
--  this section (with it, part 9 would pass 170 KB); the wave's later
--  sections (Y, O) follow it there. L uses Q, X, S, T and R directly,
--  because the file always runs in order; the calls into R (notice_add,
--  its kind registry and outbox) and into O (later) are still guarded with
--  to_regprocedure and to_regclass, so a database without them loads L and
--  works.
--  Re-runnable throughout.

-- ── Sets ──
create table if not exists public.study_qsets (
  id          uuid        primary key default gen_random_uuid(),
  group_id    uuid        not null references public.study_groups (id) on delete cascade,
  kind        text        not null check (kind in ('lecture', 'course', 'sheet')),   -- 'course': WP20; 'sheet': the exams design
  title       text        not null check (char_length(btrim(title)) between 1 and 80),
  lecture_id  uuid        references public.study_lectures (id) on delete cascade,
  plan_id     uuid,                       -- a course round (S), WP20
  exam_id     uuid,                       -- a sheet set (section O; no foreign key: O comes later)
  similar_run uuid,                       -- O's study_similar_runs.id (no foreign key)
  want        int         not null check (want between 1 and 60),
  options     jsonb       not null default '{}' check (jsonb_typeof(options) = 'object' and pg_column_size(options) <= 2000),
                                          -- {level, difficulty, types[], parts[], style_sig?}; never points or a focus
  state       text        not null default 'making' check (state in ('reading', 'making', 'ready')),
  notified_at timestamptz,                -- set_shared went to the group (once)
  created_by  uuid        default auth.uid() references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz,
  deleted_by  uuid        references auth.users (id) on delete set null,
  check (kind <> 'lecture' or lecture_id is not null)
);
create index if not exists study_qsets_shelf   on public.study_qsets (group_id, created_at desc) where deleted_at is null;
create index if not exists study_qsets_lecture on public.study_qsets (lecture_id, created_at desc) where deleted_at is null;
create index if not exists study_qsets_daily   on public.study_qsets (created_by, created_at);

-- A lecture set's request (one; slice C's course sets may have several).
create table if not exists public.study_qset_requests (
  set_id     uuid not null references public.study_qsets (id) on delete cascade,
  request_id uuid not null unique references public.study_question_requests (id) on delete cascade,
  primary key (set_id, request_id)
);

-- The set's questions, in order. Filled by the trigger below (a keep, keep
-- all, auto-keep) and by O's similar run (qset_add_items).
create table if not exists public.study_qset_items (
  set_id       uuid        not null references public.study_qsets (id) on delete cascade,
  question_id  uuid        not null references public.study_questions (id) on delete cascade,
  pos          int         not null check (pos between 1 and 200),
  added_at     timestamptz not null default now(),
  auto_kept_at timestamptz,                 -- kept by study_qset_autokeep, not by a member
  primary key (set_id, question_id)
);
create index if not exists study_qset_items_question on public.study_qset_items (question_id);

-- A summary per solve; the answers themselves stay private in study_answers.
create table if not exists public.study_qset_attempts (
  id          uuid        primary key default gen_random_uuid(),
  set_id      uuid        not null references public.study_qsets (id) on delete cascade,
  user_id     uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  started_at  timestamptz not null default now(),
  finished_at timestamptz,
  total       int         not null default 0,
  answered    int         not null default 0,
  right_n     int         not null default 0
);
-- The first answer per question in the attempt, {question_id: correct},
-- recorded by the answer wrappers when it is given: the score and the
-- group's bands read this, so deleting one's own answer row and answering
-- again (study_answers' "delete own") never changes a set's score.
alter table public.study_qset_attempts add column if not exists firsts jsonb not null default '{}';
create index if not exists study_qset_attempts_set on public.study_qset_attempts (set_id, user_id, finished_at);
create index if not exists study_qset_attempts_user on public.study_qset_attempts (user_id, started_at desc);

-- Seen ("חדש" clears) and hidden for oneself.
create table if not exists public.study_qset_marks (
  user_id   uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  set_id    uuid        not null references public.study_qsets (id) on delete cascade,
  seen_at   timestamptz,
  hidden_at timestamptz,
  primary key (user_id, set_id)
);
create index if not exists study_qset_marks_set on public.study_qset_marks (set_id);

-- OD7: a member's name in "מי פתרו" only when they chose it (L's own; T's
-- study_member_prefs is untouched).
create table if not exists public.study_qset_prefs (
  user_id   uuid        primary key default auth.uid() references auth.users (id) on delete cascade,
  show_name boolean     not null default false,
  asked_at  timestamptz
);

-- The one change to Q's tables: an answer given inside a set's attempt.
alter table public.study_answers add column if not exists set_attempt uuid
  references public.study_qset_attempts (id) on delete set null;
create index if not exists study_answers_set_attempt on public.study_answers (set_attempt) where set_attempt is not null;

-- ── Row security: members read their group's live sets; their own
-- attempts, marks and choice. Nobody writes directly. ──
alter table public.study_qsets enable row level security;
alter table public.study_qset_requests enable row level security;
alter table public.study_qset_items enable row level security;
alter table public.study_qset_attempts enable row level security;
alter table public.study_qset_marks enable row level security;
alter table public.study_qset_prefs enable row level security;
drop policy if exists "study qsets read" on public.study_qsets;
create policy "study qsets read" on public.study_qsets for select to authenticated
  using (deleted_at is null and public.study_is_member(group_id));
drop policy if exists "study qset requests read" on public.study_qset_requests;
create policy "study qset requests read" on public.study_qset_requests for select to authenticated
  using (exists (select 1 from public.study_qsets s where s.id = set_id));
drop policy if exists "study qset items read" on public.study_qset_items;
create policy "study qset items read" on public.study_qset_items for select to authenticated
  using (exists (select 1 from public.study_qsets s where s.id = set_id));
drop policy if exists "study qset attempts own" on public.study_qset_attempts;
create policy "study qset attempts own" on public.study_qset_attempts for select to authenticated using (user_id = auth.uid());
drop policy if exists "study qset marks own" on public.study_qset_marks;
create policy "study qset marks own" on public.study_qset_marks for select to authenticated using (user_id = auth.uid());
drop policy if exists "study qset prefs own" on public.study_qset_prefs;
create policy "study qset prefs own" on public.study_qset_prefs for select to authenticated using (user_id = auth.uid());
revoke all on public.study_qsets, public.study_qset_requests, public.study_qset_items, public.study_qset_attempts,
  public.study_qset_marks, public.study_qset_prefs from anon, authenticated;
grant select on public.study_qsets, public.study_qset_requests, public.study_qset_items, public.study_qset_attempts,
  public.study_qset_marks, public.study_qset_prefs to authenticated;

-- ── The switches (OD14, OD15) and which switch each ledger kind obeys ──
insert into study_private.features (name, enabled) values
  ('qsets', true),             -- set features; off: begin refuses and the shelf is empty
  ('qsets_auto_keep', false),  -- OD15: off until measured (WP16)
  ('questions_paid', true)     -- OD14: off stops every question-writing kind
on conflict (name) do nothing;

-- The same text is in section F (so a later run of part 1 keeps it).
create or replace function study_private.kind_on(p_kind text)
returns boolean language sql stable security definer set search_path = public as $$
  select case
    when p_kind = 'notes' then study_private.feature_on('recordings')
    when p_kind = 'exam'  then study_private.feature_on('exams')
    when p_kind in ('practice', 'solver', 'reword', 'style', 'points', 'bank') then study_private.feature_on('questions_paid')
    else true end
$$;
revoke all on function study_private.kind_on(text) from public;

-- ── Helpers ──

-- A set the caller may see (a member of its group, not deleted, its lecture
-- not deleted), or 'set not found'.
create or replace function study_private.qset_get(p_set uuid)
returns public.study_qsets language plpgsql stable security definer set search_path = public as $$
declare s public.study_qsets;
begin
  select * into s from public.study_qsets x where x.id = p_set;
  if not found or s.deleted_at is not null or not coalesce(public.study_is_member(s.group_id), false)
     or exists (select 1 from public.study_lectures l where l.id = s.lecture_id and l.deleted_at is not null) then
    raise exception 'set not found';
  end if;
  return s;
end;
$$;

-- What a set's requests have made so far: its questions (items); drafts
-- ready (the solver passed them, or could not run) or kept; questions that
-- did not come out (batches done with fewer than they wanted); pending
-- drafts the solver could not check; batches still pending or writing, and
-- when one of them last moved; when any batch last moved.
create or replace function study_private.qset_facts(p_set uuid)
returns table (items int, made int, failed int, unchecked int, busy int, busy_at timestamptz, last_at timestamptz)
language sql stable security definer set search_path = public as $$
  with b as (select x.status, x.wanted, x.made, x.updated_at
               from public.study_question_batches x
               join public.study_qset_requests r on r.request_id = x.request_id
              where r.set_id = p_set),
       d as (select x.status, x.check_state
               from public.study_question_drafts x
               join public.study_qset_requests r on r.request_id = x.request_id
              where r.set_id = p_set),
       i as (select count(*)::int as n from public.study_qset_items y where y.set_id = p_set)
  select (select n from i),
         greatest((select n from i), (select count(*)::int from d where d.status in ('pending', 'kept') and d.check_state in ('ok', 'unchecked'))),
         (select coalesce(sum(greatest(b.wanted - b.made, 0)), 0)::int from b where b.status in ('ready', 'failed')),
         (select count(*)::int from d where d.status = 'pending' and d.check_state = 'unchecked'),
         (select count(*)::int from b where b.status in ('pending', 'writing')),
         (select max(b.updated_at) from b where b.status in ('pending', 'writing')),
         (select max(b.updated_at) from b)
$$;

-- "Paused" is computed, never stored (design §7.4): a set being written
-- whose newest batch has not moved for 6 minutes (rounds.ts's stuck rule),
-- a set still reading its lecture for 6 minutes (the points claim's lease),
-- or a lecture set begun but never attached (no batch at all: the call
-- between begin and attach died) for 2 minutes. The nightly clean-up
-- removes that last kind after an hour.
drop function if exists study_private.qset_paused(text, timestamptz, int, timestamptz);
create or replace function study_private.qset_paused(p_kind text, p_state text, p_updated timestamptz, p_busy int, p_last timestamptz)
returns boolean language sql stable set search_path = public as $$
  select case p_state
           when 'reading' then p_updated < now() - interval '6 minutes'
           when 'making' then case when p_last is null and p_kind = 'lecture' then p_updated < now() - interval '2 minutes'
                                   else coalesce(p_busy, 0) > 0 and coalesce(p_last, p_updated) < now() - interval '6 minutes' end
           else false end
$$;

-- "Open" (D6, OD20): a set on the lecture someone is making now. Reading
-- its lecture (moved in the last 10 minutes); or being written (a batch
-- pending or writing that moved in the last 30); or just begun, its request
-- not attached yet (2 minutes: begin and attach are two calls).
create or replace function study_private.qset_is_open(p_set uuid)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare s public.study_qsets; f record;
begin
  select * into s from public.study_qsets x where x.id = p_set;
  if not found or s.deleted_at is not null then return false; end if;
  if s.state = 'reading' then return s.updated_at > now() - interval '10 minutes'; end if;
  if s.state <> 'making' then return false; end if;
  if not exists (select 1 from public.study_qset_requests r where r.set_id = p_set) then
    return s.kind = 'lecture' and s.updated_at > now() - interval '2 minutes';
  end if;
  select * into f from study_private.qset_facts(p_set);
  return f.busy > 0 and f.busy_at > now() - interval '30 minutes';
end;
$$;

-- Tells the group about a set once, when it is ready with at least one
-- question (notice_set_shared below, through R's notice_add: the dedupe, the
-- coalescing and the one push a day; R's notifyCopy.ts has the words).
-- notified_at is stamped either way, so R installed later never announces
-- old sets.
create or replace function study_private.qset_announce(p_set uuid)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  s     public.study_qsets;
  n     int;
  lec   text;
  who   text;
begin
  select * into s from public.study_qsets x where x.id = p_set for update;
  if not found or s.deleted_at is not null or s.state <> 'ready' or s.notified_at is not null then return false; end if;
  select count(*)::int into n from public.study_qset_items i where i.set_id = p_set;
  if n < 1 then return false; end if;
  update public.study_qsets x set notified_at = now() where x.id = p_set;
  if to_regprocedure('study_private.notice_set_shared(uuid,uuid,uuid[],uuid,jsonb)') is not null then
    select l.title into lec from public.study_lectures l where l.id = s.lecture_id;
    select m.name into who from public.study_members m where m.group_id = s.group_id and m.user_id = s.created_by;
    begin
      execute 'select study_private.notice_set_shared($1, $2, $3, $4, $5)'
        using s.group_id, s.id, null::uuid[], s.created_by, jsonb_build_object('lecture', lec, 'k', n, 'name', who);
    exception when others then
      raise warning 'qset_announce %', sqlstate;
    end;
  end if;
  return true;
end;
$$;

-- Brings a lecture set's state up to date: ready once its request has no
-- batch pending or writing, making again when a batch is written again
-- ("לנסות שוב" after it was ready). Then the once-only notice.
create or replace function study_private.qset_refresh(p_set uuid)
returns public.study_qsets language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets; f record;
begin
  select * into s from public.study_qsets x where x.id = p_set;
  if not found then return null; end if;
  if s.deleted_at is null and s.state in ('making', 'ready')
     and exists (select 1 from public.study_qset_requests r where r.set_id = p_set) then
    select * into f from study_private.qset_facts(p_set);
    if s.state = 'making' and f.busy = 0 then
      update public.study_qsets x set state = 'ready', updated_at = now() where x.id = p_set and x.state = 'making';
    elsif s.state = 'ready' and f.busy > 0 then
      update public.study_qsets x set state = 'making', updated_at = now() where x.id = p_set and x.state = 'ready';
    end if;
  end if;
  perform study_private.qset_announce(p_set);
  select * into s from public.study_qsets x where x.id = p_set;
  return s;
end;
$$;

-- The rows the shelf, the set page and the lecture page show (one set with
-- p_set). author_name: the author's name in the group, or null once they left.
create or replace function study_private.qset_rows(p_group uuid, p_lecture uuid, p_set uuid, p_limit int)
returns table (id uuid, kind text, title text, lecture_id uuid, lecture_title text, course text, author_id uuid,
               author_name text, created_at timestamptz, updated_at timestamptz, want int, size int, made int,
               state text, paused boolean, solvers int, my_score int, my_total int, my_open_attempt uuid,
               is_new boolean, is_mine boolean, is_hidden boolean)
language sql stable security definer set search_path = public as $$
  select s.id, s.kind, s.title, s.lecture_id, l.title, coalesce(l.course, ''), s.created_by,
         (select m.name from public.study_members m where m.group_id = s.group_id and m.user_id = s.created_by),
         s.created_at, s.updated_at, s.want, f.items, f.made, s.state,
         study_private.qset_paused(s.kind, s.state, s.updated_at, f.busy, f.last_at),
         (select count(distinct a.user_id)::int from public.study_qset_attempts a where a.set_id = s.id and a.finished_at is not null),
         mine.right_n, mine.total,
         (select a.id from public.study_qset_attempts a
           where a.set_id = s.id and a.user_id = auth.uid() and a.finished_at is null and a.started_at > now() - interval '12 hours'
           order by a.started_at desc limit 1),
         s.created_by is distinct from auth.uid() and mk.seen_at is null,
         s.created_by is not distinct from auth.uid(),
         mk.hidden_at is not null
    from public.study_qsets s
    left join public.study_lectures l on l.id = s.lecture_id
    left join public.study_qset_marks mk on mk.set_id = s.id and mk.user_id = auth.uid()
    cross join lateral study_private.qset_facts(s.id) f
    left join lateral (select a.right_n, a.total from public.study_qset_attempts a
                        where a.set_id = s.id and a.user_id = auth.uid() and a.finished_at is not null
                        order by a.finished_at, a.id limit 1) mine on true
   where s.group_id = p_group and s.deleted_at is null and (l.id is null or l.deleted_at is null)
     and (p_lecture is null or s.lecture_id = p_lecture)
     and (p_set is null or s.id = p_set)
   order by s.created_at desc, s.id
   limit greatest(1, least(coalesce(p_limit, 40), 200))
$$;

-- ── The op's RPCs (the server key and the member's token) ──

-- "ליצור": checks the switches, the day's sets (p_daily, OD13), the sets
-- line (p_line USD of practice, solver, reword and style this month, OD12),
-- and, under the lecture's round lock, an open set on the lecture (D6:
-- answered as {"open": {…}} unless p_force). Then the set: state 'reading'
-- when the generating screen reads first (p_phase 'read' or 'style'), else
-- 'making' (study_qset_attach follows at once). p_set: {title, want, options}.
-- Answers {"set_id", "state"}.
-- Errors: 'forbidden', 'not signed in', 'lecture not found', 'off',
-- 'bad request', 'daily_limit', 'sets_line'.
create or replace function public.study_qset_begin(p_lecture uuid, p_set jsonb, p_phase text default null,
  p_force boolean default false, p_daily int default null, p_line numeric default null, p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me     uuid := auth.uid();
  lec    public.study_lectures;
  v_want int;
  v_ttl  text;
  v_opt  jsonb;
  v_raw  jsonb;
  o      uuid;
  f      record;
  v_id   uuid;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if me is null then raise exception 'not signed in'; end if;
  select * into lec from public.study_lectures l where l.id = p_lecture;
  if not found or lec.deleted_at is not null or not coalesce(public.study_is_member(lec.group_id), false) then
    raise exception 'lecture not found';
  end if;
  if not study_private.feature_on('qsets') or not study_private.kind_on('practice') then raise exception 'off'; end if;
  if jsonb_typeof(p_set) is distinct from 'object' or coalesce(p_set ->> 'want', '') !~ '^[0-9]{1,2}$'
     or (p_phase is not null and p_phase not in ('read', 'style'))
     or (p_set ? 'options' and jsonb_typeof(p_set -> 'options') is distinct from 'object')
     or (p_set ? 'title' and jsonb_typeof(p_set -> 'title') not in ('string', 'null')) then
    raise exception 'bad request';
  end if;
  v_want := (p_set ->> 'want')::int;
  if v_want not between 1 and 40 then raise exception 'bad request'; end if;
  v_ttl := left(btrim(regexp_replace(coalesce(p_set ->> 'title', ''), '\s+', ' ', 'g')), 80);
  if v_ttl = '' then v_ttl := left(btrim(lec.title), 80); end if;
  -- Only what the set page shows again: never the member's points or a focus.
  v_raw := coalesce(p_set -> 'options', '{}');
  v_opt := jsonb_strip_nulls(jsonb_build_object(
    'level', case when jsonb_typeof(v_raw -> 'level') = 'string' then v_raw -> 'level' end,
    'difficulty', case when jsonb_typeof(v_raw -> 'difficulty') = 'string' then v_raw -> 'difficulty' end,
    'types', case when jsonb_typeof(v_raw -> 'types') = 'array' then v_raw -> 'types' end,
    'parts', case when jsonb_typeof(v_raw -> 'parts') = 'array' then v_raw -> 'parts' end));
  if pg_column_size(v_opt) > 2000 then raise exception 'bad request'; end if;
  -- The day's sets: one count at a time per member (two lectures at once cannot both pass).
  perform pg_advisory_xact_lock(hashtext('study_qset_daily:' || me::text));
  if p_daily is not null
     and (select count(*) from public.study_qsets s
           where s.created_by = me and s.kind in ('lecture', 'course')
             and s.created_at >= (date_trunc('day', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem')) >= p_daily then
    raise exception 'daily_limit';
  end if;
  if p_line is not null
     and coalesce((select sum(u.cost_usd) from public.study_usage u
                    where u.group_id = lec.group_id and u.kind in ('practice', 'solver', 'reword', 'style')
                      and u.created_at >= (date_trunc('month', now() at time zone 'utc') at time zone 'utc')), 0) >= p_line then
    raise exception 'sets_line';
  end if;
  perform pg_advisory_xact_lock(hashtext('study_question_round:' || p_lecture::text));
  if not coalesce(p_force, false) then
    select s.id into o from public.study_qsets s
     where s.lecture_id = p_lecture and s.deleted_at is null and s.state in ('reading', 'making')
       and study_private.qset_is_open(s.id)
     order by s.created_at desc limit 1;
    if o is not null then
      select * into f from study_private.qset_facts(o);
      return jsonb_build_object('open', (
        select jsonb_build_object('set_id', s.id, 'state', s.state, 'want', s.want, 'made', f.made,
                                  'author_name', (select m.name from public.study_members m where m.group_id = s.group_id and m.user_id = s.created_by),
                                  'mine', s.created_by = me)
          from public.study_qsets s where s.id = o));
    end if;
  end if;
  insert into public.study_qsets (group_id, kind, title, lecture_id, want, options, state, created_by)
  values (lec.group_id, 'lecture', v_ttl, p_lecture, v_want, v_opt,
          case when p_phase in ('read', 'style') then 'reading' else 'making' end, me)
  returning id into v_id;
  return jsonb_build_object('set_id', v_id, 'state', case when p_phase in ('read', 'style') then 'reading' else 'making' end);
end;
$$;

-- The set's request and batches (Q's study_request_create, with its rules
-- and refusals), under the same round lock; only the author, only once.
-- The set is 'making' after it and wants what the request plans.
create or replace function public.study_qset_attach(p_set uuid, p_request jsonb, p_batches jsonb, p_key text default null)
returns table (set_id uuid, request_id uuid, round int, batch_id uuid, part_idx int, seq int, wanted int)
language plpgsql volatile security definer set search_path = public as $$
#variable_conflict use_column
declare
  me  uuid := auth.uid();
  s   public.study_qsets;
  q   record;
  rid uuid;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if me is null then raise exception 'not signed in'; end if;
  select * into s from public.study_qsets x where x.id = p_set;
  if not found or s.deleted_at is not null or s.created_by is distinct from me or s.kind <> 'lecture'
     or not coalesce(public.study_is_member(s.group_id), false) then
    raise exception 'set not found';
  end if;
  perform pg_advisory_xact_lock(hashtext('study_question_round:' || s.lecture_id::text));   -- before the row, as keep
  perform 1 from public.study_qsets x where x.id = p_set for update;
  if exists (select 1 from public.study_qset_requests r where r.set_id = p_set) then raise exception 'set has a request'; end if;
  for q in select * from public.study_request_create(s.lecture_id, p_request, p_batches, p_key) loop
    if rid is null then
      rid := q.request_id;
      insert into public.study_qset_requests (set_id, request_id) values (p_set, rid);
    end if;
    set_id := p_set; request_id := q.request_id; round := q.round; batch_id := q.batch_id;
    part_idx := q.part_idx; seq := q.seq; wanted := q.wanted;
    return next;
  end loop;
  update public.study_qsets x
     set state = 'making', updated_at = now(),
         want = coalesce((select least(greatest(r.count, 1), 60) from public.study_question_requests r where r.id = rid), x.want)
   where x.id = p_set;
end;
$$;

-- A set that never got its request (Q refused, or the author left the
-- reading phase) is removed; one with a request or questions stays.
create or replace function public.study_qset_abandon(p_set uuid)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into s from public.study_qsets x where x.id = p_set;
  if not found or s.created_by is distinct from auth.uid() then return false; end if;
  if s.lecture_id is not null then
    perform pg_advisory_xact_lock(hashtext('study_question_round:' || s.lecture_id::text));
  end if;
  delete from public.study_qsets x
   where x.id = p_set
     and not exists (select 1 from public.study_qset_requests r where r.set_id = x.id)
     and not exists (select 1 from public.study_qset_items i where i.set_id = x.id);
  return found;
end;
$$;

-- The example's signed style (the op's signStyle), kept on the set while it
-- reads, so a retry does not pay again.
create or replace function public.study_qset_style(p_set uuid, p_sig text, p_key text default null)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if coalesce(p_sig, '') !~ '^[0-9a-f]{64}$' then raise exception 'bad request'; end if;
  s := study_private.qset_get(p_set);
  -- Only the author's own lecture set (another member never writes on it).
  if s.created_by is distinct from auth.uid() or s.kind <> 'lecture' then raise exception 'set not found'; end if;
  if s.state <> 'reading' then return false; end if;
  update public.study_qsets x set options = x.options || jsonb_build_object('style_sig', p_sig), updated_at = now()
   where x.id = p_set;
  return true;
end;
$$;

-- Auto-keep (OD15, slice C): the op "write" passes the drafts its solver
-- just passed. Nothing while the switch qsets_auto_keep is off. For each
-- draft of a set's request: first the lecture's round lock, then the draft
-- row (keep's order, so it never deadlocks with "להוסיף הכול"); only a
-- pending draft the solver passed (check_state 'ok', not 'unchecked'), a
-- staged case only when every step passed; never past 150 active questions.
create or replace function public.study_qset_autokeep(p_drafts uuid[], p_key text default null)
returns table (draft_id uuid, question_id uuid)
language plpgsql volatile security definer set search_path = public as $$
#variable_conflict use_column
declare
  x   uuid;
  lec uuid;
  rq  uuid;
  d   public.study_question_drafts;
  t   public.study_question_drafts;
  m   int;
  qid uuid;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if not study_private.feature_on('qsets_auto_keep') then return; end if;
  for x in select distinct u from unnest(coalesce(p_drafts, '{}')) u where u is not null order by 1 loop
    lec := null; rq := null;
    select y.lecture_id, y.request_id into lec, rq from public.study_question_drafts y where y.id = x;
    continue when lec is null or not exists (select 1 from public.study_qset_requests r where r.request_id = rq);
    continue when exists (select 1 from public.study_lectures l where l.id = lec and l.deleted_at is not null);
    perform pg_advisory_xact_lock(hashtext('study_question_round:' || lec::text));
    select * into d from public.study_question_drafts y where y.id = x for update;
    continue when d.id is null or d.status <> 'pending' or d.check_state <> 'ok' or d.lease_until > now();
    if d.series is not null then
      perform 1 from public.study_question_drafts y where y.series = d.series and y.status = 'pending' for update;
      continue when exists (select 1 from public.study_question_drafts y where y.series = d.series and y.status = 'pending'
                             and (y.check_state <> 'ok' or y.lease_until > now()));
      select count(*)::int into m from public.study_question_drafts y where y.series = d.series and y.status = 'pending';
      continue when (select count(*) from public.study_questions q where q.lecture_id = lec and q.retired_at is null) + m > 150;
      for t in select * from public.study_question_drafts y where y.series = d.series and y.status = 'pending' order by y.step loop
        qid := study_private.draft_to_bank(t);
        update public.study_qset_items i set auto_kept_at = now() where i.question_id = qid;
        draft_id := t.id; question_id := qid;
        return next;
      end loop;
      continue;
    end if;
    continue when (select count(*) from public.study_questions q where q.lecture_id = lec and q.retired_at is null) >= 150;
    qid := study_private.draft_to_bank(d);
    update public.study_qset_items i set auto_kept_at = now() where i.question_id = qid;
    draft_id := d.id; question_id := qid;
    return next;
  end loop;
end;
$$;

-- ── The member's RPCs ──

-- The generating screen (and the set page while it is made): the state,
-- brought up to date, and the counts. paused: nobody is writing it (§7.4).
create or replace function public.study_qset_progress(p_set uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets; f record;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  s := study_private.qset_get(p_set);
  s := study_private.qset_refresh(p_set);
  select * into f from study_private.qset_facts(p_set);
  return jsonb_build_object('state', s.state, 'want', s.want, 'made', f.made, 'size', f.items, 'failed', f.failed,
                            'unchecked', f.unchecked, 'paused', study_private.qset_paused(s.kind, s.state, s.updated_at, f.busy, f.last_at));
end;
$$;

-- The author renames a set.
create or replace function public.study_qset_rename(p_set uuid, p_title text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets; t text := left(btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g')), 80);
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  s := study_private.qset_get(p_set);
  if s.created_by is distinct from auth.uid() then raise exception 'not yours'; end if;
  if t = '' then raise exception 'bad title'; end if;
  update public.study_qsets x set title = t, updated_at = now() where x.id = p_set;
end;
$$;

-- The author or the group's creator deletes a set (OD3): it leaves every
-- shelf; its questions stay in the bank.
create or replace function public.study_qset_delete(p_set uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  s := study_private.qset_get(p_set);
  if s.created_by is distinct from auth.uid()
     and not exists (select 1 from public.study_groups g where g.id = s.group_id and g.created_by = auth.uid()) then
    raise exception 'not yours';
  end if;
  update public.study_qsets x set deleted_at = now(), deleted_by = auth.uid(), updated_at = now() where x.id = p_set;
end;
$$;

-- Hides a set for the caller only ("להסתיר אצלי"), or brings it back.
create or replace function public.study_qset_hide(p_set uuid, p_hidden boolean)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform study_private.qset_get(p_set);
  insert into public.study_qset_marks as k (user_id, set_id, hidden_at)
  values (auth.uid(), p_set, case when coalesce(p_hidden, false) then now() end)
  on conflict (user_id, set_id) do update set hidden_at = case when coalesce(p_hidden, false) then coalesce(k.hidden_at, now()) end;
end;
$$;

-- "חדש" clears: the sets the caller opened (those they may see).
create or replace function public.study_qset_seen(p_sets uuid[])
returns int language plpgsql volatile security definer set search_path = public as $$
declare n int;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into public.study_qset_marks as k (user_id, set_id, seen_at)
  select auth.uid(), s.id, now() from public.study_qsets s
   where s.id = any (coalesce(p_sets, '{}')) and s.deleted_at is null and public.study_is_member(s.group_id)
  on conflict (user_id, set_id) do update set seen_at = coalesce(k.seen_at, excluded.seen_at);
  get diagnostics n = row_count;
  return n;
end;
$$;

-- The shelf, "סטים של הקבוצה" (with p_lecture: the sets on a lecture).
-- Newest first; hidden ones are in it with is_hidden (the screen folds
-- them). No group average here (only on the set page). Empty while the
-- switch qsets is off.
create or replace function public.study_qsets_shelf(p_group uuid, p_lecture uuid default null, p_limit int default 40)
returns table (id uuid, kind text, title text, lecture_id uuid, lecture_title text, course text, author_id uuid,
               author_name text, created_at timestamptz, updated_at timestamptz, want int, size int, made int,
               state text, paused boolean, solvers int, my_score int, my_total int, my_open_attempt uuid,
               is_new boolean, is_mine boolean, is_hidden boolean)
language plpgsql volatile security definer set search_path = public as $$
declare x uuid;
begin
  if auth.uid() is null or not coalesce(public.study_is_member(p_group), false) then raise exception 'forbidden'; end if;
  if not study_private.feature_on('qsets') then return; end if;
  for x in select s.id from public.study_qsets s
            where s.group_id = p_group and s.deleted_at is null and (p_lecture is null or s.lecture_id = p_lecture)
              and (s.state = 'making' or (s.state = 'ready' and s.notified_at is null))
              and s.created_at > now() - interval '30 days' loop
    perform study_private.qset_refresh(x);
  end loop;
  return query select * from study_private.qset_rows(p_group, p_lecture, null, p_limit);
end;
$$;

-- The set page: its row as on the shelf, its questions in order, the
-- caller's attempts, the drafts the solver could not check ("לאשר או
-- להסיר"). 'set not found' for a deleted set or another group's.
create or replace function public.study_qset_open(p_set uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s public.study_qsets;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  s := study_private.qset_get(p_set);
  s := study_private.qset_refresh(p_set);
  return jsonb_build_object(
    'set', (select to_jsonb(r) from study_private.qset_rows(s.group_id, null, p_set, 1) r),
    'options', s.options,
    'items', coalesce((select jsonb_agg(jsonb_build_object('question_id', i.question_id, 'pos', i.pos) order by i.pos)
                         from public.study_qset_items i where i.set_id = p_set), '[]'),
    'my_attempts', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'started_at', a.started_at, 'finished_at', a.finished_at,
                                                                 'total', a.total, 'answered', a.answered, 'right_n', a.right_n)
                                              order by a.started_at)
                               from public.study_qset_attempts a where a.set_id = p_set and a.user_id = auth.uid()), '[]'),
    'unchecked', coalesce((select jsonb_agg(d.id order by d.part_idx, d.created_at)
                             from public.study_question_drafts d join public.study_qset_requests r on r.request_id = d.request_id
                            where r.set_id = p_set and d.status = 'pending' and d.check_state = 'unchecked'), '[]'));
end;
$$;

-- D6: the open sets on a lecture (someone is making one now).
create or replace function public.study_lecture_making(p_lecture uuid)
returns table (set_id uuid, author_name text, made int, want int, state text, updated_at timestamptz, is_mine boolean)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare g uuid := public.study_lecture_group(p_lecture);
begin
  if auth.uid() is null or g is null or not coalesce(public.study_is_member(g), false) then raise exception 'forbidden'; end if;
  if not study_private.feature_on('qsets') then return; end if;
  return query
  select s.id, (select m.name from public.study_members m where m.group_id = s.group_id and m.user_id = s.created_by),
         f.made, s.want, s.state, s.updated_at, s.created_by is not distinct from auth.uid()
    from public.study_qsets s cross join lateral study_private.qset_facts(s.id) f
   where s.lecture_id = p_lecture and s.deleted_at is null and s.state in ('reading', 'making')
     and study_private.qset_is_open(s.id)
   order by s.created_at desc;
end;
$$;

-- The create screen's two figures a member cannot read from the ledger:
-- the group's spend this month of the kinds the sets line counts, and the
-- sets the caller began today (Israel time).
create or replace function public.study_qset_room(p_group uuid)
returns table (sets_usd numeric, today int)
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null or not coalesce(public.study_is_member(p_group), false) then raise exception 'forbidden'; end if;
  return query
  select coalesce((select sum(u.cost_usd) from public.study_usage u
                    where u.group_id = p_group and u.kind in ('practice', 'solver', 'reword', 'style')
                      and u.created_at >= (date_trunc('month', now() at time zone 'utc') at time zone 'utc')), 0)::numeric,
         (select count(*)::int from public.study_qsets s
           where s.created_by = auth.uid() and s.kind in ('lecture', 'course')
             and s.created_at >= (date_trunc('day', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem'));
end;
$$;

-- "לפתור": the caller's open attempt from the last 12 hours, or a new one
-- sized to the set as it is now.
create or replace function public.study_qset_attempt_start(p_set uuid)
returns public.study_qset_attempts language plpgsql volatile security definer set search_path = public as $$
declare a public.study_qset_attempts;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform study_private.qset_get(p_set);
  select * into a from public.study_qset_attempts x
   where x.set_id = p_set and x.user_id = auth.uid() and x.finished_at is null and x.started_at > now() - interval '12 hours'
   order by x.started_at desc limit 1;
  if found then return a; end if;
  insert into public.study_qset_attempts (set_id, user_id, total)
  values (p_set, auth.uid(), (select count(*)::int from public.study_qset_items i where i.set_id = p_set))
  returning * into a;
  return a;
end;
$$;

-- The attempt the caller may answer in: their own, open, of a set they still see.
create or replace function study_private.qset_attempt_open(p_attempt uuid, p_question uuid)
returns public.study_qset_attempts language plpgsql stable security definer set search_path = public as $$
declare a public.study_qset_attempts;
begin
  select * into a from public.study_qset_attempts x where x.id = p_attempt;
  if not found or a.user_id is distinct from auth.uid() then raise exception 'attempt not found'; end if;
  if a.finished_at is not null then raise exception 'attempt finished'; end if;
  perform study_private.qset_get(a.set_id);
  if not exists (select 1 from public.study_qset_items i where i.set_id = a.set_id and i.question_id = p_question) then
    raise exception 'not in set';
  end if;
  return a;
end;
$$;

-- The answer row a wrapper's call just added (exactly that one, whatever
-- its time) gets the attempt; the attempt records it as the question's first
-- answer unless one is recorded already.
create or replace function study_private.qset_stamp(p_attempt uuid, p_question uuid, p_before uuid[])
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_ok boolean;
begin
  update public.study_answers x set set_attempt = p_attempt
   where x.user_id = auth.uid() and x.question_id = p_question and x.id <> all (coalesce(p_before, '{}'));
  if not found then return; end if;
  select x.correct into v_ok from public.study_answers x
   where x.set_attempt = p_attempt and x.user_id = auth.uid() and x.question_id = p_question and x.id <> all (coalesce(p_before, '{}'))
   order by x.answered_at, x.id limit 1;
  update public.study_qset_attempts a set firsts = a.firsts || jsonb_build_object(p_question::text, coalesce(v_ok, false))
   where a.id = p_attempt and not (a.firsts ? p_question::text);
end;
$$;

-- Answers inside a set (practice.ts calls these instead of Q's and X's):
-- the same answer, the same checks and the same reply, then the attempt
-- stamped on the answer that call added (qset_stamp).
create or replace function public.study_qset_answer(p_attempt uuid, p_question uuid, p_choice int, p_mode text default 'lecture',
  p_ms int default null, p_confidence int default null)
returns table (answer int, explanations text[], takeaway text, correct boolean, whens text[])
language plpgsql volatile security definer set search_path = public as $$
#variable_conflict use_column
declare v_before uuid[];
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform study_private.qset_attempt_open(p_attempt, p_question);
  v_before := array(select y.id from public.study_answers y where y.user_id = auth.uid() and y.question_id = p_question);
  return query select * from public.study_answer_question(p_question, p_choice, p_mode, p_ms, p_confidence);
  perform study_private.qset_stamp(p_attempt, p_question, v_before);
end;
$$;

create or replace function public.study_qset_answer_seq(p_attempt uuid, p_question uuid, p_choices int[], p_mode text default 'lecture',
  p_ms int default null, p_confidence int default null)
returns table (seq int[], explanations text[], takeaway text, correct boolean, whens text[], right_n int, total int)
language plpgsql volatile security definer set search_path = public as $$
#variable_conflict use_column
declare v_before uuid[];
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform study_private.qset_attempt_open(p_attempt, p_question);
  v_before := array(select y.id from public.study_answers y where y.user_id = auth.uid() and y.question_id = p_question);
  return query select * from public.study_answer_set(p_question, p_choices, p_mode, p_ms, p_confidence);
  perform study_private.qset_stamp(p_attempt, p_question, v_before);
end;
$$;

-- The end of an attempt: scored on the FIRST answer per question in it, as
-- the wrappers recorded it (an answer again after the explanation, or after
-- deleting one's own answer row, changes nothing). Only a member who still
-- sees the set finishes (qset_get: not a deleted set, not after leaving the
-- group); a finished attempt answers its score again. An attempt with no
-- answer is dropped (it never counts as solving). The first finished
-- attempt of someone other than the author tells the author (set_solved,
-- inbox only, once R registers the kind). Answers {answered, right_n,
-- total, first}; again for a finished attempt, its score.
create or replace function public.study_qset_attempt_finish(p_attempt uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me    uuid := auth.uid();
  a     public.study_qset_attempts;
  s     public.study_qsets;
  v_ans int;
  v_ok  int;
  v_first boolean;
  k     int;
begin
  if me is null then raise exception 'not signed in'; end if;
  select * into a from public.study_qset_attempts x where x.id = p_attempt for update;
  if not found or a.user_id is distinct from me then raise exception 'attempt not found'; end if;
  if a.finished_at is not null then
    return jsonb_build_object('answered', a.answered, 'right_n', a.right_n, 'total', a.total, 'first', false);
  end if;
  perform study_private.qset_get(a.set_id);
  select count(*)::int, count(*) filter (where e.value = 'true'::jsonb)::int into v_ans, v_ok from jsonb_each(a.firsts) e;
  if v_ans = 0 then
    delete from public.study_qset_attempts x where x.id = p_attempt;
    return jsonb_build_object('answered', 0, 'right_n', 0, 'total', a.total, 'first', false);
  end if;
  v_first := not exists (select 1 from public.study_qset_attempts x
                        where x.set_id = a.set_id and x.user_id = me and x.finished_at is not null);
  update public.study_qset_attempts x
     set finished_at = now(), answered = v_ans, right_n = v_ok, total = greatest(x.total, v_ans)
   where x.id = p_attempt
  returning * into a;
  select * into s from public.study_qsets x where x.id = a.set_id;
  if v_first and s.created_by is not null and s.created_by <> me and s.deleted_at is null
     and to_regprocedure('study_private.notice_add(uuid,uuid,text,jsonb,jsonb,text,text,uuid,timestamptz)') is not null
     and to_regclass('study_private.notice_kinds') is not null then
    begin
      execute 'select count(*)::int from study_private.notice_kinds where kind = $1' into k using 'set_solved';
      if k > 0 then
        execute 'select study_private.notice_add($1, $2, $3, $4, $5, $6, $7, $8, null)'
          using s.created_by, s.group_id, 'set_solved',
                jsonb_build_object('title', s.title, 'k', (select count(distinct y.user_id) from public.study_qset_attempts y
                                                            where y.set_id = s.id and y.finished_at is not null and y.user_id <> s.created_by)),
                jsonb_build_object('v', 'sets', 'k', s.id), 'qset:' || s.id::text, 'qset_solved:' || s.id::text, s.lecture_id;
      end if;
    exception when others then
      raise warning 'qset set_solved %', sqlstate;
    end;
  end if;
  return jsonb_build_object('answered', a.answered, 'right_n', a.right_n, 'total', a.total, 'first', v_first);
end;
$$;

-- The group's numbers on a set (OD5, as fixed after review: docs/study/
-- DECISIONS-2026-11-26.md). solvers: members with a finished attempt.
-- mine: the caller's first finished attempt. The group's numbers count only
-- OTHER members whom Pulse counts (pulse_counted: in the group 7 days, not
-- opted out of Pulse, still a member), each with their first finished
-- attempt and its first answers. avg (the share right, 0-1, rounded to 0.1)
-- and per_q (bands: 1 most were wrong, 2 some, 3 most were right) only from
-- pulse_floor() such others, and only over a fixed bucket: the first 3 (6,
-- 9, …) of them to finish. One more finisher changes nothing until the next
-- step of 3, so nobody's score can be read off two calls made before and
-- after their finish. A band only where the floor's number of the bucket
-- answered the question. others: how many others count; counted: the
-- bucket's size. names: of finishers who chose to show their name (OD7),
-- never a score.
create or replace function public.study_qset_stats(p_set uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  me     uuid := auth.uid();
  s      public.study_qsets;
  fl     int := study_private.pulse_floor();
  firsts jsonb;
  bucket jsonb;
  n_all  int;
  n_oth  int;
  n_b    int := 0;
  v_mine jsonb;
  v_avg  numeric;
  v_perq jsonb;
  v_name jsonb;
begin
  if me is null then raise exception 'not signed in'; end if;
  s := study_private.qset_get(p_set);
  -- Each member's first finished attempt.
  select coalesce(jsonb_agg(to_jsonb(f)), '[]') into firsts
    from (select distinct on (a.user_id) a.id, a.user_id, a.total, a.answered, a.right_n, a.finished_at, a.firsts
            from public.study_qset_attempts a
           where a.set_id = p_set and a.finished_at is not null
           order by a.user_id, a.finished_at, a.id) f;
  n_all := jsonb_array_length(firsts);
  select jsonb_build_object('answered', f.answered, 'right_n', f.right_n, 'total', f.total) into v_mine
    from jsonb_to_recordset(firsts) as f (id uuid, user_id uuid, total int, answered int, right_n int, finished_at timestamptz, firsts jsonb)
   where f.user_id = me;
  -- The others who count, earliest finish first; the bucket is the first n_b of them.
  select coalesce(jsonb_agg(to_jsonb(b) order by b.finished_at, b.id), '[]') into bucket
    from (select f.* from jsonb_to_recordset(firsts) as f (id uuid, user_id uuid, total int, answered int, right_n int, finished_at timestamptz, firsts jsonb)
           where f.user_id <> me and f.user_id in (select c.user_id from study_private.pulse_counted(s.group_id) c)) b;
  n_oth := jsonb_array_length(bucket);
  if n_oth >= fl then
    n_b := (n_oth / fl) * fl;
    select round(avg(b.right_n::numeric / nullif(greatest(b.total, b.answered), 0)), 1) into v_avg
      from (select * from jsonb_to_recordset(bucket) as f (id uuid, user_id uuid, total int, answered int, right_n int, finished_at timestamptz, firsts jsonb)
             order by f.finished_at, f.id limit n_b) b;
    select jsonb_agg(jsonb_build_object('question_id', i.question_id, 'pos', i.pos,
                                        'band', case when c.n < fl then null
                                                     when c.r::numeric / c.n < 0.34 then 1
                                                     when c.r::numeric / c.n <= 0.66 then 2
                                                     else 3 end) order by i.pos)
      into v_perq
      from public.study_qset_items i
      cross join lateral (
        select count(*)::int as n, count(*) filter (where b.firsts -> i.question_id::text = 'true'::jsonb)::int as r
          from (select * from jsonb_to_recordset(bucket) as f (id uuid, user_id uuid, total int, answered int, right_n int, finished_at timestamptz, firsts jsonb)
                 order by f.finished_at, f.id limit n_b) b
         where b.firsts ? i.question_id::text) c
     where i.set_id = p_set;
  end if;
  select jsonb_agg(m.name order by m.name) into v_name
    from jsonb_to_recordset(firsts) as f (id uuid, user_id uuid, total int, answered int, right_n int, finished_at timestamptz, firsts jsonb)
    join public.study_qset_prefs p on p.user_id = f.user_id and p.show_name
    join public.study_members m on m.group_id = s.group_id and m.user_id = f.user_id;
  return jsonb_build_object('solvers', n_all, 'others', n_oth, 'counted', n_b, 'floor', fl, 'mine', v_mine, 'avg', v_avg,
                            'per_q', v_perq, 'names', coalesce(v_name, '[]'));
end;
$$;

-- OD7: "להציג את השם שלי ברשימת מי פתרו" (asked once, then in שלי).
create or replace function public.study_qset_names_pref(p_on boolean)
returns boolean language plpgsql volatile security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into public.study_qset_prefs as p (user_id, show_name, asked_at) values (auth.uid(), coalesce(p_on, false), now())
  on conflict (user_id) do update set show_name = excluded.show_name, asked_at = now();
  return coalesce(p_on, false);
end;
$$;

-- ── The trigger: a question kept from a set's request joins the set ──
-- One trigger for a member's keep, keep all and auto-keep alike. The keep
-- paths hold the round lock and then the draft row when the insert fires;
-- this locks only the set row (as progress does), so there is no cycle. Its
-- body never fails the keep: an error is a warning and the set misses that
-- question. Rollback (sets stop filling, nothing else changes):
--   alter table public.study_questions disable trigger study_qset_items_from_bank;
create or replace function study_private.qset_item_from_bank()
returns trigger language plpgsql security definer set search_path = public set lock_timeout = '2s' as $$
declare v_set uuid; v_pos int;
begin
  select r.set_id into v_set from public.study_qset_requests r where r.request_id = new.request_id;
  if v_set is null then return null; end if;
  perform 1 from public.study_qsets s where s.id = v_set for update;
  select coalesce(max(i.pos), 0) + 1 into v_pos from public.study_qset_items i where i.set_id = v_set;
  if v_pos <= 200 then
    insert into public.study_qset_items (set_id, question_id, pos) values (v_set, new.id, v_pos) on conflict do nothing;
    update public.study_qsets s set updated_at = now() where s.id = v_set;
  end if;
  return null;
exception when others then
  raise warning 'study_qset_items_from_bank %', sqlstate;
  return null;
end;
$$;
drop trigger if exists study_qset_items_from_bank on public.study_questions;
create trigger study_qset_items_from_bank after insert on public.study_questions
  for each row when (new.request_id is not null) execute function study_private.qset_item_from_bank();

-- ── Hooks for the other sections (guarded on their side) ──

-- The set of a request, or null (a seam: R sends nothing for questions being
-- written, notify's OD21; a later "questions ready" notice skips a set's
-- request with it, so an author never gets two notices for one set).
create or replace function study_private.qset_of_request(p_request uuid)
returns uuid language sql stable security definer set search_path = public as $$
  select r.set_id from public.study_qset_requests r join public.study_qsets s on s.id = r.set_id
   where r.request_id = p_request and s.deleted_at is null
$$;

-- The exams design (section O 2): a "similar" run is a set of kind 'sheet'.
create or replace function study_private.qset_for_similar(p_group uuid, p_exam uuid, p_run uuid, p_by uuid, p_title text, p_want int)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid; t text := left(btrim(coalesce(p_title, '')), 80);
begin
  if p_group is null or t = '' then raise exception 'bad request'; end if;
  insert into public.study_qsets (group_id, kind, title, exam_id, similar_run, want, state, created_by)
  values (p_group, 'sheet', t, p_exam, p_run, least(greatest(coalesce(p_want, 1), 1), 60), 'making', p_by)
  returning id into v_id;
  return v_id;
end;
$$;

-- Appends questions at the next places (a question already in it is skipped).
create or replace function study_private.qset_add_items(p_set uuid, p_questions uuid[])
returns int language plpgsql volatile security definer set search_path = public as $$
declare q uuid; v_pos int; n int := 0;
begin
  perform 1 from public.study_qsets s where s.id = p_set and s.deleted_at is null for update;
  if not found then return 0; end if;
  select coalesce(max(i.pos), 0) into v_pos from public.study_qset_items i where i.set_id = p_set;
  for q in select u from unnest(coalesce(p_questions, '{}')) with ordinality as t(u, o) where u is not null order by o loop
    exit when v_pos >= 200;
    continue when exists (select 1 from public.study_qset_items i where i.set_id = p_set and i.question_id = q);
    v_pos := v_pos + 1;
    insert into public.study_qset_items (set_id, question_id, pos) values (p_set, q, v_pos);
    n := n + 1;
  end loop;
  update public.study_qsets s set updated_at = now() where s.id = p_set;
  return n;
end;
$$;

-- The run's last job: ready, then the same once-only notice.
create or replace function study_private.qset_similar_done(p_set uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  update public.study_qsets s set state = 'ready', updated_at = now() where s.id = p_set and s.state <> 'ready';
  perform study_private.qset_announce(p_set);
end;
$$;

-- ── The notices (WP17), through section R ──
-- R's kind registry already reserves set_shared ('mine', 7 days, pushed);
-- L registers set_solved (the author's inbox only). Both go through R's
-- notice_add, so R's switches, quiet hours, its daily caps and the inbox's
-- "seen" apply unchanged; R's SQL is not touched (R stays at 2). R has no
-- notice for questions being written (notify's OD21), so a set's request
-- never sends its author a second notice. The words are R's
-- (shared/study/notifyCopy.ts): the lock screen never shows the lecture or
-- the author's name.
do $$
begin
  if to_regclass('study_private.notice_kinds') is null then
    raise notice 'section R is not installed: practice sets work, and the group hears about new sets once R is (run its part, then this one again)';
  else
    insert into study_private.notice_kinds (kind, cat, ttl, delay, push) values
      ('set_solved', 'inapp', '30 days', '0', false)
    on conflict (kind) do update set cat = excluded.cat, ttl = excluded.ttl, delay = excluded.delay, push = excluded.push;
  end if;
end $$;

-- set_shared: the group, but the author (p_to: only these members), hears
-- about a set once it is ready (qset_announce). One row a member a day,
-- Israel time (dedupe 'qsets:<group>:<date>'): a second set that day adds
-- to its count while it is unseen ("3 סטים חדשים בקבוצה", the route then the
-- shelf, the args emptied so no lecture lingers), and at most one push a
-- member a day (OD10): once a set_shared push went out today, a new or
-- coalesced row stays in the inbox; a set_shared push being sent right now
-- counts as pushed (R's "again" would otherwise send a second one). obj
-- 'qsets': opening the shelf sees it. Each member's row is its own step: one
-- that fails is a warning and the others stay. Never raises; answers how
-- many members got the row.
create or replace function study_private.notice_set_shared(p_group uuid, p_set uuid, p_to uuid[], p_actor uuid, p_args jsonb)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  v_day    date := (now() at time zone 'Asia/Jerusalem')::date;
  v_since  timestamptz := v_day::timestamp at time zone 'Asia/Jerusalem';
  v_dedupe text;
  v_lec    uuid;
  v_args   jsonb;
  v_open   boolean;
  v_pushed boolean;
  v_id     bigint;
  u        uuid;
  n        int := 0;
begin
  if p_group is null or p_set is null
     or to_regprocedure('study_private.notice_add(uuid,uuid,text,jsonb,jsonb,text,text,uuid,timestamptz)') is null
     or to_regclass('study_private.notify_outbox') is null then
    return 0;
  end if;
  v_dedupe := 'qsets:' || p_group::text || ':' || to_char(v_day, 'YYYY-MM-DD');
  select s.lecture_id into v_lec from public.study_qsets s where s.id = p_set;
  -- Only what R's words read: the lecture's title, the size, the author's name (no other key gets through).
  v_args := jsonb_strip_nulls(jsonb_build_object(
    'lecture', left(nullif(btrim(coalesce(p_args ->> 'lecture', '')), ''), 120),
    'k', case when coalesce(p_args ->> 'k', '') ~ '^[0-9]{1,3}$' then (p_args ->> 'k')::int end,
    'name', left(nullif(btrim(coalesce(p_args ->> 'name', '')), ''), 60)));
  for u in select m.user_id from public.study_members m
            where m.group_id = p_group and m.user_id is distinct from p_actor
              and (p_to is null or m.user_id = any (p_to))
            order by m.user_id loop
    begin
      select exists (select 1 from public.study_notices x where x.user_id = u and x.dedupe = v_dedupe and x.seen_at is null),
             exists (select 1 from study_private.notify_outbox o
                      where o.user_id = u and o.kind = 'set_shared' and (o.pushed_at >= v_since or o.state = 'sending'))
        into v_open, v_pushed;
      v_id := study_private.notice_add(u, p_group, 'set_shared',
                case when v_open then '{}'::jsonb else v_args end,
                case when v_open then jsonb_build_object('v', 'sets') else jsonb_build_object('v', 'sets', 'k', p_set) end,
                'qsets', v_dedupe, v_lec, null);
      continue when v_id is null;
      if v_pushed then
        -- Already pushed (or being pushed) today: this one waits in the inbox (a row being sent keeps its lease, without a second send).
        update study_private.notify_outbox o
           set again = false,
               state = case when o.state = 'due' then case when o.pushed_at is not null then 'sent' else 'capped' end else o.state end
         where o.notice_id = v_id and (o.state = 'due' or o.again);
      end if;
      n := n + 1;
    exception when others then
      raise warning 'notice_set_shared %', sqlstate;
    end;
  end loop;
  return n;
exception when others then
  raise warning 'notice_set_shared %', sqlstate;
  return 0;
end;
$$;

-- ── The nightly clean-up (its own job: section F's is one fixed command) ──
create or replace function study_private.qsets_cleanup()
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  -- A set that never got past reading its lecture.
  delete from public.study_qsets s
   where s.state = 'reading' and s.created_at < now() - interval '1 day'
     and not exists (select 1 from public.study_qset_requests r where r.set_id = s.id)
     and not exists (select 1 from public.study_qset_items i where i.set_id = s.id);
  -- A lecture set begun but never attached (the call between begin and
  -- attach died, and so did its abandon): shown as paused after 2 minutes,
  -- gone after an hour (it then stops counting toward the day's sets).
  delete from public.study_qsets s
   where s.kind = 'lecture' and s.state = 'making' and s.updated_at < now() - interval '1 hour'
     and not exists (select 1 from public.study_qset_requests r where r.set_id = s.id)
     and not exists (select 1 from public.study_qset_items i where i.set_id = s.id);
  delete from public.study_qset_attempts a where a.finished_at is null and a.started_at < now() - interval '365 days';
  delete from public.study_qset_marks k using public.study_qsets s where s.id = k.set_id and s.deleted_at is not null;
  delete from public.study_qsets s
   where s.deleted_at < now() - interval '30 days'
     and not exists (select 1 from public.study_qset_attempts a where a.set_id = s.id);
  if to_regclass('cron.job_run_details') is not null and to_regclass('cron.job') is not null then
    execute $c$delete from cron.job_run_details where jobid in (select jobid from cron.job where jobname = 'study-qsets-clean')
                and end_time < now() - interval '2 days'$c$;
  end if;
end;
$$;

-- ── Who may call what ──
revoke all on function study_private.qset_get(uuid), study_private.qset_facts(uuid),
  study_private.qset_paused(text, text, timestamptz, int, timestamptz), study_private.qset_is_open(uuid),
  study_private.qset_announce(uuid), study_private.qset_refresh(uuid), study_private.qset_rows(uuid, uuid, uuid, int),
  study_private.qset_attempt_open(uuid, uuid), study_private.qset_stamp(uuid, uuid, uuid[]), study_private.qset_item_from_bank(), study_private.qset_of_request(uuid),
  study_private.qset_for_similar(uuid, uuid, uuid, uuid, text, int), study_private.qset_add_items(uuid, uuid[]),
  study_private.qset_similar_done(uuid), study_private.qsets_cleanup(),
  study_private.notice_set_shared(uuid, uuid, uuid[], uuid, jsonb) from public;
revoke all on function public.study_qset_begin(uuid, jsonb, text, boolean, int, numeric, text),
  public.study_qset_attach(uuid, jsonb, jsonb, text), public.study_qset_abandon(uuid), public.study_qset_style(uuid, text, text),
  public.study_qset_autokeep(uuid[], text), public.study_qset_progress(uuid), public.study_qset_rename(uuid, text),
  public.study_qset_delete(uuid), public.study_qset_hide(uuid, boolean), public.study_qset_seen(uuid[]),
  public.study_qsets_shelf(uuid, uuid, int), public.study_qset_open(uuid), public.study_lecture_making(uuid),
  public.study_qset_room(uuid), public.study_qset_attempt_start(uuid),
  public.study_qset_answer(uuid, uuid, int, text, int, int), public.study_qset_answer_seq(uuid, uuid, int[], text, int, int),
  public.study_qset_attempt_finish(uuid), public.study_qset_stats(uuid), public.study_qset_names_pref(boolean)
  from public, anon;
-- begin, attach, style and autokeep need the server key inside; the grant only lets the op's call reach them.
grant execute on function public.study_qset_begin(uuid, jsonb, text, boolean, int, numeric, text),
  public.study_qset_attach(uuid, jsonb, jsonb, text), public.study_qset_abandon(uuid), public.study_qset_style(uuid, text, text),
  public.study_qset_autokeep(uuid[], text), public.study_qset_progress(uuid), public.study_qset_rename(uuid, text),
  public.study_qset_delete(uuid), public.study_qset_hide(uuid, boolean), public.study_qset_seen(uuid[]),
  public.study_qsets_shelf(uuid, uuid, int), public.study_qset_open(uuid), public.study_lecture_making(uuid),
  public.study_qset_room(uuid), public.study_qset_attempt_start(uuid),
  public.study_qset_answer(uuid, uuid, int, text, int, int), public.study_qset_answer_seq(uuid, uuid, int[], text, int, int),
  public.study_qset_attempt_finish(uuid), public.study_qset_stats(uuid), public.study_qset_names_pref(boolean)
  to authenticated;

-- ── Realtime: a set's state and its questions as they join (the
-- generating screen, the shelf). Never an attempt, a mark or an answer. ──
do $$
declare t text;
begin
  foreach t in array array['study_qsets', 'study_qset_items'] loop
    begin
      execute format('alter publication supabase_realtime add table public.%I', t);
    exception
      when duplicate_object then null;
      when undefined_object then raise notice 'no supabase_realtime publication: sets update on each open only';
    end;
  end loop;
end $$;

-- ── Every night at 03:29 (only with pg_cron) ──
do $$
begin
  if to_regnamespace('cron') is null then
    raise notice 'pg_cron is off: practice sets work, but nothing cleans them up at night. Integrations → Cron → enable pg_cron, then run this part again.';
  else
    perform cron.schedule('study-qsets-clean', '29 3 * * *', 'select study_private.qsets_cleanup()');
  end if;
end $$;

insert into study_private.schema_sections (section, version) values ('L', 1)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ════ END SECTION L ════

-- ════ BEGIN SECTION O · uploaded questions: sheets, forms, similar (package O) ════
--  docs/study/sheets.md; design-exams revision 2, §7; the decisions are in
--  docs/study/DECISIONS-2026-11-26.md ("Uploaded sheets").
--  A member uploads a past exam or an exercise sheet ("דף תרגילים"; a
--  question bank is a sheet with no lecture). A sheet is a study_exams row
--  with kind 'sheet': the same pages table, Storage path, queue, lease,
--  worker, review screen and ledger kind 'exam' as section S's past exams.
--
--  O 1 (this version, release A0): the kind and the one optional lecture of
--  an upload; the switch 'sheets' (off); "a new sheet" (study_sheet_create);
--  keying any choice item by hand, true/false and match included
--  (study_exam_key_set), with its undo; and three of section S's functions
--  redefined here (create or replace, the list is in sheets.md): the course
--  page lists each upload's kind and lecture, the library counts past exams
--  only, and a simulation takes past exams only and only their choice items.
--  The op exam_read keeps a sheet to 40 pages and checks the sheets line and
--  the headroom (study_sheet_room) before it calls S's study_exam_pages_done,
--  so release A0's sheets are read by the exam reader as they are. Sheets
--  are created with hide_from_profile, so the course's style examples never
--  learn from them.
--
--  O 2 (the sheet reader, open and numeric forms) and O 3 (similar
--  questions, a set of kind 'sheet' in section L) come later. Every
--  reference to L or R is guarded. Re-runnable; parts 1 to 10 run in order
--  (README), so O's definitions of S's functions win.

-- ── The kind and the lecture of an upload ──
alter table public.study_exams
  add column if not exists kind       text not null default 'exam',
  add column if not exists lecture_id uuid references public.study_lectures (id) on delete set null;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'study_exams_kind_x') then
    alter table public.study_exams add constraint study_exams_kind_x check (kind in ('exam', 'sheet'));
  end if;
end $$;
-- A member's insert (Q's grant) cannot name either: an exam is 'exam', a sheet is made by study_sheet_create.

-- The switch: off until Yoad turns it on (release A0); 'exams' must be on too.
insert into study_private.features (name) values ('sheets') on conflict (name) do nothing;

-- The key log keeps a true/false or match item's statements' answers too
-- (old_seq, new_seq), so "לבטל" brings them back.
alter table public.study_exam_key_log
  add column if not exists old_seq smallint[],
  add column if not exists new_seq smallint[];

-- ── "דף תרגילים": the sheet's row in its course, before its pages are uploaded ──
-- p_meta: {title (1-120 characters), lecture (optional: one lecture of the
-- course's group, not deleted), key_source (marked | separate | none)}.
-- No year, moed or minutes. Returns {exam_id, prefix}, as study_exam_create:
-- the pages go to <prefix>p<n>.jpg. 'not signed in', 'course not found',
-- 'off' (either switch), 'bad sheet', 'lecture not found'.
create or replace function public.study_sheet_create(p_course uuid, p_meta jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c   public.study_courses;
  v   uuid := gen_random_uuid();
  t   text;
  ks  text;
  lid uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then
    raise exception 'course not found';
  end if;
  if not study_private.feature_on('exams') or not study_private.feature_on('sheets') then raise exception 'off'; end if;
  if jsonb_typeof(coalesce(p_meta, '{}'::jsonb)) <> 'object' or jsonb_typeof(p_meta -> 'title') is distinct from 'string'
     or (p_meta -> 'lecture' is not null and jsonb_typeof(p_meta -> 'lecture') not in ('string', 'null'))
     or (p_meta -> 'key_source' is not null and jsonb_typeof(p_meta -> 'key_source') <> 'string') then
    raise exception 'bad sheet';
  end if;
  -- One space for every run of white space, as the course's key does.
  t := btrim(regexp_replace(p_meta ->> 'title', '\s+', ' ', 'g'));
  ks := coalesce(p_meta ->> 'key_source', 'none');
  if char_length(t) not between 1 and 120 or ks not in ('marked', 'separate', 'none')
     or coalesce(p_meta ->> 'lecture', '') !~ '^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})?$' then
    raise exception 'bad sheet';
  end if;
  lid := nullif(p_meta ->> 'lecture', '')::uuid;
  if lid is not null and not exists (select 1 from public.study_lectures l where l.id = lid and l.group_id = c.group_id and l.deleted_at is null) then
    raise exception 'lecture not found';
  end if;
  insert into public.study_exams (id, group_id, course, title, key_source, status, kind, lecture_id, hide_from_profile, created_by)
  values (v, c.group_id, c.name, t, ks, 'uploading', 'sheet', lid, true, auth.uid());
  return jsonb_build_object('exam_id', v, 'prefix', c.group_id || '/exams/' || v || '/');
end;
$$;

-- ── "לסמן תשובה" for any choice item of an upload ──
-- A one-answer item takes p_answer (p_seq null); a true/false item takes
-- p_seq, 1/0 per statement; a match item p_seq, a distinct option per prompt
-- (study_private.exam_key_fit). Both null clear the key. The change is
-- logged with the key it replaced (the statements' too) and its origin
-- becomes 'member'; explanations depend on the key, so they are cleared.
-- (Section S's study_set_exam_key stays for one-answer items.)
-- 'not signed in', 'question not found', 'off', 'in quiz', 'bad answer'.
create or replace function public.study_exam_key_set(p_question uuid, p_answer int, p_seq int[])
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  q     public.study_questions;
  k     public.study_question_keys;
  fit   jsonb;
  v_ans smallint;
  v_seq smallint[];
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into q from public.study_questions x where x.id = p_question for update;
  if not found or not coalesce(public.study_is_member(q.group_id), false) or q.source <> 'exam'
     or exists (select 1 from public.study_exams e where e.id = q.exam_id and e.deleted_at is not null) then
    raise exception 'question not found';
  end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  select * into k from public.study_question_keys x where x.question_id = p_question for update;
  if not found then raise exception 'question not found'; end if;
  if k.held_until > now() then raise exception 'in quiz'; end if;
  if p_answer is not null or p_seq is not null then
    if q.form not in ('one', 'tf', 'match') or (q.form = 'one' and p_seq is not null) or (q.form <> 'one' and p_answer is not null) then
      raise exception 'bad answer';
    end if;
    fit := study_private.exam_key_fit(q, p_answer, p_seq);
    if fit is null then raise exception 'bad answer'; end if;
    v_ans := (fit ->> 'answer')::smallint;
    v_seq := (select array_agg(x::smallint order by o) from jsonb_array_elements_text(fit -> 'seq') with ordinality t(x, o));
  end if;
  insert into public.study_exam_key_log (question_id, exam_id, old, new, origin_old, origin_new, conf_old, by_old, old_seq, new_seq)
  values (q.id, q.exam_id, k.answer, v_ans, k.key_origin, case when v_ans is not null or v_seq is not null then 'member' end,
          k.key_conf, k.key_by,
          case when q.form <> 'one' then coalesce(k.seq, '{}') end, case when q.form <> 'one' then coalesce(v_seq, '{}') end);
  update public.study_question_keys x
     set answer = v_ans, seq = v_seq, key_by = auth.uid(), key_at = now(), explanations = '{}', takeaway = '',
         key_origin = case when v_ans is not null or v_seq is not null then 'member' end, key_conf = null
   where x.question_id = p_question;
  update public.study_questions x set has_key = v_ans is not null or v_seq is not null where x.id = p_question;
  return jsonb_build_object('answer', v_ans, 'seq', to_jsonb(v_seq), 'origin', case when v_ans is not null or v_seq is not null then 'member' end);
end;
$$;

-- ── Redefined from section S: "לבטל" ──
-- S's text, with one branch more: a change study_exam_key_set logged on a
-- true/false or match item (its old_seq and new_seq, '{}' for none) brings
-- the statements' answers back too, and is 'changed' when they are no
-- longer what it left. Every other change undoes as in S.
create or replace function public.study_exam_key_undo(p_question uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  q public.study_questions;
  k public.study_question_keys;
  l public.study_exam_key_log;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into q from public.study_questions x where x.id = p_question for update;
  if not found or not public.study_is_member(q.group_id) or q.source <> 'exam' then raise exception 'question not found'; end if;
  select * into k from public.study_question_keys x where x.question_id = p_question for update;
  if k.held_until > now() then raise exception 'in quiz'; end if;
  select * into l from public.study_exam_key_log x
   where x.question_id = p_question and x.undo_of is null
     and not exists (select 1 from public.study_exam_key_log u where u.undo_of = x.id)
   order by x.id desc limit 1;
  if not found then raise exception 'nothing to undo'; end if;
  if l.new_seq is not null then
    -- A set item's hand key (O 1): the statements' answers and the origin.
    if (coalesce(k.seq, '{}'), k.key_origin) is distinct from (l.new_seq, l.origin_new) then raise exception 'changed'; end if;
    insert into public.study_exam_key_log (question_id, exam_id, old, new, origin_old, origin_new, conf_old, by_old, undo_of, old_seq, new_seq)
    values (q.id, q.exam_id, k.answer, l.old, k.key_origin, l.origin_old, k.key_conf, k.key_by, l.id, coalesce(k.seq, '{}'), l.old_seq);
    update public.study_question_keys x
       set answer = l.old, seq = nullif(l.old_seq, '{}'), key_origin = l.origin_old, key_conf = l.conf_old, key_by = l.by_old,
           key_at = now(), explanations = '{}', takeaway = ''
     where x.question_id = p_question;
    update public.study_questions x set has_key = l.old is not null or cardinality(l.old_seq) > 0 where x.id = p_question;
    return jsonb_build_object('answer', l.old, 'seq', to_jsonb(nullif(l.old_seq, '{}')), 'origin', l.origin_old);
  end if;
  if (k.answer, k.key_origin) is distinct from (l.new, l.origin_new) then raise exception 'changed'; end if;
  insert into public.study_exam_key_log (question_id, exam_id, old, new, origin_old, origin_new, conf_old, by_old, undo_of)
  values (q.id, q.exam_id, k.answer, l.old, k.key_origin, l.origin_old, k.key_conf, k.key_by, l.id);
  update public.study_question_keys x
     set answer = l.old, key_origin = l.origin_old, key_conf = l.conf_old, key_by = l.by_old, key_at = now(),
         explanations = '{}', takeaway = ''
   where x.question_id = p_question;
  update public.study_questions x set has_key = l.old is not null or k.seq is not null where x.id = p_question;
  return jsonb_build_object('answer', l.old, 'origin', l.origin_old);
end;
$$;

-- ── Redefined from section S: the course page ──
-- S's text, and each upload's kind ('exam' | 'sheet') and its lecture (null
-- when it has none, or that lecture was deleted or is not the group's).
create or replace function public.study_course_overview(p_course uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c     public.study_courses;
  today date := (now() at time zone 'Asia/Jerusalem')::date;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then
    raise exception 'course not found';
  end if;
  if not study_private.feature_on('courses') then raise exception 'off'; end if;
  return jsonb_build_object(
    'id', c.id, 'name', c.name, 'exam_date', c.exam_date,
    'days_left', case when c.exam_date is not null then c.exam_date - today end,
    'exam_minutes', c.exam_minutes, 'exam_n', c.exam_n,
    'lectures', (select count(*) from public.study_lectures l
                  where l.group_id = c.group_id and l.deleted_at is null and study_private.course_key(l.course) = c.name_key),
    'ready', (select count(*) from public.study_lectures l
               where l.group_id = c.group_id and l.deleted_at is null and l.status = 'ready' and study_private.course_key(l.course) = c.name_key),
    'exams', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'title', e.title, 'year', e.year, 'status', e.status,
                                                           'moed', e.moed, 'minutes', e.minutes, 'key_source', e.key_source,
                                                           'hidden', e.hide_from_profile, 'created_at', e.created_at,
                                                           'questions', (select count(*) from public.study_questions q
                                                                          where q.exam_id = e.id and q.retired_at is null),
                                                           'printed', study_private.exam_printed(e.id),
                                                           'kind', e.kind,
                                                           'lecture_id', (select l.id from public.study_lectures l
                                                                           where l.id = e.lecture_id and l.group_id = e.group_id and l.deleted_at is null))
                                        order by e.year desc nulls last, e.created_at desc), '[]'::jsonb)
                from public.study_exams e where e.group_id = c.group_id and study_private.course_key(e.course) = c.name_key
                 and e.deleted_at is null and not study_private.exam_stale(e)),
    'questions', (select count(*) from public.study_questions q join public.study_lectures l on l.id = q.lecture_id
                   where l.group_id = c.group_id and l.deleted_at is null and study_private.course_key(l.course) = c.name_key
                     and q.retired_at is null and q.hidden_at is null and q.stale_at is null and q.has_key));
end;
$$;

-- ── Redefined from section S: the library's course links ──
-- S's text; "exams" counts past exams only (a sheet is not an exam).
create or replace function public.study_courses_of(p_group uuid)
returns table (id uuid, name text, name_key text, exam_date date, exam_minutes int, exam_n int, lectures int, exams int)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not coalesce(public.study_is_member(p_group), false) then raise exception 'group not found'; end if;
  return query
  select c.id, c.name, c.name_key, c.exam_date, c.exam_minutes, c.exam_n,
         (select count(*)::int from public.study_lectures l
           where l.group_id = c.group_id and l.deleted_at is null and study_private.course_key(l.course) = c.name_key),
         (select count(*)::int from public.study_exams e where e.group_id = c.group_id and study_private.course_key(e.course) = c.name_key
           and e.deleted_at is null and e.kind = 'exam' and not study_private.exam_stale(e))
    from public.study_courses c
   where c.group_id = p_group and c.deleted_at is null
   order by c.name_key;
end;
$$;

-- ── Redefined from section S: "סימולציה" ──
-- S's text, for past exams only (a sheet is 'exam not found', OD9), and
-- only their choice items (one, tap, tf, match, order): study_mock_answer
-- takes a choice or choices, so an open or a numeric item (O 2) never
-- enters a simulation. The pool and its count are those items.
create or replace function public.study_mock_create(p_course uuid, p_kind text, p_exam uuid, p_n int default null,
  p_minutes int default null, p_unseen_only boolean default true)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c    public.study_courses;
  e    public.study_exams;
  pool int;
  n    int;
  ids  uuid[];
  mins int;
  v    uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.study_courses x where x.id = p_course;
  if not found or c.deleted_at is not null or not coalesce(public.study_is_member(c.group_id), false) then raise exception 'course not found'; end if;
  if not study_private.feature_on('exams') then raise exception 'off'; end if;
  if p_kind is distinct from 'exam' then raise exception 'bad kind'; end if;
  select * into e from public.study_exams x where x.id = p_exam;
  if not found or e.group_id <> c.group_id or e.deleted_at is not null or study_private.course_key(e.course) <> c.name_key
     or e.kind <> 'exam' then
    raise exception 'exam not found';
  end if;
  if e.status <> 'ready' then raise exception 'exam not ready'; end if;
  if p_n is not null and p_n not between 5 and 150 then raise exception 'bad questions'; end if;
  if p_minutes is not null and p_minutes not between 1 and 600 then raise exception 'bad minutes'; end if;
  select count(*) into pool from public.study_questions q
   where q.exam_id = e.id and q.retired_at is null and q.hidden_at is null and q.form in ('one', 'tap', 'tf', 'match', 'order');
  if pool < 5 then raise exception 'too few questions'; end if;
  n := least(coalesce(p_n, 150), pool, 150);
  select array_agg(x.id order by x.exam_no) into ids from (
    select q.id, q.exam_no from public.study_questions q
     where q.exam_id = e.id and q.retired_at is null and q.hidden_at is null and q.form in ('one', 'tap', 'tf', 'match', 'order')
     order by case when coalesce(p_unseen_only, true)
                    and exists (select 1 from public.study_answers a where a.question_id = q.id and a.user_id = auth.uid()) then 1 else 0 end,
              case when n < pool then random() else 0 end, q.exam_no
     limit n) x;
  mins := least(600, greatest(1, coalesce(p_minutes,
            -- the exam's minutes were for all it printed, open questions and items not saved included
            case when e.minutes is not null then ceil(e.minutes::numeric * n / greatest(pool, study_private.exam_printed(e.id), 1))::int end,
            case when c.exam_minutes is not null and c.exam_n is not null then ceil(c.exam_minutes::numeric * n / c.exam_n)::int end,
            ceil(n * 1.8)::int)));
  insert into public.study_mocks (group_id, course_id, kind, exam_id, question_ids, minutes, spec, created_by)
  values (c.group_id, c.id, 'exam', e.id, ids, mins,
          jsonb_build_object('n', n, 'pool', pool, 'unseen_only', coalesce(p_unseen_only, true)), auth.uid())
  returning id into v;
  return jsonb_build_object('mock', v, 'questions', n, 'minutes', mins, 'pool', pool, 'missing', '[]'::jsonb);
end;
$$;

-- ── The sheets line and the headroom (OD3, OD13) ──
-- What the op exam_read needs before a sheet is read, which a member cannot
-- read from the ledger or the private queue: whether the switch 'sheets' is
-- on, what reading sheets (their read, key and solve units) cost the group
-- this calendar month (UTC, as study_spent), and the group's whole spend
-- this month. The op refuses a sheet whose worst case passes the sheets
-- line ($6 a month, STUDY_SHEETS_MONTHLY_USD) or the room left under the 80%
-- line. A unit's cost is known when it finishes, so two sheets started
-- minutes apart may both pass (the design's accepted gap: one sheet's worst
-- case at most; the 80% line still holds).
create or replace function public.study_sheet_room(p_group uuid)
returns table (sheets_on boolean, sheets_usd numeric, spent_usd numeric)
language plpgsql stable security definer set search_path = public as $$
declare since timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
begin
  if auth.uid() is null or not coalesce(public.study_is_member(p_group), false) then raise exception 'forbidden'; end if;
  return query
  select study_private.feature_on('exams') and study_private.feature_on('sheets'),
         coalesce((select sum(j.cost_usd) from study_private.exam_jobs j join public.study_exams e on e.id = j.exam_id
                    where j.group_id = p_group and e.kind = 'sheet' and j.updated_at >= since), 0)::numeric,
         coalesce((select sum(u.cost_usd) from public.study_usage u where u.group_id = p_group and u.created_at >= since), 0)::numeric;
end;
$$;

revoke all on function public.study_sheet_create(uuid, jsonb), public.study_exam_key_set(uuid, int, int[]), public.study_sheet_room(uuid) from public, anon;
grant execute on function public.study_sheet_create(uuid, jsonb), public.study_exam_key_set(uuid, int, int[]), public.study_sheet_room(uuid) to authenticated;

insert into study_private.schema_sections (section, version) values ('O', 1)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ════ END SECTION O ════
